          <Card className="bg-slate-900 border-slate-700 p-6">
            <Trophy className="w-8 h-8 text-amber-400 mb-4" />
            <p className="text-slate-400 text-sm">IGJEN</p>
            <p className="text-4xl font-bold text-white">{stats.remaining}</p>
          </Card>
        </div>
      </div>
    </div>
  );
}

"use client";

import { createClient } from "@/lib/supabase/client";
import {
  Activity,
  LayoutDashboard,
  LogOut,
  Menu,
  RefreshCw,
  Server,
  Shield,
  UserCog,
  Users,
  X,
} from "lucide-react";
import { useTranslations } from "next-intl";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

export default function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const t = useTranslations("admin");
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [userEmail, setUserEmail] = useState("");
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Extract locale from pathname
  const locale = pathname.split("/")[1] || "no";

  useEffect(() => {
    const checkAdmin = async (retryCount = 0) => {
      const MAX_RETRIES = 3;
      const RETRY_DELAY = 500; // ms

      try {
        console.info(
          `[Admin Layout] Checking admin access (attempt ${retryCount + 1})...`,
        );
        const supabase = createClient();

        // First try to get session (more reliable than getUser)
        const {
          data: { session },
          error: sessionError,
        } = await supabase.auth.getSession();

        if (sessionError) {
          console.error("[Admin Layout] Session error:", sessionError);
        }

        // If no session, try getUser as fallback
        let user = session?.user;
        if (!user) {
          const {
            data: { user: authUser },
          } = await supabase.auth.getUser();
          user = authUser;
        }

        if (!user) {
          console.info("[Admin Layout] No user found");
          if (retryCount < MAX_RETRIES) {
            console.info(`[Admin Layout] Retrying in ${RETRY_DELAY}ms...`);
            setTimeout(() => checkAdmin(retryCount + 1), RETRY_DELAY);
            return;
          }
          console.info("[Admin Layout] Redirecting to login");
          const supportedLocales = ["no", "en", "th", "zh"];
          const safeLocale = supportedLocales.includes(locale) ? locale : "no";
          router.push(
            `/${safeLocale}/innlogging?error=admin_auth_required&next=${encodeURIComponent(pathname)}`,
          );
          return;
        }

        console.info("[Admin Layout] User found:", user.email);
        setUserEmail(user.email || "");

        // ADMIN EMAIL WHITELIST - Backup if database check fails
        const ADMIN_EMAILS = ["tomarnejensen@gmail.com", "admin@klarpakke.no"];

        // Check if user is in whitelist
        const isWhitelisted = ADMIN_EMAILS.includes(user.email || "");

        // Check role in public.profiles
        const { data: userData, error } = await supabase
          .from("profiles")
          .select("role")
          .eq("user_id", user.id)
          .single();

        if (error) {
          console.error("[Admin Layout] Profile fetch error:", error);
        }

        console.info(
          "[Admin Layout] User role:",
          userData?.role,
          "| Whitelisted:",
          isWhitelisted,
        );

        // Allow access if either role is admin OR email is whitelisted
        const hasAdminAccess = userData?.role === "admin" || isWhitelisted;

        if (!hasAdminAccess) {
          console.info(
            "[Admin Layout] User is not admin, redirecting to dashboard",
          );
          router.push(`/${locale}/dashboard?error=not_admin`);
          return;
        }

        // If whitelisted but role is not admin, try to update it
        if (isWhitelisted && userData?.role !== "admin") {
          console.info(
            "[Admin Layout] User whitelisted but role not set, updating...",
          );
          await supabase
            .from("profiles")
            .update({ role: "admin", updated_at: new Date().toISOString() })
            .eq("user_id", user.id);
        }

        console.info("[Admin Layout] Admin access granted");
        setIsAdmin(true);
        setLoading(false);
      } catch (err) {
        console.error("[Admin Layout] Unexpected error:", err);
        if (retryCount < MAX_RETRIES) {
          setTimeout(() => checkAdmin(retryCount + 1), RETRY_DELAY);
          return;
        }
        router.push(`/${locale}/innlogging?error=admin_error`);
      }
    };

    checkAdmin();
  }, [router, pathname]);

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (!isAdmin) return null;

  const navItems = [
    { href: `/${locale}/admin`, label: t("overview"), icon: LayoutDashboard },
    { href: `/${locale}/admin/users`, label: t("users"), icon: UserCog },
    { href: `/${locale}/admin/students`, label: t("students"), icon: Users },
    {
      href: `/${locale}/admin/sync-status`,
      label: t("tradeSync"),
      icon: RefreshCw,
    },
    {
      href: `/${locale}/admin/auto-trading/sessions`,
      label: "Trading Bots",
      icon: Activity,
    },
    { href: `/${locale}/admin/system`, label: t("system"), icon: Server },
    { href: `/${locale}/admin/settings`, label: t("settings"), icon: Shield },
  ];

  return (
    <div className="min-h-screen bg-slate-950 flex">
      {/* Mobile Menu Button */}
      <button
        onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        className="lg:hidden fixed top-4 left-4 z-50 p-2 bg-slate-800 rounded-lg text-white"
        aria-label="Toggle menu"
      >
        {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
      </button>

      {/* Sidebar - Desktop: always visible, Mobile: conditional */}
      <aside 
        className={`fixed lg:static inset-y-0 left-0 z-40 w-64 bg-slate-900 border-r border-slate-800 flex flex-col transform transition-transform duration-200 lg:transform-none ${
          mobileMenuOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"
        }`}
      >
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-xl font-bold text-white flex items-center gap-2">
            <span className="bg-blue-600 rounded p-1">🛡️</span>
            Admin
          </h1>
        </div>

        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          {navItems.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setMobileMenuOpen(false)}
                className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors min-h-[44px] ${
                  isActive
                    ? "bg-blue-600/10 text-blue-400"
                    : "text-slate-400 hover:text-white hover:bg-slate-800"
                }`}
              >
                <item.icon className="w-5 h-5" />
                {item.label}
              </Link>
            );
          })}
        </nav>

        {/* Logg ut - nederst i sidebar */}
        <div className="p-4 border-t border-slate-800 space-y-2">
          <div className="px-4 py-2">
            <p className="text-xs text-slate-500">{t("loggedInAs")}</p>
            <p className="text-sm text-slate-300 truncate">{userEmail}</p>
          </div>
          <button
            onClick={async () => {
              const supabase = createClient();
              await supabase.auth.signOut();
              router.push(`/${locale}/innlogging`);
            }}
            className="flex items-center gap-3 px-4 py-3 bg-yellow-600 text-white font-semibold rounded-full hover:bg-yellow-700 text-sm w-full transition-colors min-h-[44px]"
          >
            <LogOut className="w-5 h-5" />
            {t("logout")}
          </button>
        </div>
      </aside>

      {/* Overlay for mobile */}
      {mobileMenuOpen && (
        <div 
          className="lg:hidden fixed inset-0 bg-black/50 z-30"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-auto min-w-0">
        <div className="p-4 lg:p-8 pt-16 lg:pt-8">{children}</div>
      </main>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useLocale, useTranslations } from 'next-intl';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Lock, AlertCircle, Loader2, CheckCircle, ArrowLeft } from 'lucide-react';
import { createClient } from '@/lib/supabase/client';

export default function ClientResetPassword() {
  const router = useRouter();
  const locale = useLocale();
  const t = useTranslations('admin');

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [verifying, setVerifying] = useState(true);
  const [sessionValid, setSessionValid] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    // Supabase handles the token from the URL hash automatically
    // When the user clicks the reset link, Supabase sets up a session
    const checkSession = async () => {
      try {
        const supabase = createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (user) {
          setSessionValid(true);
        } else {
          setError('Ugyldig eller utløpt lenke. Be om en ny tilbakestillingslenke.')
        }
      } catch {
        setError('Kunne ikke verifisere lenken')
      } finally {
        setVerifying(false)
      }
    }

    checkSession()
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      setError('Passordene matcher ikke');
      return;
    }

    if (password.length < 8) {
      setError('Passordet må være minst 8 tegn');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const supabase = createClient();
      const { error: updateError } = await supabase.auth.updateUser({
        password,
      });

      if (updateError) {
        setError(updateError.message);
        return;
      }

      setSuccess(true);
    } catch (err) {
      setError('En feil oppstod. Prøv igjen.');
    } finally {
      setLoading(false);
    }
  };

  if (verifying) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md border-slate-700 bg-slate-800/50">
          <CardContent className="p-8 text-center">
            <Loader2 className="w-8 h-8 animate-spin mx-auto mb-4 text-blue-500" />
            <p className="text-slate-400">Verifiserer lenken...</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (success) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md border-slate-700 bg-slate-800/50">
          <CardHeader className="text-center">
            <div className="mx-auto w-12 h-12 bg-green-600/20 rounded-xl flex items-center justify-center mb-4">
              <CheckCircle className="w-6 h-6 text-green-500" />
            </div>
            <CardTitle className="text-white text-2xl">Passord oppdatert!</CardTitle>
            <CardDescription className="text-slate-400">
              Ditt nye passord er nå aktivt. Du kan logge inn med en gang.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Button
              className="w-full bg-blue-600 hover:bg-blue-700"
              asChild
            >
              <a href={`/${locale}/admin/login`}>
                Logg inn nå
              </a>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error && !sessionValid) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md border-slate-700 bg-slate-800/50">
          <CardHeader className="text-center">
            <div className="mx-auto w-12 h-12 bg-red-600/20 rounded-xl flex items-center justify-center mb-4">
              <AlertCircle className="w-6 h-6 text-red-500" />
            </div>
            <CardTitle className="text-white text-2xl">Ugyldig lenke</CardTitle>
            <CardDescription className="text-slate-400">
              {error}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Button
              variant="outline"
              className="w-full border-slate-600 text-slate-300"
              asChild
            >
              <a href={`/${locale}/admin/forgot-password`}>
                Be om ny lenke
              </a>
            </Button>
            <div className="text-center">
              <a
                href={`/${locale}/admin/login`}
                className="text-sm text-blue-400 hover:text-blue-300 flex items-center justify-center gap-1"
              >
                <ArrowLeft className="w-4 h-4" />
                Tilbake til login
              </a>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 flex items-center justify-center p-4">
      <Card className="w-full max-w-md border-slate-700 bg-slate-800/50">
        <CardHeader className="text-center">
          <div className="mx-auto w-12 h-12 bg-blue-600/20 rounded-xl flex items-center justify-center mb-4">
            <Lock className="w-6 h-6 text-blue-500" />
          </div>
          <CardTitle className="text-white text-2xl">{t('resetPassword')}</CardTitle>
          <CardDescription className="text-slate-400">
            {t('choosePassword')}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-1.5">
                Nytt passord
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                <Input
                  type="password"
                  placeholder="--------"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="pl-10 bg-slate-900 border-slate-700 text-white"
                  required
                  minLength={8}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-300 mb-1.5">
                Gjenta nytt passord
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                <Input
                  type="password"
                  placeholder="--------"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="pl-10 bg-slate-900 border-slate-700 text-white"
                  required
                />
              </div>
            </div>

            {error && (
              <Alert variant="destructive" className="bg-red-500/10 border-red-500/20">
                <AlertCircle className="h-4 w-4 text-red-500" />
                <AlertDescription className="text-red-400">{error}</AlertDescription>
              </Alert>
            )}

            <Button
              type="submit"
              className="w-full bg-blue-600 hover:bg-blue-700"
              disabled={loading}
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Oppdaterer...
                </>
              ) : (
                'Lagre nytt passord'
              )}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { 
  RefreshCw, 
  CheckCircle, 
  AlertCircle, 
  Clock, 
  Users,
  TrendingUp,
  Activity,
  Play
} from 'lucide-react';
import { toast } from 'sonner';

interface SyncLog {
  id: string;
  user_id: string;
  status: 'success' | 'error' | 'in_progress';
  message: string;
  trades_fetched: number;
  trades_saved: number;
  started_at: string;
  completed_at: string;
  created_at: string;
  user_email?: string;
}

interface SyncStats {
  totalUsers: number;
  usersWithApiKeys: number;
  last24Hours: {
    total: number;
    successful: number;
    failed: number;
  };
  totalTrades: number;
  recentSyncs: SyncLog[];
}

export default function SyncStatusPage() {
  const [stats, setStats] = useState<SyncStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);
  const supabase = createClient();

  const fetchStats = async () => {
    setLoading(true);
    try {
      // Get all sync logs
      const { data: logs, error: logsError } = await supabase
        .from('trade_sync_log')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(100);

      if (logsError) throw logsError;

      // Get user profiles for email lookup
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, email');

      const emailMap = new Map(profiles?.map(p => [p.id, p.email]) || []);

      // Enrich logs with emails
      const enrichedLogs = logs?.map(log => ({
        ...log,
        user_email: emailMap.get(log.user_id),
      })) || [];

      // Calculate stats
      const last24Hours = enrichedLogs.filter(
        log => new Date(log.created_at).getTime() > Date.now() - 24 * 60 * 60 * 1000
      );

      // Get unique users with API keys
      const { count: apiKeyCount } = await supabase
        .from('trading_api_keys')
        .select('*', { count: 'exact', head: true });

      // Get total trades
      const { count: tradesCount } = await supabase
        .from('auto_trades')
        .select('*', { count: 'exact', head: true });

      setStats({
        totalUsers: profiles?.length || 0,
        usersWithApiKeys: apiKeyCount || 0,
        last24Hours: {
          total: last24Hours.length,
          successful: last24Hours.filter(l => l.status === 'success').length,
          failed: last24Hours.filter(l => l.status === 'error').length,
        },
        totalTrades: tradesCount || 0,
        recentSyncs: enrichedLogs.slice(0, 20),
      });

    } catch (error) {
      toast.error('Failed to fetch sync stats');
    } finally {
      setLoading(false);
    }
  };

  const triggerManualSync = async () => {
    setTriggering(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Not authenticated');
      const { data: { session } } = await supabase.auth.getSession();

      const response = await fetch(
        `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/auto-sync-trades`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${session?.access_token}`,
            'Content-Type': 'application/json',
          },
        }
      );

      const result = await response.json();

      if (result.success) {
        toast.success(`Manual sync triggered! ${result.usersSuccess} users synced`);
        fetchStats();
      } else {
        toast.error(result.error || 'Sync failed');
      }
    } catch (error) {
      toast.error('Failed to trigger sync');
    } finally {
      setTriggering(false);
    }
  };

  useEffect(() => {
    fetchStats();

    // Realtime subscription i stedet for polling
    const channel = supabase
      .channel('admin-sync-status')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'trade_sync_log',
      }, () => {
        fetchStats();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, []);

  const formatTime = (date: string) => {
    return new Date(date).toLocaleString('no-NO');
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle className="w-5 h-5 text-green-400" />;
      case 'error':
        return <AlertCircle className="w-5 h-5 text-red-400" />;
      case 'in_progress':
        return <RefreshCw className="w-5 h-5 text-blue-400 animate-spin" />;
      default:
        return <Clock className="w-5 h-5 text-slate-400" />;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white">Trade Sync Status</h1>
          <p className="text-slate-400">Monitor auto-sync for all users</p>
        </div>
        <Button 
          onClick={triggerManualSync} 
          disabled={triggering}
          className="bg-blue-600 hover:bg-blue-700"
        >
          {triggering ? (
            <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
          ) : (
            <Play className="w-4 h-4 mr-2" />
          )}
          Trigger Manual Sync
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="bg-slate-900 border-slate-800">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-400 text-sm">Users with API</p>
                <p className="text-2xl font-bold text-white">
                  {stats?.usersWithApiKeys} / {stats?.totalUsers}
                </p>
              </div>
              <Users className="w-8 h-8 text-blue-400" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-400 text-sm">Last 24h Syncs</p>
                <p className="text-2xl font-bold text-white">
                  {stats?.last24Hours.total}
                </p>
              </div>
              <Activity className="w-8 h-8 text-green-400" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-400 text-sm">Success Rate</p>
                <p className="text-2xl font-bold text-green-400">
                  {stats?.last24Hours.total 
                    ? Math.round((stats.last24Hours.successful / stats.last24Hours.total) * 100)
                    : 0}%
                </p>
              </div>
              <TrendingUp className="w-8 h-8 text-green-400" />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900 border-slate-800">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-400 text-sm">Total Trades</p>
                <p className="text-2xl font-bold text-white">
                  {stats?.totalTrades.toLocaleString()}
                </p>
              </div>
              <TrendingUp className="w-8 h-8 text-emerald-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Recent Syncs */}
      <Card className="bg-slate-900 border-slate-800">
        <CardHeader>
          <CardTitle className="text-white">Recent Sync Activity</CardTitle>
          <CardDescription className="text-slate-400">
            Last 20 sync attempts across all users
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full">
