            </div>

            {/* Nivå-filter */}
            <div className="flex gap-2 flex-wrap">
              <Badge 
                variant={filterLevel === 'all' ? 'default' : 'outline'}
                className="cursor-pointer"
                onClick={() => setFilterLevel('all')}
