                Alle nivåer
              </Badge>
              <Badge 
                variant={filterLevel === 'beginner' ? 'default' : 'outline'}
                className={cn('cursor-pointer', filterLevel === 'beginner' && 'bg-green-600')}
                onClick={() => setFilterLevel('beginner')}
              >
                Nybegynner
