    // Helper function to format time ago
    const getTimeAgo = (minutes: number): string => {
        if (minutes < 60) {
            return minutes === 1 
                ? tAutoTrade('timeAgo.min', { n: minutes })
                : tAutoTrade('timeAgo.mins', { n: minutes });
        } else {
            const hours = Math.floor(minutes / 60);
