      const data = await response.json();

      if (data.verified) {
        setVerified(true);
        // Redirect to dashboard after 5 seconds
        setTimeout(() => {
          router.push(`/${locale}/dashboard`, { scroll: false });
        }, 5000);
      } else {
        throw new Error('Betaling ikke bekreftet');
