  const supabase = await createClient();
  const t = await getTranslations('courses');

  // Fetch course data
  const { data: course, error } = await supabase
    .from('courses')
    .select('*')
    .eq('slug', slug)
    .eq('is_published', true)
    .single();

  if (error || !course) {
    notFound();
  }

  // Check if user is enrolled (if authenticated)
