          </DialogHeader>
          <div className="space-y-4 pt-4">
            <Alert>
              <Shield className="h-4 w-4" />
              <AlertDescription>
                API-nøklene krypteres før lagring. Vi lagrer aldri nøklene i klartekst.
              </AlertDescription>
            </Alert>

            <div className="space-y-2">
              <Label>API Key</Label>
              <Input 
                type="password"
                value={binanceKeys.apiKey}
                onChange={(e) => setBinanceKeys({...binanceKeys, apiKey: e.target.value})}
                placeholder="Din Binance API Key"
              />
            </div>

            <div className="space-y-2">
              <Label>API Secret</Label>
              <Input 
                type="password"
                value={binanceKeys.apiSecret}
                onChange={(e) => setBinanceKeys({...binanceKeys, apiSecret: e.target.value})}
                placeholder="Din Binance API Secret"
              />
            </div>

            <div className="flex items-center justify-between">
              <Label>Bruk Testnet (paper trading)</Label>
              <Switch 
                checked={binanceKeys.isTestnet}
                onCheckedChange={(v) => setBinanceKeys({...binanceKeys, isTestnet: v})}
              />
            </div>

            {!binanceKeys.isTestnet && !tier.liveTrading && !trialStatus?.canUseLiveTrading && (
              <Alert variant="destructive">
                <Lock className="h-4 w-4" />
                <AlertDescription>
                  Live trading krever Bachelor-tier eller høyere
                </AlertDescription>
              </Alert>
            )}

            <Button 
              onClick={handleSaveBinanceKeys}
              className="w-full"
              disabled={!binanceKeys.apiKey || !binanceKeys.apiSecret}
            >
              Lagre og koble til
            </Button>

            <p className="text-xs text-slate-500 text-center">
              Du kan opprette API-nøkler i din{' '}
              <a 
                href="https://www.binance.com/en/my/settings/api-management" 
                target="_blank" 
                rel="noopener noreferrer"
                className="underline"
              >
                Binance-konto
              </a>
            </p>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import BinanceAPISettings from '@/components/dashboard/BinanceAPISettings';
import { createClient } from '@/lib/supabase/client';
import { Loader2 } from 'lucide-react';
import { useRouter, useParams } from 'next/navigation';

interface UserData {
  id: string;
  email: string;
  full_name: string | null;
}

export default function ClientDashboardSettings() {
  const router = useRouter();
  const params = useParams();
  const locale = params.locale as string;
  const supabase = createClient();
  const [user, setUser] = useState<UserData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) {
          setLoading(false);
          return;
        }
        setUser({
          id: user.id,
          email: user.email || '',
          full_name: user.user_metadata?.full_name || null,
        });
      } catch (error) {
        console.error('Error fetching user:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchUser();
  }, [supabase]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-12 h-12 animate-spin text-blue-500" />
      </div>
    );
  }

  if (!user) return null;

  return (
    <div className="min-h-screen bg-[#0F1118] py-8">
      <BinanceAPISettings user={user} />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { 
  FileText, 
  Download, 
  TrendingUp, 
  TrendingDown, 
  Calendar,
  PieChart,
  AlertCircle,
  CheckCircle,
  Info,
  FileSpreadsheet,
  Printer
} from 'lucide-react';
import { toast } from 'sonner';

interface TaxReport {
  year: number;
  totalTrades: number;
  totalBuyVolume: number;
  totalSellVolume: number;
  realizedProfitLoss: number;
  totalFees: number;
  tradesBySymbol: Record<string, {
    symbol: string;
    buyCount: number;
    sellCount: number;
    realizedProfitLoss: number;
  }>;
  quarterlyBreakdown: {
    q1: { profitLoss: number; trades: number };
    q2: { profitLoss: number; trades: number };
    q3: { profitLoss: number; trades: number };
    q4: { profitLoss: number; trades: number };
  };
  skatteetatenFormat: {
    year: number;
    formData: {
      post3_1_1: number;
      post3_1_2: number;
      post3_1_10: number;
    };
  };
}

export default function TaxReportClient() {
  const t = useTranslations('taxReport');
  const [year, setYear] = useState(new Date().getFullYear().toString());
  const [report, setReport] = useState<TaxReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [downloading, setDownloading] = useState<'csv' | 'pdf' | 'html' | null>(null);

  const availableYears = Array.from({ length: 5 }, (_, i) => (new Date().getFullYear() - i).toString());

  const fetchReport = async () => {
    setLoading(true);
    try {
      const response = await fetch(`/api/tax-report?year=${year}`);
      if (!response.ok) throw new Error('Failed to fetch report');
      const data = await response.json();
      setReport(data);
    } catch (error) {
      toast.error(t('errorFetching'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReport();
  }, [year]);

  const downloadFile = async (format: 'csv' | 'pdf' | 'html') => {
    setDownloading(format);
    try {
      const response = await fetch(`/api/tax-report?year=${year}&format=${format}`);
      if (!response.ok) throw new Error('Failed to download');

      if (format === 'pdf') {
        // Open PDF in new window for printing
        const html = await response.text();
        const printWindow = window.open('', '_blank');
        if (printWindow) {
          printWindow.document.write(html);
          printWindow.document.close();
          toast.success(t('pdfOpenInNewWindow'));
        }
      } else {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `skatterapport-${year}.${format}`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
        toast.success(t('downloadSuccess'));
      }
    } catch (error) {
      toast.error(t('downloadError'));
    } finally {
      setDownloading(null);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('no-NO', {
      style: 'currency',
      currency: 'NOK',
    }).format(amount);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-white mb-2">{t('title')}</h1>
        <p className="text-slate-400">{t('description')}</p>
      </div>

      {/* Year Selector & Downloads */}
      <Card className="bg-slate-900 border-slate-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            <Calendar className="w-5 h-5 text-blue-400" />
            {t('selectYear')}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-4 items-center">
            <Select value={year} onValueChange={setYear}>
              <SelectTrigger className="w-48 bg-slate-800 border-slate-700 text-white">
                <SelectValue placeholder={t('selectYear')} />
              </SelectTrigger>
              <SelectContent className="bg-slate-800 border-slate-700">
                {availableYears.map((y) => (
                  <SelectItem key={y} value={y} className="text-white hover:bg-slate-700">
                    {y}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <div className="flex gap-2">
