'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useRouter } from 'next/navigation';
import { 
  Users, 
  Shield, 
  Database, 
  Activity,
  AlertTriangle,
  TrendingUp,
  Settings,
  RefreshCw,
  Download,
  Trash2,
  CheckCircle,
  Pause,
  Search
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { Profile, Trade } from '@/types/database';
import { LucideIcon } from 'lucide-react';

const SUPER_ADMIN_EMAIL = 'tomarnejensen@gmail.com';

export default function ClientSuperAdmin() {
  const router = useRouter();
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeAutoTrading: 0,
    totalTrades: 0,
    adminUsers: 0
  });
  const [users, setUsers] = useState<Profile[]>([]);
  const [trades, setTrades] = useState<Array<Trade & { user?: { email?: string } }>>([]);
  type TradeWithUser = Trade & { user?: { email?: string } };
  const [sessions, setSessions] = useState<Array<{ id: string; phase?: string; status?: string; current_balance?: number; user?: { email?: string } }>>([]);

  useEffect(() => {
    checkAuthorization();
  }, []);

  const checkAuthorization = async () => {
    const supabase = createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user || user.email !== SUPER_ADMIN_EMAIL) {
      toast.error('Du har ikke tilgang til denne siden');
      router.push('/');
      return;
    }

    setIsAuthorized(true);
    loadAllData();
  };

  const loadAllData = async () => {
    setLoading(true);
    const supabase = createClient();

    try {
      const { count: userCount } = await supabase
        .from('profiles')
        .select('*', { count: 'exact', head: true });

      const { count: adminCount } = await supabase
        .from('profiles')
        .select('*', { count: 'exact', head: true })
        .eq('role', 'admin');

      const { count: tradingCount } = await supabase
        .from('trading_sessions')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'ACTIVE');

      const { count: tradesCount } = await supabase
        .from('trades')
        .select('*', { count: 'exact', head: true });

      setStats({
        totalUsers: userCount || 0,
        activeAutoTrading: tradingCount || 0,
        totalTrades: tradesCount || 0,
        adminUsers: adminCount || 0
      });

      const { data: usersData } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(50);

      setUsers(usersData || []);

      const { data: tradesData } = await supabase
        .from('trades')
        .select('*, user:user_id(email)')
        .order('executed_at', { ascending: false })
        .limit(50);

      setTrades(tradesData || []);

      const { data: sessionsData } = await supabase
        .from('trading_sessions')
        .select('*, user:user_id(email)')
        .order('created_at', { ascending: false });

      setSessions(sessionsData || []);

    } catch (error) {
      toast.error('Kunne ikke laste data');
    } finally {
      setLoading(false);
    }
  };

  const handleMakeAdmin = async (userId: string) => {
    const supabase = createClient();
    const { error } = await supabase
      .from('profiles')
      .update({ role: 'admin' })
      .eq('id', userId);

    if (error) toast.error('Kunne ikke oppdatere rolle');
    else {
      toast.success('Bruker er nå admin');
      loadAllData();
    }
  };

  const handlePauseTrading = async (sessionId: string) => {
    const supabase = createClient();
    await supabase
      .from('trading_sessions')
      .update({ status: 'PAUSED', paused_reason: 'ADMIN_OVERRIDE' })
      .eq('id', sessionId);

    toast.success('Trading pauset av admin');
    loadAllData();
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm('Er du sikker? Dette kan ikke angres!')) return;

    const supabase = createClient();
    await supabase.from('trades').delete().eq('user_id', userId);
    await supabase.from('trading_sessions').delete().eq('user_id', userId);
    await supabase.from('profiles').delete().eq('id', userId);

    toast.success('Bruker slettet');
    loadAllData();
  };

  const handleExportData = () => {
    const data = { users, trades, sessions, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `klarpakke-export-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    toast.success('Data eksportert');
  };

  const handleEmergencyStop = async () => {
    if (!confirm('STOPPE ALL TRADING FOR ALLE BRUKERE?')) return;

    const supabase = createClient();
    await supabase
      .from('trading_sessions')
      .update({ status: 'STOPPED', stopped_reason: 'ADMIN_EMERGENCY' })
      .eq('status', 'ACTIVE');

    toast.success('All trading stoppet!');
    loadAllData();
  };

  if (!isAuthorized) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950">
        <Card className="bg-slate-900 border-slate-800">
          <CardContent className="p-8 text-center">
            <Shield className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <h1 className="text-2xl font-bold text-white mb-2">Ingen Tilgang</h1>
            <p className="text-slate-400">Kun {SUPER_ADMIN_EMAIL} har tilgang.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      <header className="border-b border-slate-800 bg-slate-900/50 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="w-7 h-7 text-red-500" />
            <div>
              <h1 className="text-xl font-bold">Super Admin</h1>
              <p className="text-xs text-slate-400">{SUPER_ADMIN_EMAIL}</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <Button variant="outline" onClick={loadAllData} className="border-slate-700">
              <RefreshCw className="w-4 h-4 mr-2" />
              Oppdater
            </Button>
            <Button variant="outline" onClick={handleExportData} className="border-slate-700">
              <Download className="w-4 h-4 mr-2" />
              Eksporter
            </Button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
