          <StatCard title="Totalt Brukere" value={stats.totalUsers} icon={Users} color="text-blue-400" />
          <StatCard title="Aktive Auto-Trading" value={stats.activeAutoTrading} icon={Activity} color="text-green-400" />
          <StatCard title="Totale Trades" value={stats.totalTrades} icon={TrendingUp} color="text-amber-400" />
          <StatCard title="Admin Brukere" value={stats.adminUsers} icon={Shield} color="text-emerald-400" />
        </div>

        <Tabs defaultValue="users" className="space-y-4">
          <TabsList className="bg-slate-800 border-slate-700">
            <TabsTrigger value="users">Brukere ({users.length})</TabsTrigger>
            <TabsTrigger value="trades">Trades ({trades.length})</TabsTrigger>
