export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export interface MarketplaceListing {
  id: string;
  sellerId: string;
  strategyId: string | null;
  title: string;
  description: string | null;
  priceModel: "free" | "subscription" | "one_time";
  priceNok: number;
  backtestSummary: Record<string, unknown>;
  category: string | null;
  status: "draft" | "published" | "archived";
  subscriberCount: number;
  rating: number;
  reviewCount: number;
  createdAt: string;
  updatedAt: string;
  // Joined fields from seller
  sellerName?: string;
  sellerAvatar?: string | null;
  // Risk level derived from strategy
  riskLevel?: "low" | "medium" | "high";
  // Performance metrics from backtest
  winRate?: number;
  pnl30d?: number;
}

export interface MarketplaceListingsResponse {
  listings: MarketplaceListing[];
  total: number;
  page: number;
  limit: number;
}

export async function GET(
  request: NextRequest,
): Promise<NextResponse<MarketplaceListingsResponse | { error: string }>> {
  try {
    // Parse query parameters
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get("page") || "1", 10);
    const limit = Math.min(parseInt(searchParams.get("limit") || "20", 10), 100);
    const offset = (page - 1) * limit;
    const riskLevel = searchParams.get("risk") as
      | "low"
      | "medium"
      | "high"
      | null;
    const sortBy = searchParams.get("sort") || "performance"; // 'performance', 'newest', 'rating'
    const category = searchParams.get("category");

    // Try to get authenticated user (optional)
    let userId: string | null = null;
    try {
      const authClient = createServerClient(
        request,
        NextResponse.next(),
      );
      const { data } = await authClient.auth.getUser();
      if (data.user) {
        userId = data.user.id;
      }
    } catch {
      // Not authenticated, continue as public
    }

    // Create public Supabase client
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    );

    // Build query for marketplace_listings
    let query = supabase
      .from("marketplace_listings")
      .select("*, profiles:seller_id(display_name, avatar_url)", {
        count: "exact",
      })
      .eq("status", "published");

    // Apply filters
    if (category) {
      query = query.eq("category", category);
    }

    // Apply sorting
    if (sortBy === "performance") {
      query = query.order("rating", { ascending: false });
    } else if (sortBy === "newest") {
      query = query.order("created_at", { ascending: false });
    } else if (sortBy === "rating") {
      query = query.order("rating", { ascending: false });
    }

    // Apply pagination
    query = query.range(offset, offset + limit - 1);

    const { data, error, count } = await query;

    if (error) {
      console.error("Error fetching marketplace listings:", error);

      // Fallback: return user_strategies with is_marketplace_listed = true
      const { data: fallbackData, error: fallbackError } = await supabase
        .from("user_strategies")
        .select("*, profiles:user_id(display_name, avatar_url)")
        .eq("is_marketplace_listed", true)
        .eq("is_public", true)
        .range(offset, offset + limit - 1);

      if (fallbackError) {
        return NextResponse.json(
          { error: "Failed to fetch marketplace listings" },
          { status: 500 },
        );
      }

      // Map fallback data to MarketplaceListing format
      const listings: MarketplaceListing[] =
        fallbackData?.map((item) => {
          const profiles = item.profiles as
            | { display_name: string; avatar_url: string | null }
            | undefined;
          return {
            id: item.id,
            sellerId: item.user_id,
            strategyId: item.id,
            title: `${item.strategy_type || "Strategy"} - ${profiles?.display_name || "Creator"}`,
            description: null,
            priceModel: "free",
            priceNok: 0,
            backtestSummary: item.strategy_config || {},
            category: item.strategy_type,
            status: "published",
            subscriberCount: item.subscriber_count || 0,
            rating: 0,
            reviewCount: 0,
            createdAt: item.created_at,
            updatedAt: item.updated_at,
            sellerName: profiles?.display_name || "Anonym Creator",
            sellerAvatar: profiles?.avatar_url,
            riskLevel: getRiskLevel(item.strategy_type),
            winRate: 0,
            pnl30d: 0,
          };
        }) || [];

      return NextResponse.json({
        listings,
        total: listings.length,
        page,
        limit,
      });
    }

    // Map data to MarketplaceListing format
    const listings: MarketplaceListing[] =
      data?.map((item) => {
        const profiles = item.profiles as
          | { display_name: string; avatar_url: string | null }
          | undefined;
        return {
          id: item.id,
          sellerId: item.seller_id,
          strategyId: item.strategy_id,
          title: item.title,
          description: item.description,
          priceModel: item.price_model,
          priceNok: item.price_nok,
          backtestSummary: item.backtest_summary || {},
          category: item.category,
          status: item.status,
          subscriberCount: item.subscriber_count || 0,
          rating: item.rating || 0,
          reviewCount: item.review_count || 0,
          createdAt: item.created_at,
          updatedAt: item.updated_at,
          sellerName: profiles?.display_name || "Anonym Creator",
          sellerAvatar: profiles?.avatar_url,
          riskLevel: getRiskLevelFromBacktest(item.backtest_summary),
          winRate: item.backtest_summary?.win_rate || 0,
          pnl30d: item.backtest_summary?.pnl_30d || 0,
        };
      }) || [];

    // Filter by risk level if specified
    let filteredListings = listings;
    if (riskLevel) {
      filteredListings = listings.filter((l) => l.riskLevel === riskLevel);
    }

    return NextResponse.json({
      listings: filteredListings,
      total: count || 0,
      page,
      limit,
    });
  } catch (error) {
    console.error("Error in /api/marketplace/listings:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

// Helper function to determine risk level from strategy type
function getRiskLevel(strategyType: string | null): "low" | "medium" | "high" {
  if (!strategyType) return "medium";
  const type = strategyType.toLowerCase();
  if (type.includes("dca") || type.includes("trygg")) return "low";
  if (type.includes("trend") || type.includes("balansert") || type.includes("grid"))
    return "medium";
  if (type.includes("multi") || type.includes("aktiv") || type.includes("aggressiv"))
    return "high";
  return "medium";
}

// Helper function to determine risk level from backtest summary
function getRiskLevelFromBacktest(
  backtest: Record<string, unknown> | null,
): "low" | "medium" | "high" {
  if (!backtest) return "medium";
  const volatility = (backtest.volatility as number) || 0;
  if (volatility < 0.1) return "low";
  if (volatility > 0.3) return "high";
  return "medium";
}

/**
 * Trading Mode API
 * GET: Hent nåværende trading mode og Binance-tilkobling
 * POST: Bytt mellom paper og live trading
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

/**
 * GET: Hent trading mode status
 */
export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json(
        { error: 'Uautorisert', code: 'AUTH_REQUIRED' },
        { status: 401 }
      );
    }

    // Hent brukerprofil med trading info
    const { data: profile, error } = await supabase
      .from('user_profiles')
      .select('trading_mode, binance_api_key_encrypted, paper_trades_count, exchange_connected')
      .eq('id', user.id)
      .single();

    if (error) {
      console.error('Error fetching trading mode:', error);
      return NextResponse.json(
        { error: 'Kunne ikke hente trading mode' },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      mode: profile?.trading_mode || 'paper',
      canSwitchToLive: !!profile?.binance_api_key_encrypted,
      binanceConnected: !!profile?.binance_api_key_encrypted,
      paperTradesCount: profile?.paper_trades_count || 0,
    });

  } catch (error) {
    console.error('Error in GET /api/trading/mode:', error);
    return NextResponse.json(
      { error: 'Intern serverfeil' },
      { status: 500 }
    );
  }
}

/**
 * POST: Bytt trading mode
 */
export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json(
        { error: 'Uautorisert', code: 'AUTH_REQUIRED' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { mode } = body;

    // Valider mode
    if (!mode || !['paper', 'live'].includes(mode)) {
      return NextResponse.json(
        { error: 'Ugyldig trading mode. Må være "paper" eller "live"', code: 'INVALID_MODE' },
        { status: 400 }
      );
    }

    // Hvis bytte til live, sjekk at Binance er koblet til
    if (mode === 'live') {
      const { data: profile } = await supabase
        .from('user_profiles')
        .select('binance_api_key_encrypted')
        .eq('id', user.id)
        .single();

      if (!profile?.binance_api_key_encrypted) {
        return NextResponse.json(
          { 
            error: 'Binance API ikke tilkoblet. Koble til Binance først.',
            code: 'BINANCE_NOT_CONNECTED'
          },
          { status: 400 }
        );
      }

      // Sjekk tier-tilgang for live trading
      const { data: entitlements } = await supabase.rpc('get_user_entitlements', {
        p_user_id: user.id,
      });

      if (!entitlements?.[0]?.auto_trade_allow_live) {
        return NextResponse.json(
          { 
            error: 'Live trading krever Bachelor-tier eller høyere',
            code: 'TIER_LIMIT',
            required: 'bachelor',
            current: entitlements?.[0]?.subscription_tier || 'student'
          },
          { status: 403 }
        );
      }
    }

    // Oppdater trading mode
    const { error } = await supabase
      .from('user_profiles')
      .update({ 
        trading_mode: mode,
        updated_at: new Date().toISOString(),
      })
      .eq('id', user.id);

    if (error) {
      console.error('Error updating trading mode:', error);
      return NextResponse.json(
        { error: 'Kunne ikke oppdatere trading mode' },
        { status: 500 }
      );
    }

    // Logg hendelsen
    await supabase.from('audit_logs').insert({
      user_id: user.id,
      action: 'TRADING_MODE_CHANGED',
      details: { new_mode: mode },
      created_at: new Date().toISOString(),
    });

    return NextResponse.json({
      success: true,
      message: `Byttet til ${mode} trading`,
      mode,
    });

  } catch (error) {
    console.error('Error in POST /api/trading/mode:', error);
    return NextResponse.json(
      { error: 'Intern serverfeil' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

const priceCache = new Map<string, { price: number; timestamp: number }>();
const CACHE_TTL_MS = 2000;

export async function GET(request: NextRequest) {
  const symbol = request.nextUrl.searchParams.get("symbol") || "BTCUSDT";

  const cached = priceCache.get(symbol);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
    return NextResponse.json({ symbol, price: cached.price, cached: true });
  }

  try {
    const response = await fetch(
      `https://api.binance.com/api/v3/ticker/price?symbol=${symbol.toUpperCase()}`,
      { signal: AbortSignal.timeout(5000) },
    );

    if (!response.ok) {
      throw new Error(`Binance API error: ${response.status}`);
    }

    const data = await response.json();
    const price = parseFloat(data.price);

    priceCache.set(symbol, { price, timestamp: Date.now() });

    return NextResponse.json({ symbol, price, cached: false });
  } catch (error) {
    const cached = priceCache.get(symbol);
    if (cached) {
      return NextResponse.json({
        symbol,
        price: cached.price,
        cached: true,
        stale: true,
      });
    }

    return NextResponse.json(
      { error: "Failed to fetch price" },
      { status: 502 },
    );
  }
}

