import { createClient } from "@/lib/supabase/server";
import { NextResponse } from "next/server";
import { getErrorMessage } from "@/lib/utils/error";

export const dynamic = "force-dynamic";

export async function GET() {
  const status = {
    env: {
      NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL
        ? `${process.env.NEXT_PUBLIC_SUPABASE_URL.substring(0, 25)}...`
        : false,
      NEXT_PUBLIC_SUPABASE_ANON_KEY:
        !!process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
      PERPLEXITY_API_KEY: !!process.env.PERPLEXITY_API_KEY,
    },
    connection: false,
    tables: {
      users: false,
      leagues: false,
      push_subscriptions: false,
    },
    error: null as string | null,
  };

  try {
    const supabase = await createClient();

    // Check connection by fetching a public table (or users if RLS allows)
    // We try to fetch 1 row from 'users'
    const { data: users, error: usersError } = await supabase
      .from("users")
      .select("count")
      .limit(1);

    if (!usersError) {
      status.connection = true;
      status.tables.users = true;
    } else {
      console.error("Users table check failed:", getErrorMessage(usersError));
    }

    // Check leagues
    const { error: leaguesError } = await supabase
      .from("leagues")
      .select("count")
      .limit(1);
    if (!leaguesError) status.tables.leagues = true;

    // Check push_subscriptions
    const { error: pushError } = await supabase
      .from("push_subscriptions")
      .select("count")
      .limit(1);
    if (!pushError) status.tables.push_subscriptions = true;

    return NextResponse.json(status);
  } catch (err: unknown) {
    status.error = getErrorMessage(err);
    return NextResponse.json(status, { status: 500 });
  }
}

/**
 * POST /api/webhooks/resend
 * 
 * Handle Resend webhook events for email delivery tracking
 * https://resend.com/docs/dashboard/webhooks
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { Webhook } from 'svix';

const WEBHOOK_SECRET = process.env.RESEND_WEBHOOK_SECRET;

// Supabase admin client
const getSupabase = () => {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  );
};

export async function POST(req: NextRequest) {
  try {
    const payload = await req.text();
    const headers = req.headers;

    // Verify webhook signature if secret is configured
    if (WEBHOOK_SECRET) {
      const svixId = headers.get('svix-id');
      const svixTimestamp = headers.get('svix-timestamp');
      const svixSignature = headers.get('svix-signature');

      if (!svixId || !svixTimestamp || !svixSignature) {
        console.error('[Resend Webhook] Missing svix headers');
        return NextResponse.json(
          { error: 'Missing webhook headers' },
          { status: 400 }
        );
      }

      const wh = new Webhook(WEBHOOK_SECRET);
      try {
        wh.verify(payload, {
          'svix-id': svixId,
          'svix-timestamp': svixTimestamp,
          'svix-signature': svixSignature,
        });
      } catch (err) {
        console.error('[Resend Webhook] Invalid signature:', err);
        return NextResponse.json(
          { error: 'Invalid signature' },
          { status: 400 }
        );
      }
    }

    const event = JSON.parse(payload);
    const { type, data } = event;

    console.log(`[Resend Webhook] Event: ${type}`, data);

    const supabase = getSupabase();

    switch (type) {
      case 'email.sent': {
        // Email was sent successfully
        await supabase
          .from('email_log')
          .update({
            status: 'sent',
            sent_at: new Date().toISOString(),
          })
          .eq('resend_id', data.id);
        break;
      }

      case 'email.delivered': {
        // Email was delivered to recipient
        await supabase
          .from('email_log')
          .update({
            status: 'delivered',
            delivered_at: new Date().toISOString(),
          })
          .eq('resend_id', data.id);
        break;
      }

      case 'email.delivery_delayed': {
        // Email delivery delayed (temporary issue)
        console.log(`[Resend Webhook] Delivery delayed for ${data.id}`);
        break;
      }

      case 'email.bounced': {
        // Email bounced
        await supabase
          .from('email_log')
          .update({
            status: 'bounced',
            error_message: data.reason || 'Bounced',
          })
          .eq('resend_id', data.id);

        // Optionally: Mark user email as invalid
        console.error(`[Resend Webhook] Email bounced: ${data.to}`, data.reason);
        break;
      }

      case 'email.complained': {
        // User marked email as spam
        await supabase
          .from('email_log')
          .update({
            status: 'failed',
            error_message: 'User marked as spam',
          })
          .eq('resend_id', data.id);

        // Disable marketing emails for this user
        const { data: logEntry } = await supabase
          .from('email_log')
          .select('user_id')
          .eq('resend_id', data.id)
          .single();

        if (logEntry?.user_id) {
          await supabase
            .from('email_preferences')
            .update({ marketing_emails: false })
            .eq('user_id', logEntry.user_id);

          console.log(`[Resend Webhook] Disabled marketing emails for user ${logEntry.user_id}`);
        }
        break;
      }

      case 'email.opened': {
        // User opened email
        console.log(`[Resend Webhook] Email opened: ${data.id}`);
        break;
      }

      case 'email.clicked': {
        // User clicked link in email
        console.log(`[Resend Webhook] Link clicked in email: ${data.id}, link: ${data.link}`);
        break;
      }

      default:
        console.log(`[Resend Webhook] Unhandled event type: ${type}`);
    }

    return NextResponse.json({ received: true });

  } catch (error) {
    console.error('[Resend Webhook] Error:', error);
    return NextResponse.json(
      { error: 'Webhook processing failed' },
      { status: 500 }
    );
  }
}

