'use client'

import { Bell, BellOff, Loader2 } from 'lucide-react'
import { usePushNotifications } from '@/lib/pwa'

interface PushNotificationSettingsProps {
  userId: string | null
}

export function PushNotificationSettings({ userId }: PushNotificationSettingsProps) {
  const {
    isSupported,
    permission,
    isSubscribed,
    subscribe,
    unsubscribe,
  } = usePushNotifications(userId)

  const handleToggle = async () => {
    try {
      if (isSubscribed) {
        await unsubscribe()
      } else {
        await subscribe()
      }
    } catch (error) {
      console.error('Toggle failed:', error)
    }
  }

  if (!isSupported) {
    return (
      <div className="bg-gray-800/50 rounded-lg p-4">
        <div className="flex items-center gap-3">
          <BellOff className="w-5 h-5 text-gray-500" />
          <div>
            <p className="text-gray-400 font-medium">Push-varsler ikke støttet</p>
            <p className="text-gray-500 text-sm">
              Din nettleser støtter ikke push-varsler. Prøv Chrome eller Safari.
            </p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-gray-800/50 rounded-lg p-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${
            isSubscribed ? 'bg-green-500/20' : 'bg-gray-700'
          }`}>
            <Bell className={`w-5 h-5 ${isSubscribed ? 'text-green-400' : 'text-gray-400'}`} />
          </div>
          <div>
            <p className="text-white font-medium">Push-varsler</p>
            <p className="text-gray-400 text-sm">
              {isSubscribed 
                ? 'Du mottar varsler om nye kurs og webinarer' 
                : 'Få varsler om nye kurs og webinarer'}
            </p>
          </div>
        </div>

        <button
          onClick={handleToggle}
          disabled={permission === 'denied'}
          className={`relative w-14 h-8 rounded-full transition-colors ${
            isSubscribed ? 'bg-green-500' : 'bg-gray-600'
          } ${permission === 'denied' ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <span
            className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-transform ${
              isSubscribed ? 'left-7' : 'left-1'
            }`}
          />
        </button>
      </div>

      {permission === 'denied' && (
        <p className="mt-3 text-amber-400 text-sm">
          Du har blokkert varsler. Endre dette i nettleserinnstillingene for å aktivere.
        </p>
      )}

      {permission === 'default' && !isSubscribed && (
        <p className="mt-3 text-gray-400 text-sm">
          Klikk på bryteren for å tillate varsler fra Klarpakke.
        </p>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';


interface Signal {
  id: string;
  title?: string;
  symbol?: string;
  direction?: string;
  signal_type?: string;
  price?: number;
  created_at: string;
  confidence?: number;
  status?: string;
  description?: string;
}



interface SignalTableProps {
  onRefresh?: () => void;
}

type FilterType = 'all' | 'pending' | 'approved' | 'rejected';

const filterLabels: Record<FilterType, string> = {
  all: 'Alle',
  pending: 'Venter',
  approved: 'Godkjent',
  rejected: 'Avslått',
};

const statusLabels: Record<string, string> = {
  pending: 'Venter',
  approved: 'Godkjent',
  rejected: 'Avslått',
};

export default function SignalTable({ onRefresh }: SignalTableProps) {
  const [signals, setSignals] = useState<Signal[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<FilterType>('all');

  useEffect(() => {
    fetchSignals();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchSignals = async () => {
    setIsLoading(true);
    setError('');

    try {
      let query = supabase.from('signals').select('*');

      if (filter !== 'all') {
        query = query.eq('status', filter);
      }

      const { data, error: fetchError } = await query.order('created_at', {
        ascending: false,
      });

      if (fetchError) {
        setError('Kunne ikke laste signaler');
        console.error('Fetch error:', fetchError);
        return;
      }

      setSignals(data || []);
    } catch (err) {
      setError('En feil oppstod under henting av data');
      console.error('Error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFilterChange = (newFilter: FilterType) => {
    setFilter(newFilter);
    setSignals([]);
    fetchSignals();
  };

  const getStatusBadgeClass = (status: string | undefined) => {
    const classes: Record<string, string> = {
      pending: 'kp-badge-pending',
      approved: 'kp-badge-approved',
      rejected: 'kp-badge-rejected',
    };
    return classes[status];
  };

  const getDirectionBadgeClass = (direction: string | undefined) => {
    return direction === 'long' ? 'kp-badge-info' : 'kp-badge-error';
  };

  return (
    <div id="signals-list" className="kp-flex kp-flex-col kp-gap-4">
      {/* Filters */}
      <div id="signals-filter" className="kp-flex kp-gap-2" style={{ flexWrap: 'wrap' }}>
        {(['all', 'pending', 'approved', 'rejected'] as const).map((f) => (
          <button
            key={f}
            onClick={() => handleFilterChange(f)}
            className={`kp-button ${filter === f ? 'kp-button-primary' : 'kp-button-secondary'}`}
          >
            {filterLabels[f]}
          </button>
        ))}
      </div>

      {/* Error message */}
      {error && (
        <div className="kp-alert kp-alert-error">
          <svg className="kp-alert-icon" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
          <div className="kp-alert-content">
            <div className="kp-alert-message">{error}</div>
          </div>
        </div>
      )}

      {/* Loading state */}
      {isLoading && (
        <div id="signals-loading" className="kp-flex kp-flex-col kp-items-center kp-justify-center" style={{ padding: 'var(--kp-space-12)' }}>
          <span className="kp-spinner kp-spinner-lg" style={{ color: 'var(--kp-primary)' }} />
          <p className="kp-text-secondary kp-mt-4">Laster signaler...</p>
        </div>
      )}

      {/* Empty state */}
      {!isLoading && signals.length === 0 && (
        <div className="kp-card" style={{ textAlign: 'center', padding: 'var(--kp-space-12)' }}>
          <p className="kp-text-secondary kp-mb-2">Ingen signaler funnet</p>
          <p className="kp-text-sm kp-text-muted">
            Signaler vises her når de er opprettet
          </p>
        </div>
      )}

      {/* Signal cards */}
      {!isLoading && signals.length > 0 && (
        <div className="kp-table-responsive">
          <table className="kp-table">
            <thead>
              <tr>
                <th className="signal-asset">Tittel</th>
                <th className="signal-direction">Retning</th>
                <th>Selvtillit</th>
                <th className="signal-status">Status</th>
                <th className="signal-time">Dato</th>
              </tr>
            </thead>
            <tbody>
              {signals.map((signal) => (
                <tr key={signal.id} className="signal-card">
                  <td className="signal-asset kp-font-medium">
                    {signal.title || 'Ingen tittel'}
                  </td>
                  <td className="signal-direction">
                    <span className={`kp-badge ${getDirectionBadgeClass(signal.direction)}`}>
                      {signal.direction === 'long' ? 'Long' : 'Short'}
                    </span>
                  </td>
                  <td>
                    <div className="kp-flex kp-items-center kp-gap-2">
                      <div
                        style={{
                          width: '3rem',
                          height: '0.5rem',
                          backgroundColor: 'var(--kp-bg-tertiary)',
                          borderRadius: 'var(--kp-radius-full)',
                          overflow: 'hidden',
                        }}
                      >
                        <div
                          style={{
                            height: '100%',
                            width: `${signal.confidence}%`,
                            backgroundColor: 'var(--kp-primary)',
                          }}
                        />
                      </div>
                      <span className="kp-text-sm kp-font-medium">
                        {signal.confidence}%
                      </span>
                    </div>
                  </td>
                  <td className="signal-status">
                    <span className={`kp-badge ${getStatusBadgeClass(signal.status)}`}>
                      {statusLabels[signal.status || 'pending']}
                    </span>
                  </td>
                  <td className="signal-time kp-text-secondary">
                    {new Date(signal.created_at).toLocaleDateString('no-NO')}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useLocale } from 'next-intl'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Lock, AlertCircle, Shield } from 'lucide-react'
import { createClient } from '@/lib/supabase/client'

interface AdminLoginGateProps {
  children: React.ReactNode
}

export function AdminLoginGate({ children }: AdminLoginGateProps) {
  const locale = useLocale()
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    checkAdmin()
  }, [])

  const checkAdmin = async () => {
    try {
      const supabase = createClient()
      const { data: { user } } = await supabase.auth.getUser()

      if (!user) {
        setIsAuthenticated(false)
        setIsLoading(false)
        return
      }

      const { data: profile } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', user.id)
        .single()

      setIsAuthenticated(profile?.role === 'admin')
    } catch (err) {
      setError('Kunne ikke verifisere tilgang')
      setIsAuthenticated(false)
    } finally {
      setIsLoading(false)
    }
  }

  const handleLogout = async () => {
    const supabase = createClient()
    await supabase.auth.signOut()
    setIsAuthenticated(false)
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full" />
      </div>
    )
  }

  if (isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900">
        <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-sm sticky top-0 z-50">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Shield className="w-6 h-6 text-blue-500" />
              <h1 className="text-xl font-bold text-white">Admin Dashboard</h1>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleLogout}
              className="border-slate-700 text-slate-300 hover:bg-slate-800"
            >
              Logg ut
            </Button>
          </div>
        </header>

        <main className="p-4 sm:p-6 lg:p-8">
          {children}
        </main>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <Card className="w-full max-w-md border-slate-700 bg-slate-800/50">
        <CardHeader className="text-center">
          <div className="mx-auto w-12 h-12 bg-blue-600/20 rounded-xl flex items-center justify-center mb-4">
            <Lock className="w-6 h-6 text-blue-500" />
          </div>
          <CardTitle className="text-white text-2xl">Admin Login</CardTitle>
          <CardDescription className="text-slate-400">
            Logg inn via <a href={`/${locale}/admin/login`} className="text-blue-400 hover:text-blue-300">admin-innlogging</a> for å fortsette.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {error && (
            <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-500 mt-0.5" />
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}
          <Button
            className="w-full bg-blue-600 hover:bg-blue-700 mt-4"
            onClick={() => window.location.href = '/admin/login'}
          >
            Gå til innlogging
          </Button>
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import {
    Bell,
    Mail,
    Send,
    CheckCircle,
    AlertCircle,
    X,
    Eye
} from 'lucide-react'

interface Notification {
    id: string
    title: string
    message: string
    type: 'info' | 'success' | 'warning' | 'error'
    priority: 'low' | 'normal' | 'high' | 'urgent'
    read: boolean
    action_url?: string
    created_at: string
}

export function AdminNotificationCenter() {
    const supabase = createClient()
    const [notifications, setNotifications] = useState<Notification[]>([])
    const [unreadCount, setUnreadCount] = useState(0)
    const [showPanel, setShowPanel] = useState(false)
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        fetchNotifications()
        subscribeToNotifications()
    }, [])

    const fetchNotifications = async () => {
        try {
            const { data, error } = await supabase
                .from('admin_notifications')
                .select('*')
                .order('created_at', { ascending: false })
                .limit(20)

            if (error) throw error

            setNotifications(data || [])
            setUnreadCount(data?.filter(n => !n.read).length || 0)
        } catch (error) {
            console.error('Failed to fetch notifications:', error)
        } finally {
            setLoading(false)
        }
    }

    const subscribeToNotifications = () => {
        const channel = supabase
            .channel('admin_notifications')
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'admin_notifications',
                },
                (payload) => {
                    setNotifications(prev => [payload.new as Notification, ...prev])
                    setUnreadCount(prev => prev + 1)
                }
            )
            .subscribe()

        return () => {
            supabase.removeChannel(channel)
        }
    }

    const markAsRead = async (id: string) => {
        try {
            await supabase
                .from('admin_notifications')
                .update({ read: true, read_at: new Date().toISOString() })
                .eq('id', id)

            setNotifications(prev =>
                prev.map(n => (n.id === id ? { ...n, read: true } : n))
            )
            setUnreadCount(prev => Math.max(0, prev - 1))
        } catch (error) {
            console.error('Failed to mark as read:', error)
        }
    }

    const markAllAsRead = async () => {
        try {
            const unreadIds = notifications.filter(n => !n.read).map(n => n.id)

            await supabase
                .from('admin_notifications')
                .update({ read: true, read_at: new Date().toISOString() })
                .in('id', unreadIds)

            setNotifications(prev => prev.map(n => ({ ...n, read: true })))
            setUnreadCount(0)
        } catch (error) {
            console.error('Failed to mark all as read:', error)
        }
    }

    const getTypeIcon = (type: string) => {
        switch (type) {
            case 'success':
                return <CheckCircle className="w-5 h-5 text-green-500" />
            case 'warning':
                return <AlertCircle className="w-5 h-5 text-yellow-500" />
            case 'error':
                return <AlertCircle className="w-5 h-5 text-red-500" />
            default:
                return <Bell className="w-5 h-5 text-blue-500" />
        }
    }

    return (
        <div className="relative">
            {/* Notification Bell */}
            <button
                onClick={() => setShowPanel(!showPanel)}
                className="relative p-2 text-slate-400 hover:text-white transition-colors rounded-lg hover:bg-slate-800"
            >
                <Bell className="w-6 h-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-0 right-0 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                )}
            </button>

            {/* Notification Panel */}
            {showPanel && (
                <>
                    <div
                        className="fixed inset-0 z-40"
                        onClick={() => setShowPanel(false)}
                    />
                    <div className="absolute right-0 top-12 w-96 max-h-[600px] bg-slate-800 border border-slate-700 rounded-xl shadow-2xl z-50 overflow-hidden">
                        <div className="p-4 border-b border-slate-700 flex items-center justify-between">
                            <h3 className="text-white font-semibold">Notifications</h3>
                            <div className="flex items-center gap-2">
                                {unreadCount > 0 && (
                                    <Button
                                        size="sm"
                                        variant="ghost"
                                        onClick={markAllAsRead}
                                        className="text-xs text-blue-400 hover:text-blue-300"
                                    >
                                        Mark all read
                                    </Button>
                                )}
                                <button
                                    onClick={() => setShowPanel(false)}
                                    className="text-slate-400 hover:text-white"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                        </div>

                        <div className="overflow-y-auto max-h-[500px]">
                            {loading ? (
                                <div className="p-8 text-center">
                                    <div className="animate-spin w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full mx-auto" />
                                </div>
                            ) : notifications.length === 0 ? (
                                <div className="p-8 text-center text-slate-400">
                                    <Bell className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                    <p>No notifications</p>
                                </div>
                            ) : (
                                <div className="divide-y divide-slate-700">
                                    {notifications.map((notification) => (
                                        <div
                                            key={notification.id}
                                            className={`p-4 hover:bg-slate-700/50 transition-colors ${!notification.read ? 'bg-slate-700/30' : ''
                                                }`}
                                        >
                                            <div className="flex items-start gap-3">
                                                <div className="mt-0.5">{getTypeIcon(notification.type)}</div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-start justify-between gap-2">
                                                        <h4 className="text-white font-medium text-sm">
                                                            {notification.title}
                                                        </h4>
                                                        {!notification.read && (
                                                            <button
                                                                onClick={() => markAsRead(notification.id)}
                                                                className="text-blue-400 hover:text-blue-300"
                                                            >
