'use client';

import { useEffect, useState } from 'react';
import { AlertTriangle, CheckCircle, XCircle, RefreshCw, Filter } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface ClientError {
  id: string;
  error_type: string;
  error_message: string;
  page_url: string;
  browser: string;
  device_type: string;
  severity: string;
  resolved: boolean;
  created_at: string;
}

interface ErrorStats {
  total_errors: number;
  critical_errors: number;
  unresolved_errors: number;
  errors_last_hour: number;
}

export function ErrorMonitor() {
  const [errors, setErrors] = useState<ClientError[]>([]);
  const [stats, setStats] = useState<ErrorStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'unresolved' | 'critical'>('all');

  const fetchErrors = async () => {
    try {
      const res = await fetch('/api/admin/errors');
      if (res.ok) {
        const data = await res.json();
        setErrors(data.errors || []);
        setStats(data.stats || null);
      }
    } catch (err) {
      console.error('Failed to fetch errors:', err);
    } finally {
      setLoading(false);
    }
  };

  const resolveError = async (id: string) => {
    try {
      const res = await fetch(`/api/admin/errors/${id}/resolve`, { method: 'POST' });
      if (res.ok) {
        setErrors(prev => prev.map(e => e.id === id ? { ...e, resolved: true } : e));
      }
    } catch (err) {
      console.error('Failed to resolve error:', err);
    }
  };

  useEffect(() => {
    fetchErrors();
    // Refresh every 30 seconds
    const interval = setInterval(fetchErrors, 30000);
    return () => clearInterval(interval);
  }, []);

  const filteredErrors = errors.filter(e => {
    if (filter === 'unresolved') return !e.resolved;
    if (filter === 'critical') return e.severity === 'critical';
    return true;
  });

  if (loading) {
    return (
      <div className="bg-slate-900 rounded-xl p-6 border border-slate-800">
        <div className="flex items-center justify-center py-8">
          <RefreshCw className="w-6 h-6 text-blue-400 animate-spin" />
        </div>
      </div>
    );
  }

  return (
    <div className="bg-slate-900 rounded-xl border border-slate-800">
      {/* Header */}
      <div className="p-6 border-b border-slate-800">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-white flex items-center gap-2">
            <AlertTriangle className="w-5 h-5 text-red-400" />
            Client Errors
          </h3>
          <Button variant="outline" size="sm" onClick={fetchErrors}>
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>

        {/* Stats */}
        {stats && (
          <div className="grid grid-cols-4 gap-4">
            <div className="bg-slate-800/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-white">{stats.total_errors}</div>
              <div className="text-xs text-slate-400">Total (24h)</div>
            </div>
            <div className="bg-slate-800/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-red-400">{stats.critical_errors}</div>
              <div className="text-xs text-slate-400">Critical</div>
            </div>
            <div className="bg-slate-800/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-yellow-400">{stats.unresolved_errors}</div>
              <div className="text-xs text-slate-400">Unresolved</div>
            </div>
            <div className="bg-slate-800/50 rounded-lg p-3">
              <div className="text-2xl font-bold text-blue-400">{stats.errors_last_hour}</div>
              <div className="text-xs text-slate-400">Last hour</div>
            </div>
          </div>
        )}
      </div>

      {/* Filters */}
      <div className="px-6 py-3 border-b border-slate-800 flex items-center gap-2">
        <Filter className="w-4 h-4 text-slate-400" />
        {(['all', 'unresolved', 'critical'] as const).map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${
              filter === f
                ? 'bg-blue-500/20 text-blue-400'
                : 'text-slate-400 hover:text-white'
            }`}
          >
            {f.charAt(0).toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      {/* Error List */}
      <div className="max-h-[400px] overflow-y-auto">
        {filteredErrors.length === 0 ? (
          <div className="p-8 text-center text-slate-500">
            <CheckCircle className="w-12 h-12 mx-auto mb-2 text-green-500" />
            <p>No errors found</p>
          </div>
        ) : (
          <div className="divide-y divide-slate-800">
            {filteredErrors.slice(0, 20).map((error) => (
              <div
                key={error.id}
                className={`p-4 hover:bg-slate-800/30 transition-colors ${
                  error.resolved ? 'opacity-50' : ''
                }`}
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`text-xs px-2 py-0.5 rounded-full ${
                        error.severity === 'critical'
                          ? 'bg-red-500/20 text-red-400'
                          : error.severity === 'warning'
                          ? 'bg-yellow-500/20 text-yellow-400'
                          : 'bg-blue-500/20 text-blue-400'
                      }`}>
                        {error.error_type}
                      </span>
                      <span className="text-xs text-slate-500">
                        {new Date(error.created_at).toLocaleTimeString()}
                      </span>
                    </div>
                    <p className="text-sm text-white truncate mb-1">
                      {error.error_message}
                    </p>
                    <p className="text-xs text-slate-500 truncate">
                      {error.page_url} • {error.browser} • {error.device_type}
                    </p>
                  </div>
                  {!error.resolved && (
                    <button
                      onClick={() => resolveError(error.id)}
                      className="p-2 hover:bg-green-500/20 rounded-lg transition-colors"
                      title="Mark as resolved"
                    >
                      <CheckCircle className="w-4 h-4 text-green-400" />
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client'

import { useState } from 'react'
import { createClient } from '@supabase/supabase-js'
import { Trash2, Crown, Mail } from 'lucide-react'
import { toast } from 'sonner'

interface User {
  id: string
  email: string
  full_name: string | null
  subscription_tier: string
  subscription_status: string
  created_at: string
  role: string
}

function getSupabase() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL || '',
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || ''
  )
}

export function UserTable({ users, onUsersChange }: { users: User[]; onUsersChange: (users: User[]) => void }) {
  const [searchTerm, setSearchTerm] = useState('')
  const [upgrading, setUpgrading] = useState<string | null>(null)
  const [deleting, setDeleting] = useState<string | null>(null)

  const filteredUsers = users.filter(user =>
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.full_name?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const handleUpgradeToBeta = async (userId: string) => {
    setUpgrading(userId)
    try {
      const supabase = getSupabase()
      const { error } = await supabase
        .from('profiles')
        .update({
          subscription_tier: 'beta',
          subscription_status: 'active',
          updated_at: new Date().toISOString()
        })
        .eq('id', userId)

      if (!error) {
        const updatedUsers = users.map(u =>
          u.id === userId ? { ...u, subscription_tier: 'beta', subscription_status: 'active' } : u
        )
        onUsersChange(updatedUsers)
      } else {
        console.error('Upgrade error:', error)
        toast.error('Kunne ikke oppgradere bruker: ' + error.message)
      }
    } catch (error) {
      console.error('Upgrade error:', error)
      toast.error('En feil oppstod')
    } finally {
      setUpgrading(null)
    }
  }

  const handleDelete = async (userId: string, email: string) => {
    if (!confirm(`Sikker på å slette ${email}? Dette kan ikke angres!`)) return

    setDeleting(userId)
    try {
      const supabase = getSupabase()
      const { error } = await supabase
        .from('profiles')
        .delete()
        .eq('id', userId)

      if (!error) {
        const updatedUsers = users.filter(u => u.id !== userId)
        onUsersChange(updatedUsers)
      } else {
        console.error('Delete error:', error)
        toast.error('Kunne ikke slette bruker: ' + error.message)
      }
    } catch (error) {
      console.error('Delete error:', error)
      toast.error('En feil oppstod')
    } finally {
      setDeleting(null)
    }
  }

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-lg">
      <div className="p-6 border-b border-slate-800">
        <input
          type="text"
          placeholder="Søk brukere..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full px-4 py-2 bg-slate-950 border border-slate-700 rounded-lg text-white placeholder:text-slate-500"
        />
      </div>

      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-slate-800">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-300 uppercase">
                Bruker
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-300 uppercase">
                Tier
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-300 uppercase">
                Status
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-300 uppercase">
                Registrert
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-slate-300 uppercase">
                Handlinger
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800">
            {filteredUsers.map((user) => (
              <tr key={user.id} className="hover:bg-slate-800/50 transition-colors">
                <td className="px-6 py-4">
                  <div>
                    <p className="text-white font-medium">{user.full_name || 'Ukjent'}</p>
                    <p className="text-slate-400 text-sm">{user.email}</p>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                    user.subscription_tier === 'beta' ? 'bg-emerald-500/20 text-emerald-300' :
                    user.subscription_tier === 'pro' ? 'bg-blue-500/20 text-blue-300' :
                    'bg-slate-500/20 text-slate-300'
                  }`}>
                    {user.subscription_tier}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                    user.subscription_status === 'active' ? 'bg-green-500/20 text-green-300' :
                    'bg-slate-500/20 text-slate-300'
                  }`}>
                    {user.subscription_status}
                  </span>
                </td>
                <td className="px-6 py-4 text-slate-400 text-sm">
                  {new Date(user.created_at).toLocaleDateString('no-NO')}
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-end gap-2">
                    {user.subscription_tier !== 'beta' && (
                      <button
                        onClick={() => handleUpgradeToBeta(user.id)}
                        disabled={upgrading === user.id}
                        className="p-2 hover:bg-emerald-500/20 rounded-lg transition-colors disabled:opacity-50"
                        title="Oppgrader til Beta"
                      >
                        <Crown className={`w-4 h-4 ${upgrading === user.id ? 'animate-spin' : ''}`} />
                      </button>
                    )}
                    <button
                      onClick={() => handleDelete(user.id, user.email)}
                      disabled={deleting === user.id}
                      className="p-2 hover:bg-red-500/20 rounded-lg transition-colors disabled:opacity-50"
                      title="Slett bruker"
                    >
                      <Trash2 className="w-4 h-4 text-red-400" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

'use client'

import { useState, useRef, useEffect, useCallback } from 'react'
import { MessageCircle, X, Send, GraduationCap, Minimize2, Sparkles, User, Bot, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { getErrorMessage } from '@/lib/utils/error'

interface Message {
    id: string
    role: 'user' | 'assistant'
    content: string
    isTyping?: boolean
}

// Typing delay konfigurasjon
const TYPING_CONFIG = {
    minDelay: 15,      // Minimum ms mellom tegn
    maxDelay: 45,      // Maximum ms mellom tegn
    batchSize: 3,      // Antall tegn som vises samtidig
    pauseChars: ['.', '!', '?', ','], // Tegn som gir pause
    pauseDelay: 150,   // Ekstra pause etter punktum/komma
}

export function ChatWidget() {
    const [isOpen, setIsOpen] = useState(false)
    const [isHovered, setIsHovered] = useState(false)
    const [messages, setMessages] = useState<Message[]>([])
    const [input, setInput] = useState('')
    const [isLoading, setIsLoading] = useState(false)
    const [error, setError] = useState<string | null>(null)
    const [typingMessageId, setTypingMessageId] = useState<string | null>(null)

    const scrollRef = useRef<HTMLDivElement>(null)
    const inputRef = useRef<HTMLInputElement>(null)
    const abortControllerRef = useRef<AbortController | null>(null)

    // Scroll to bottom when messages change
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTo({
                top: scrollRef.current.scrollHeight,
                behavior: 'smooth'
            })
        }
    }, [messages, isOpen])

    // Focus input when opened
    useEffect(() => {
        if (isOpen && inputRef.current) {
            setTimeout(() => inputRef.current?.focus(), 100)
        }
    }, [isOpen])

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (abortControllerRef.current) {
                abortControllerRef.current.abort()
            }
        }
    }, [])

    // Simulate typing effect
    const simulateTyping = useCallback(async (messageId: string, fullContent: string) => {
        setTypingMessageId(messageId)
        let currentIndex = 0

        const typeNextBatch = () => {
            if (currentIndex >= fullContent.length) {
                setTypingMessageId(null)
                setMessages(prev => prev.map(m => 
                    m.id === messageId ? { ...m, isTyping: false } : m
                ))
                return
            }

            const batchEnd = Math.min(currentIndex + TYPING_CONFIG.batchSize, fullContent.length)
            const newContent = fullContent.slice(0, batchEnd)

            setMessages(prev => prev.map(m => 
                m.id === messageId ? { ...m, content: newContent } : m
            ))

            currentIndex = batchEnd

            // Calculate delay for next batch
            const lastChar = fullContent[currentIndex - 1]
            const isPauseChar = TYPING_CONFIG.pauseChars.includes(lastChar)
            const delay = isPauseChar 
                ? TYPING_CONFIG.pauseDelay 
                : Math.random() * (TYPING_CONFIG.maxDelay - TYPING_CONFIG.minDelay) + TYPING_CONFIG.minDelay

            setTimeout(typeNextBatch, delay)
        }

        // Start typing after a small initial delay (thinking time)
        setTimeout(typeNextBatch, 400)
    }, [])

    const handleSubmit = useCallback(async (e?: React.FormEvent) => {
        e?.preventDefault()

        if (!(input || '').trim() || isLoading) return

        const userMessage = (input || '').trim()
        setInput('')
        setIsLoading(true)
        setError(null)

        // Cancel any ongoing typing
        if (abortControllerRef.current) {
            abortControllerRef.current.abort()
        }
        abortControllerRef.current = new AbortController()

        // Add user message
        const userMsg: Message = {
            id: Date.now().toString(),
            role: 'user',
            content: userMessage
        }
        setMessages(prev => [...prev, userMsg])

        try {
            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    messages: [...messages, userMsg].map(m => ({
                        role: m.role,
                        content: m.content
                    }))
                }),
                signal: abortControllerRef.current.signal
            })

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}))
                throw new Error(errorData.error || `HTTP error! status: ${response.status}`)
            }

            // Read the SSE stream
            const reader = response.body?.getReader()
            const decoder = new TextDecoder()
            let fullContent = ''
            const assistantId = (Date.now() + 1).toString()

            // Add placeholder for assistant message (hidden initially)
            setMessages(prev => [...prev, {
                id: assistantId,
                role: 'assistant',
                content: '',
                isTyping: true
            }])

            if (reader) {
                let buffer = ''
                while (true) {
                    const { done, value } = await reader.read()
                    if (done) break

                    buffer += decoder.decode(value, { stream: true })

                    // Process SSE lines
                    const lines = buffer.split('\n')
                    buffer = lines.pop() || ''

                    for (const line of lines) {
                        const trimmed = (line || '').trim()
                        if (trimmed.startsWith('data: ')) {
                            const data = trimmed.slice(6)
                            if (data === '[DONE]') continue

                            try {
                                const parsed = JSON.parse(data)
                                const content = parsed.choices?.[0]?.delta?.content
                                if (content) {
                                    fullContent += content
                                }
                            } catch (e) {
                                // Ignore parse errors for non-JSON lines
                            }
                        }
                    }
                }
            }

            // Now start the typing effect with the full content
            if (fullContent) {
                simulateTyping(assistantId, fullContent)
            }

        } catch (err: unknown) {
            if (err instanceof Error && err.name === 'AbortError') return
            console.error('Chat error:', err)
            setError(getErrorMessage(err))
        } finally {
            setIsLoading(false)
        }
    }, [input, isLoading, messages, simulateTyping])

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setInput(e.target.value)
    }

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault()
            handleSubmit()
        }
    }

    return (
        <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end gap-4 font-sans">
            {/* Chat Window */}
