interface StrategyBuilderProps {
  maxStrategies?: number;
  onStrategyCreated?: (strategy: {
    id: string;
    name: string;
    symbol: string;
    indicators: string[];
    stopLoss: number;
    takeProfit: number;
  }) => void;
}

interface StrategyCondition {
  id: string;
  indicator: string;
  operator: '>' | '<' | '=' | 'crosses_above' | 'crosses_below';
  value: number;
}

interface Strategy {
  name: string;
  description: string;
  entryConditions: StrategyCondition[];
  exitConditions: StrategyCondition[];
  stopLoss: number;
  takeProfit: number;
  positionSize: number;
  maxPositions: number;
}

interface BacktestResult {
  totalReturn: number;
  totalReturnPercent: number;
  winRate: number;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  maxDrawdown: number;
  sharpeRatio: number;
  profitFactor: number;
  avgTrade: number;
  bestTrade: number;
  worstTrade: number;
  isValid: boolean;
  confidenceScore: number;
  recommendation: 'proceed' | 'caution' | 'reject';
  validationErrors: string[];
}

