                <Input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Slutt Dato
              </label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Strategy Builder Tabs */}
        <div className="border-b border-gray-200 dark:border-gray-800">
          <div className="flex">
            {(['entry', 'exit', 'risk'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 px-4 text-sm font-medium transition-colors ${
                  activeTab === tab
                    ? 'border-b-2 border-blue-500 text-blue-600 dark:text-blue-400'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200'
                }`}
              >
                {tab === 'entry' && 'Entry Betingelser'}
                {tab === 'exit' && 'Exit Betingelser'}
                {tab === 'risk' && 'Risk Management'}
              </button>
            ))}
          </div>
        </div>

        {/* Tab Content */}
        <div className="p-6">
          {activeTab === 'entry' && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="font-medium text-gray-900 dark:text-white">
                  Når skal vi kjøpe?
                </h4>
                <Button
                  onClick={() => addCondition('entry')}
                  variant="outline"
                  size="sm"
                >
                  <Plus className="w-4 h-4 mr-1" />
                  Legg til betingelse
                </Button>
              </div>

              {strategy.entryConditions.length === 0 ? (
                <p className="text-gray-500 dark:text-gray-400 text-sm">
                  Ingen entry-betingelser enda. Klikk "Legg til betingelse" for å starte.
                </p>
              ) : (
                <div className="space-y-3">
                  {strategy.entryConditions.map((condition, index) => (
                    <ConditionRow
                      key={condition.id}
                      condition={condition}
                      index={index}
                      onUpdate={(updates) => updateCondition('entry', condition.id, updates)}
                      onRemove={() => removeCondition('entry', condition.id)}
                    />
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'exit' && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="font-medium text-gray-900 dark:text-white">
                  Når skal vi selge?
                </h4>
                <Button
                  onClick={() => addCondition('exit')}
                  variant="outline"
                  size="sm"
                >
                  <Plus className="w-4 h-4 mr-1" />
                  Legg til betingelse
                </Button>
              </div>

              {strategy.exitConditions.length === 0 ? (
                <p className="text-gray-500 dark:text-gray-400 text-sm">
                  Ingen exit-betingelser enda. Klikk "Legg til betingelse" for å starte.
                </p>
              ) : (
                <div className="space-y-3">
                  {strategy.exitConditions.map((condition, index) => (
                    <ConditionRow
                      key={condition.id}
                      condition={condition}
                      index={index}
                      onUpdate={(updates) => updateCondition('exit', condition.id, updates)}
                      onRemove={() => removeCondition('exit', condition.id)}
                    />
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'risk' && (
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Stop Loss (%)
                </label>
                <Input
                  type="number"
                  value={strategy.stopLoss}
                  onChange={(e) => setStrategy(prev => ({ ...prev, stopLoss: Number(e.target.value) }))}
                  min={1}
                  max={50}
                  step={0.5}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Take Profit (%)
                </label>
                <Input
                  type="number"
                  value={strategy.takeProfit}
                  onChange={(e) => setStrategy(prev => ({ ...prev, takeProfit: Number(e.target.value) }))}
                  min={1}
                  max={100}
                  step={0.5}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Posisjonsstørrelse (%)
                </label>
                <Input
                  type="number"
                  value={strategy.positionSize}
                  onChange={(e) => setStrategy(prev => ({ ...prev, positionSize: Number(e.target.value) }))}
                  min={1}
                  max={100}
                  step={1}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Maks antall posisjoner
                </label>
                <Input
                  type="number"
                  value={strategy.maxPositions}
                  onChange={(e) => setStrategy(prev => ({ ...prev, maxPositions: Number(e.target.value) }))}
                  min={1}
                  max={10}
                  step={1}
                />
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Backtest Results */}
      {backtestResult && (
        <BacktestResults result={backtestResult} />
      )}

      {/* Actions */}
      <div className="flex flex-col sm:flex-row gap-4">
        <Button
          onClick={runBacktest}
          disabled={isTesting || !selectedStrategyId}
          variant="outline"
          className="flex-1"
        >
          {isTesting ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Kjører backtest...
            </>
          ) : (
            <>
              <Play className="w-4 h-4 mr-2" />
              Kjør Backtest
            </>
          )}
        </Button>

        <Button
          onClick={saveStrategy}
          disabled={isTesting || !selectedStrategyId}
          className="flex-1"
        >
          <Save className="w-4 h-4 mr-2" />
          Lagre Strategi
        </Button>
      </div>

      {/* Messages */}
      {error && (
        <div className="flex items-center gap-2 text-red-600 dark:text-red-400">
          <AlertCircle className="w-4 h-4" />
          <span className="text-sm">{error}</span>
        </div>
      )}

      {success && (
        <div className="flex items-center gap-2 text-green-600 dark:text-green-400">
          <CheckCircle className="w-4 h-4" />
          <span className="text-sm">{success}</span>
        </div>
      )}
    </div>
  );
}

// Sub-components
function ConditionRow({
  condition,
  index,
  onUpdate,
  onRemove,
}: {
  condition: StrategyCondition;
  index: number;
  onUpdate: (updates: Partial<StrategyCondition>) => void;
  onRemove: () => void;
}) {
  return (
    <div className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-lg">
      <span className="text-sm text-gray-500 dark:text-gray-400 w-8">#{index + 1}</span>

      <select
        value={condition.indicator}
        onChange={(e) => onUpdate({ indicator: e.target.value })}
        className="px-3 py-2 rounded border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm"
      >
        {INDICATORS.map(ind => (
          <option key={ind.value} value={ind.value}>{ind.label}</option>
        ))}
      </select>

      <select
        value={condition.operator}
        onChange={(e) => onUpdate({ operator: e.target.value as StrategyCondition['operator'] })}
        className="px-3 py-2 rounded border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm"
      >
        <option value="<">&lt; (mindre enn)</option>
        <option value=">">&gt; (større enn)</option>
        <option value="=">= (lik)</option>
        <option value="crosses_above">Krysser over</option>
        <option value="crosses_below">Krysser under</option>
      </select>

      <Input
        type="number"
        value={condition.value}
        onChange={(e) => onUpdate({ value: Number(e.target.value) })}
        className="w-24"
      />

      <button
        onClick={onRemove}
        className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
}

function BacktestResults({ result }: { result: BacktestResult }) {
  const isGood = result.recommendation === 'proceed';
  const isCaution = result.recommendation === 'caution';

  return (
    <div className={`p-6 rounded-2xl border-2 ${
      isGood ? 'border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-900/10' :
      isCaution ? 'border-yellow-200 dark:border-yellow-800 bg-yellow-50 dark:bg-yellow-900/10' :
      'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/10'
    }`}>
      <div className="flex items-center gap-3 mb-4">
        {isGood ? <TrendingUp className="w-6 h-6 text-green-600" /> :
         isCaution ? <AlertCircle className="w-6 h-6 text-yellow-600" /> :
         <TrendingDown className="w-6 h-6 text-red-600" />}
        <div>
          <h4 className="font-semibold text-gray-900 dark:text-white">
            Backtest Resultater
          </h4>
          <p className={`text-sm ${
            isGood ? 'text-green-600' :
            isCaution ? 'text-yellow-600' :
            'text-red-600'
          }`}>
            {isGood ? 'Anbefalt - God strategi' :
             isCaution ? 'Moderat - Vurder justeringer' :
             'Ikke anbefalt - Trenger forbedringer'}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Stat label="Total Avkastning" value={`${result.totalReturnPercent.toFixed(2)}%`} />
        <Stat label="Win Rate" value={`${result.winRate.toFixed(1)}%`} />
        <Stat label="Antall Handler" value={result.totalTrades.toString()} />
        <Stat label="Sharpe Ratio" value={result.sharpeRatio.toFixed(2)} />
        <Stat label="Max Drawdown" value={`${result.maxDrawdown.toFixed(2)}%`} />
        <Stat label="Profit Factor" value={result.profitFactor.toFixed(2)} />
        <Stat label="Gj.snitt Trade" value={`$${result.avgTrade.toFixed(0)}`} />
        <Stat label="Konfidens" value={`${result.confidenceScore}%`} />
      </div>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="text-center p-3 bg-white dark:bg-gray-800 rounded-lg">
      <p className="text-2xl font-bold text-gray-900 dark:text-white">{value}</p>
      <p className="text-xs text-gray-500 dark:text-gray-400">{label}</p>
    </div>
  );
}

'use client';

/**
 * ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
 * STRATEGY RECOMMENDATIONS COMPONENT
 * ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
 * 
 * Displays:
 * - Current market regime with confidence badge
 * - Technical metrics (RSI, ADX, ATR, Volatility, Trend)
 * - AI reasoning in Norwegian
 * - Top recommended strategies
 * - Educational links
 * 
 * ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { 
  TrendingUp, 
  TrendingDown, 
  ArrowRightLeft, 
  AlertTriangle,
  HelpCircle,
  RefreshCw,
  Activity,
  Target,
  BarChart3,
  LineChart,
  BookOpen,
} from 'lucide-react';

interface MarketMetrics {
  rsi: number;
  adx: number;
  atr: number;
  atrPercent: number;
  volatility: number;
  trend: number;
  volumeTrend: number;
  priceVsSMA20: number;
  priceVsSMA50: number;
}

interface Strategy {
  id: string;
  name: string;
  description: string;
  riskLevel: string;
  expectedReturn: number;
  timeframe: string;
  score: number;
  matchReason: string;
}

interface EducationalLink {
  title: string;
  url: string;
  description: string;
}

interface RecommendationsData {
  success: boolean;
  symbol: string;
  timeframe: string;
  analysis: {
    regime: 'TRENDING_UP' | 'TRENDING_DOWN' | 'RANGING' | 'VOLATILE' | 'UNCERTAIN';
    confidence: number;
    metrics: MarketMetrics;
    reasoning: string;
  };
  strategies: Strategy[];
  recommendedApproach: string[];
  educationalLinks: EducationalLink[];
  timestamp: string;
}

interface Props {
  symbol?: string;
  timeframe?: string;
}

export function StrategyRecommendations({ symbol = 'BTCUSDT', timeframe = '1h' }: Props) {
  const [data, setData] = useState<RecommendationsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  const fetchRecommendations = async () => {
    try {
      setRefreshing(true);
      const response = await fetch(
        `/api/auto-trading/recommendations?symbol=${symbol}&timeframe=${timeframe}`
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to fetch recommendations');
      }

      const result = await response.json();
      setData(result);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRecommendations();

    // Auto-refresh every 5 minutes
    const interval = setInterval(fetchRecommendations, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, [symbol, timeframe]);

  // Get regime display info
  const getRegimeInfo = (regime: string) => {
    const info: Record<string, { label: string; color: string; icon: React.ReactNode; bgColor: string }> = {
      'TRENDING_UP': {
        label: 'Opptrend',
        color: 'text-green-600',
        bgColor: 'bg-green-100 dark:bg-green-900',
        icon: <TrendingUp className="h-5 w-5" />,
      },
      'TRENDING_DOWN': {
        label: 'Nedtrend',
        color: 'text-red-600',
        bgColor: 'bg-red-100 dark:bg-red-900',
        icon: <TrendingDown className="h-5 w-5" />,
      },
      'RANGING': {
        label: 'Sideways',
        color: 'text-blue-600',
        bgColor: 'bg-blue-100 dark:bg-blue-900',
        icon: <ArrowRightLeft className="h-5 w-5" />,
      },
      'VOLATILE': {
        label: 'Volatilt',
        color: 'text-orange-600',
        bgColor: 'bg-orange-100 dark:bg-orange-900',
        icon: <AlertTriangle className="h-5 w-5" />,
      },
      'UNCERTAIN': {
        label: 'Usikkert',
        color: 'text-gray-600',
        bgColor: 'bg-gray-100 dark:bg-gray-800',
        icon: <HelpCircle className="h-5 w-5" />,
      },
    };
    return info[regime] || info['UNCERTAIN'];
  };

  // Format percentage
  const formatPct = (val: number, decimals = 1) => `${val > 0 ? '+' : ''}${val.toFixed(decimals)}%`;

  if (loading) {
    return (
      <Card className="w-full">
        <CardHeader>
          <Skeleton className="h-8 w-64" />
        <Skeleton className="h-4 w-48" />
        </CardHeader>
        <CardContent className="space-y-4">
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-32 w-full" />
          <Skeleton className="h-48 w-full" />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className="w-full border-red-200 dark:border-red-800">
        <CardContent className="pt-6">
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <AlertTriangle className="h-12 w-12 text-red-500 mb-4" />
            <h3 className="text-lg font-semibold text-red-600 mb-2">Kunne ikke laste anbefalinger</h3>
            <p className="text-sm text-muted-foreground mb-4">{error}</p>
            <Button onClick={fetchRecommendations} variant="outline">
              <RefreshCw className="h-4 w-4 mr-2" />
              Prøv igjen
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!data) return null;

  const regimeInfo = getRegimeInfo(data.analysis.regime);
  const confidence = Math.round(data.analysis.confidence * 100);

  return (
    <Card className="w-full">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-xl flex items-center gap-2">
              <Activity className="h-5 w-5 text-primary" />
              Markedsanalyse & Strategier
            </CardTitle>
            <p className="text-sm text-muted-foreground mt-1">
              {data.symbol} • {data.timeframe} • Oppdatert {new Date(data.timestamp).toLocaleTimeString('no-NO')}
            </p>
          </div>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={fetchRecommendations}
            disabled={refreshing}
          >
            <RefreshCw className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Market Regime Badge */}
        <div className={`p-4 rounded-lg ${regimeInfo.bgColor} flex items-center gap-4`}>
          <div className={`p-3 rounded-full bg-white dark:bg-gray-800 ${regimeInfo.color}`}>
            {regimeInfo.icon}
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <span className="text-lg font-semibold">{regimeInfo.label}</span>
              <Badge variant={confidence > 70 ? 'default' : 'secondary'}>
                {confidence}% sikkerhet
              </Badge>
            </div>
            <p className={`text-sm ${regimeInfo.color} mt-1`}>
              {data.analysis.reasoning}
            </p>
          </div>
        </div>

        {/* Technical Metrics */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <MetricCard 
            icon={<Target className="h-4 w-4" />}
            label="RSI (14)"
            value={data.analysis.metrics.rsi.toFixed(1)}
            subtext={data.analysis.metrics.rsi > 70 ? 'Overkjøpt' : data.analysis.metrics.rsi < 30 ? 'Oversolgt' : 'Nøytral'}
            color={data.analysis.metrics.rsi > 70 ? 'text-orange-500' : data.analysis.metrics.rsi < 30 ? 'text-blue-500' : 'text-green-500'}
          />
          <MetricCard 
            icon={<BarChart3 className="h-4 w-4" />}
            label="ADX"
            value={data.analysis.metrics.adx.toFixed(1)}
            subtext={data.analysis.metrics.adx > 25 ? 'Sterk trend' : 'Svak trend'}
            color={data.analysis.metrics.adx > 25 ? 'text-green-500' : 'text-gray-500'}
          />
          <MetricCard 
            icon={<Activity className="h-4 w-4" />}
            label="ATR"
            value={`${data.analysis.metrics.atrPercent.toFixed(2)}%`}
            subtext={data.analysis.metrics.atrPercent > 4 ? 'Høy volatilitet' : 'Normal'}
            color={data.analysis.metrics.atrPercent > 4 ? 'text-red-500' : 'text-green-500'}
          />
          <MetricCard 
            icon={<LineChart className="h-4 w-4" />}
            label="Trend"
            value={formatPct(data.analysis.metrics.trend * 100, 0)}
            subtext={data.analysis.metrics.trend > 0.2 ? 'Opp' : data.analysis.metrics.trend < -0.2 ? 'Ned' : 'Flat'}
            color={data.analysis.metrics.trend > 0.2 ? 'text-green-500' : data.analysis.metrics.trend < -0.2 ? 'text-red-500' : 'text-gray-500'}
          />
        </div>

        {/* Recommended Strategies */}
        <div>
          <h4 className="font-semibold mb-3 flex items-center gap-2">
            <Target className="h-4 w-4 text-primary" />
            Anbefalte Strategier
          </h4>
          <div className="space-y-3">
            {data.strategies.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">
                Ingen strategier tilgjengelig. Kontakt support.
              </p>
            ) : (
              data.strategies.map((strategy) => (
                <div 
                  key={strategy.id}
                  className="p-3 border rounded-lg hover:bg-accent transition-colors"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{strategy.name}</span>
                        <RiskBadge level={strategy.riskLevel} />
                        {strategy.score >= 80 && (
                          <Badge variant="default" className="text-xs">Beste match</Badge>
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">
                        {strategy.description}
                      </p>
                      <p className="text-xs text-primary mt-2">
                        💡 {strategy.matchReason}
                      </p>
                      <div className="flex gap-4 mt-2 text-xs text-muted-foreground">
                        <span>Forventet avkastning: {strategy.expectedReturn}%/år</span>
                        <span>Timeframe: {strategy.timeframe}</span>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Educational Links */}
        {data.educationalLinks.length > 0 && (
          <div className="pt-4 border-t">
            <h4 className="font-semibold mb-3 flex items-center gap-2">
              <BookOpen className="h-4 w-4 text-primary" />
              Lær mer
            </h4>
            <div className="grid gap-2">
              {data.educationalLinks.map((link, idx) => (
                <a 
                  key={idx}
                  href={link.url}
                  className="flex items-center justify-between p-3 rounded-lg bg-accent hover:bg-accent/80 transition-colors"
                >
                  <div>
                    <p className="font-medium text-sm">{link.title}</p>
                    <p className="text-xs text-muted-foreground">{link.description}</p>
                  </div>
                  <ArrowRightLeft className="h-4 w-4 text-muted-foreground" />
                </a>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// Metric Card Component
function MetricCard({ 
  icon, 
  label, 
  value, 
  subtext, 
  color = 'text-muted-foreground' 
}: { 
  icon: React.ReactNode;
  label: string;
  value: string;
  subtext: string;
  color?: string;
}) {
  return (
    <div className="p-3 border rounded-lg">
      <div className="flex items-center gap-2 text-muted-foreground mb-1">
        {icon}
        <span className="text-xs">{label}</span>
      </div>
      <div className="text-lg font-semibold">{value}</div>
      <div className={`text-xs ${color}`}>{subtext}</div>
    </div>
  );
}

// Risk Badge Component
function RiskBadge({ level }: { level: string }) {
  const colors: Record<string, string> = {
    'conservative': 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200',
    'balanced': 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
    'aggressive': 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200',
  };

  const labels: Record<string, string> = {
    'conservative': 'Konservativ',
    'balanced': 'Balansert',
    'aggressive': 'Aggressiv',
  };

  return (
    <span className={`text-xs px-2 py-0.5 rounded ${colors[level] || colors['balanced']}`}>
      {labels[level] || level}
    </span>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  ArrowRight,
  BarChart3,
  Copy,
  Crown,
  TrendingUp,
  Users,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

interface LeaderboardEntry {
  id: string;
  userId: string;
  displayName: string;
  avatarUrl: string | null;
  pnl30d: number;
  pnl90d: number;
  pnlAllTime: number;
  winRate: number;
  sharpeRatio: number;
  followerCount: number;
  performanceFeePct: number;
  strategyType: string;
  rank: number;
  isActive: boolean;
}

type Period = "30d" | "90d" | "all";

export default function CopyTradingLeaderboard() {
  const { locale } = useParams();
  const [entries, setEntries] = useState<LeaderboardEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [period, setPeriod] = useState<Period>("30d");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const limit = 20;

  useEffect(() => {
    fetchLeaderboard();
  }, [period, page]);

  const fetchLeaderboard = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(
        `/api/copy-trading/leaderboard?period=${period}&page=${page}&limit=${limit}`,
      );
      if (!response.ok) {
        throw new Error("Failed to fetch leaderboard");
      }
      const data = await response.json();
      setEntries(data.entries || []);
      setTotal(data.total || 0);
    } catch (error) {
      console.error("Error fetching leaderboard:", error);
      toast.error("Kunne ikke laste ledertavlen");
    } finally {
      setIsLoading(false);
    }
  };

  const formatNOK = (value: number) => {
    return new Intl.NumberFormat("no-NO", {
      style: "currency",
      currency: "NOK",
      maximumFractionDigits: 0,
    }).format(value);
  };

  const formatPercent = (value: number) => {
    return `${value >= 0 ? "+" : ""}${value.toFixed(1)}%`;
  };

  const totalPages = Math.ceil(total / limit);

  return (
    <div className="max-w-6xl mx-auto p-6 space-y-8">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <Link href={`/${locale}/dashboard`}>
              <Button variant="ghost" size="icon" className="text-slate-400">
                <ArrowLeft className="w-5 h-5" />
              </Button>
            </Link>
            <h1 className="text-3xl font-black text-white">Kopier Trading</h1>
          </div>
          <p className="text-slate-400">
            Følg og kopier suksessfulle kryptotradere automatisk
          </p>
        </div>
        <Badge
          variant="outline"
          className="bg-blue-500/10 text-blue-400 border-blue-500/30 self-start md:self-auto"
        >
          <Crown className="w-3 h-3 mr-1" />
          {total} aktive tradere
        </Badge>
      </div>

      {/* Period Selector */}
      <Tabs value={period} onValueChange={(v) => setPeriod(v as Period)}>
        <TabsList className="bg-slate-900 border border-slate-800">
          <TabsTrigger
            value="30d"
            className="data-[state=active]:bg-blue-600 data-[state=active]:text-white"
          >
            30 dager
          </TabsTrigger>
          <TabsTrigger
            value="90d"
            className="data-[state=active]:bg-blue-600 data-[state=active]:text-white"
          >
            90 dager
          </TabsTrigger>
          <TabsTrigger
            value="all"
            className="data-[state=active]:bg-blue-600 data-[state=active]:text-white"
          >
            All tid
          </TabsTrigger>
        </TabsList>
      </Tabs>

      {/* Leaderboard */}
      <div className="space-y-4">
        {isLoading ? (
          // Loading skeletons
          Array.from({ length: 5 }).map((_, i) => (
            <Card key={i} className="bg-slate-900 border-slate-800">
              <CardContent className="p-6">
                <div className="flex items-center gap-4">
                  <Skeleton className="w-12 h-12 rounded-full bg-slate-800" />
                  <div className="flex-1 space-y-2">
                    <Skeleton className="h-4 w-32 bg-slate-800" />
                    <Skeleton className="h-3 w-24 bg-slate-800" />
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        ) : entries.length === 0 ? (
          <Card className="bg-slate-900 border-slate-800">
            <CardContent className="p-12 text-center">
              <BarChart3 className="w-12 h-12 text-slate-600 mx-auto mb-4" />
              <p className="text-slate-400">Ingen tradere funnet ennå</p>
              <p className="text-slate-500 text-sm mt-1">
