    </div>
  );
}

// Quick Stats Component
export function QuickStats({ 
  totalValue, 
  totalProfit, 
  profitPercent,
  activePositions,
  locale = 'no' 
}: { 
  totalValue: number; 
  totalProfit: number; 
  profitPercent: number;
  activePositions: number;
  locale?: string;
}) {
  const isNorwegian = locale === 'no';
  const formatNOK = (n: number) => 
    new Intl.NumberFormat(isNorwegian ? 'no-NO' : 'en-US', {
      style: 'currency',
      currency: 'NOK',
      maximumFractionDigits: 0,
    }).format(n);

  const stats = [
    {
      label: isNorwegian ? 'Total Verdi' : 'Total Value',
      value: formatNOK(totalValue),
      subtext: `${activePositions} ${isNorwegian ? 'posisjoner' : 'positions'}`,
      color: 'text-white',
    },
    {
      label: isNorwegian ? 'Total Avkastning' : 'Total Return',
      value: formatNOK(totalProfit),
      subtext: `${profitPercent >= 0 ? '+' : ''}${profitPercent.toFixed(1)}%`,
      color: profitPercent >= 0 ? 'text-green-400' : 'text-red-400',
      isPositive: profitPercent >= 0,
    },
  ];

  return (
    <div className="grid grid-cols-2 gap-4 mb-6">
      {stats.map((stat, i) => (
        <div 
          key={i}
          className="bg-slate-900/50 border border-white/5 rounded-2xl p-4 hover:border-white/10 transition-colors"
        >
          <p className="text-xs text-slate-500 uppercase tracking-wider mb-1">{stat.label}</p>
          <p className={cn("text-2xl font-bold", stat.color)}>{stat.value}</p>
          <p className={cn(
            "text-sm mt-1",
            stat.isPositive !== undefined 
              ? stat.isPositive ? 'text-green-400' : 'text-red-400'
              : 'text-slate-400'
          )}>
            {stat.subtext}
          </p>
        </div>
      ))}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';

type ViewMode = 'enkel' | 'mellom' | 'avansert';

export default function ProgressiveDashboard() {
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  );
  const [viewMode, setViewMode] = useState<ViewMode>('enkel');
  const [userTier, setUserTier] = useState<string>('student');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadUserTier() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (user) {
          const { data } = await supabase
            .from('profiles')
            .select('tier, view_mode_preference')
            .eq('id', user.id)
            .single();

          if (data) {
            setUserTier(data.tier || 'student');
            setViewMode(data.view_mode_preference || getDefaultViewMode(data.tier));
          }
        }
      } catch (error) {
        console.error('Failed to load user tier:', error);
      } finally {
        setLoading(false);
      }
    }
    loadUserTier();
  }, []);

  function getDefaultViewMode(tier: string): ViewMode {
    if (tier === 'phd' || tier === 'professor') return 'avansert';
    if (tier === 'master') return 'mellom';
    return 'enkel';
  }

  async function saveViewMode(mode: ViewMode) {
    setViewMode(mode);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase
          .from('profiles')
          .update({ view_mode_preference: mode })
          .eq('id', user.id);
      }
    } catch (error) {
      console.error('Failed to save view mode:', error);
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 p-4 md:p-8">
      {/* Header med toggle */}
      <div className="max-w-6xl mx-auto">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6 gap-4">
          <div>
            <h1 className="text-3xl md:text-4xl font-bold text-white">Dashboard</h1>
            <p className="text-slate-400 mt-1">
              Velkommen tilbake{userTier && `, ${userTier.charAt(0).toUpperCase() + userTier.slice(1)}-nivå`}
            </p>
          </div>

          {/* Toggle-knapper */}
          <div className="flex gap-2 bg-gray-800 p-1 rounded-lg">
            <button
              onClick={() => saveViewMode('enkel')}
              className={`px-4 py-2 rounded-lg text-sm font-semibold transition-colors ${viewMode === 'enkel'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-white hover:bg-gray-700'
                }`}
            >
              Enkel
            </button>
            <button
              onClick={() => saveViewMode('mellom')}
              className={`px-4 py-2 rounded-lg text-sm font-semibold transition-colors ${viewMode === 'mellom'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-white hover:bg-gray-700'
                }`}
            >
              Mellom
            </button>
            <button
              onClick={() => saveViewMode('avansert')}
              className={`px-4 py-2 rounded-lg text-sm font-semibold transition-colors ${viewMode === 'avansert'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-white hover:bg-gray-700'
                }`}
            >
              Avansert
            </button>
          </div>
        </div>

        {/* ENKEL VISNING (Student/Nybegynner) */}
        {viewMode === 'enkel' && (
          <div className="space-y-6">
            <PortfolioCard simple />
            <NextLessonCard />
            <SingleSignalCard />
          </div>
        )}

        {/* MELLOM VISNING (Bachelor/Master) */}
        {viewMode === 'mellom' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <PortfolioCard />
            <PaperTradingChart />
            <SignalListCard limit={5} />
            <NextLessonCard />
          </div>
        )}

        {/* AVANSERT VISNING (PhD/Professor) */}
        {viewMode === 'avansert' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
              <AdvancedTradingChart />
            </div>
            <div className="space-y-6">
              <PortfolioCard />
              <RiskMetricsCard />
            </div>
            <SignalListCard limit={10} />
            <AIInsightsCard />
            <AutoTradingStatusCard />
          </div>
        )}
      </div>
    </div>
  );
}

