'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { CheckCircle2, XCircle, Lightbulb, RotateCcw } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface MiniQuizProps {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
  lessonId?: string;
  onComplete?: (isCorrect: boolean) => void;
  className?: string;
}

export function MiniQuiz({
  question,
  options,
  correctIndex,
  explanation,
  lessonId,
  onComplete,
  className,
}: MiniQuizProps) {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);

  const handleSelect = (index: number) => {
    if (isSubmitted) return;
    setSelectedIndex(index);
  };

  const handleSubmit = () => {
    if (selectedIndex === null) return;

    const correct = selectedIndex === correctIndex;
    setIsCorrect(correct);
    setIsSubmitted(true);
    onComplete?.(correct);
  };

  const handleReset = () => {
    setSelectedIndex(null);
    setIsSubmitted(false);
    setIsCorrect(false);
  };

  return (
    <Card className={cn('border-l-4 border-l-blue-500', className)}>
      <CardHeader className="pb-3">
        <div className="flex items-center gap-2 text-blue-600">
          <Lightbulb className="w-5 h-5" />
          <span className="text-sm font-medium">Hva tror du?</span>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <p className="text-lg font-medium text-gray-900">{question}</p>

        {/* Alternativer */}
        <div className="space-y-2">
          {options.map((option, index) => {
            const isSelected = selectedIndex === index;
            const isCorrectOption = index === correctIndex;
            const showCorrect = isSubmitted && isCorrectOption;
            const showWrong = isSubmitted && isSelected && !isCorrect;

            return (
              <button
                key={index}
                onClick={() => handleSelect(index)}
                disabled={isSubmitted}
                className={cn(
                  'w-full text-left p-4 rounded-lg border-2 transition-all',
                  'hover:border-blue-300',
                  isSelected && !isSubmitted && 'border-blue-500 bg-blue-50',
                  showCorrect && 'border-green-500 bg-green-50',
                  showWrong && 'border-red-500 bg-red-50',
                  !isSelected && !isSubmitted && 'border-gray-200 bg-white'
                )}
              >
                <div className="flex items-center justify-between">
                  <span className={cn(
                    'text-gray-700',
                    showCorrect && 'text-green-700 font-medium',
                    showWrong && 'text-red-700'
                  )}>
                    {option}
                  </span>
                  {showCorrect && <CheckCircle2 className="w-5 h-5 text-green-500" />}
                  {showWrong && <XCircle className="w-5 h-5 text-red-500" />}
                </div>
              </button>
            );
          })}
        </div>

        {/* Submit-knapp */}
        {!isSubmitted && (
          <Button
            onClick={handleSubmit}
            disabled={selectedIndex === null}
            className="w-full"
          >
            Sjekk svar
          </Button>
        )}

        {/* Resultat */}
        {isSubmitted && (
          <div className={cn(
            'p-4 rounded-lg',
            isCorrect ? 'bg-green-50 border border-green-200' : 'bg-orange-50 border border-orange-200'
          )}>
            <div className="flex items-center gap-2 mb-2">
              {isCorrect ? (
                <>
                  <CheckCircle2 className="w-5 h-5 text-green-600" />
                  <span className="font-semibold text-green-700">Riktig! 🎉</span>
                </>
              ) : (
                <>
                  <XCircle className="w-5 h-5 text-orange-600" />
                  <span className="font-semibold text-orange-700">Ikke helt...</span>
                </>
              )}
            </div>
            <p className="text-gray-700 text-sm leading-relaxed">{explanation}</p>

            <Button
              variant="outline"
              size="sm"
              onClick={handleReset}
              className="mt-4"
            >
              <RotateCcw className="w-4 h-4 mr-2" />
              Prøv igjen
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

