  const maskApiKey = (key: string) => {
    if (!key || key.length < 8) return "••••••••";
    return key.slice(0, 4) + "••••••••" + key.slice(-4);
  };

  const testCredentials = async () => {
    if (!form.apiKey || !form.apiSecret) {
      setErrors({ apiKey: "API Key og Secret er påkrevd" });
      return null;
    }

    setTesting(true);
    setErrors({});
    setSuccess("");

