      const response = await fetch("/api/binance/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          apiKey: form.apiKey,
          apiSecret: form.apiSecret,
          testnet: form.testnet,
