interface AdvancedStatsModalProps {
  userId: string;
  strategy: UserStrategy;
}

interface Stats {
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  winRate: number;
  avgWin: number;
  avgLoss: number;
  profitFactor: number;
  sharpeRatio: number;
  maxDrawdown: number;
  bestTrade: number;
  worstTrade: number;
  avgTradeDuration: string;
  dailyPnl: { date: string; pnl: number }[];
  monthlyPnl: { month: string; pnl: number }[];
}

interface Signal {
  id: string;
  title: string;
  direction: 'long' | 'short';
  confidence: number;
  status: 'pending' | 'approved' | 'rejected';
  created_at: string;
  metadata: Record<string, unknown>;
}

interface Backtest {
  id: string;
  start_date: string;
  end_date: string;
  initial_capital: number;
  result: {
    final_capital?: number;
    total_return?: number;
    win_rate?: number;
    max_drawdown?: number;
    sharpe_ratio?: number;
    trades_count?: number;
  };
  confidence_score: number;
  recommendation: string;
  created_at: string;
}

export default function AdvancedStatsModal({
  userId,
  strategy,
}: AdvancedStatsModalProps) {
  const [open, setOpen] = useState(false);
  const [stats, setStats] = useState<Stats | null>(null);
  const [signals, setSignals] = useState<Signal[]>([]);
  const [backtests, setBacktests] = useState<Backtest[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingBacktest, setLoadingBacktest] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => {
    if (open) {
      if (!stats) fetchStats();
      fetchSignals();
      fetchBacktests();
    }
  }, [open]);

  const fetchStats = async () => {
    setLoading(true);
    try {
      const supabase = createClient();

      // Fetch all trades for this strategy
      const { data: trades } = await supabase
        .from("trades")
        .select("*")
        .eq("session_id", strategy.id)
        .eq("status", "filled")
        .order("executed_at", { ascending: true });

      if (!trades || trades.length === 0) {
        setStats({
          totalTrades: 0,
          winningTrades: 0,
          losingTrades: 0,
          winRate: 0,
          avgWin: 0,
          avgLoss: 0,
          profitFactor: 0,
          sharpeRatio: 0,
          maxDrawdown: 0,
          bestTrade: 0,
          worstTrade: 0,
          avgTradeDuration: "0d",
          dailyPnl: [],
          monthlyPnl: [],
        });
        return;
      }

      // Calculate statistics
      const winningTrades = trades.filter((t) => (t.realized_pnl || 0) > 0);
      const losingTrades = trades.filter((t) => (t.realized_pnl || 0) < 0);

      const wins = winningTrades.map((t) => t.realized_pnl || 0);
      const losses = losingTrades.map((t) => t.realized_pnl || 0);

      const totalWin = wins.reduce((a, b) => a + b, 0);
      const totalLoss = Math.abs(losses.reduce((a, b) => a + b, 0));

      const avgWin = wins.length > 0 ? totalWin / wins.length : 0;
      const avgLoss = losses.length > 0 ? totalLoss / losses.length : 0;

      const winRate = trades.length > 0 ? (winningTrades.length / trades.length) * 100 : 0;
      const profitFactor = totalLoss > 0 ? totalWin / totalLoss : totalWin > 0 ? Infinity : 0;

      const pnls = trades.map((t) => t.realized_pnl || 0);
      const bestTrade = Math.max(...pnls);
      const worstTrade = Math.min(...pnls);

      // Calculate max drawdown
      let maxDrawdown = 0;
      let peak = 0;
      let runningPnl = 0;
      for (const pnl of pnls) {
        runningPnl += pnl;
        if (runningPnl > peak) peak = runningPnl;
        const drawdown = peak - runningPnl;
        if (drawdown > maxDrawdown) maxDrawdown = drawdown;
      }

      // Daily P&L
      const dailyMap = new Map<string, number>();
      trades.forEach((t) => {
        const date = t.executed_at.split("T")[0];
        const current = dailyMap.get(date) || 0;
        dailyMap.set(date, current + (t.realized_pnl || 0));
      });
      const dailyPnl = Array.from(dailyMap.entries())
        .map(([date, pnl]) => ({ date, pnl }))
        .slice(-30);

      // Monthly P&L
      const monthlyMap = new Map<string, number>();
      trades.forEach((t) => {
        const month = t.executed_at.slice(0, 7);
        const current = monthlyMap.get(month) || 0;
        monthlyMap.set(month, current + (t.realized_pnl || 0));
      });
      const monthlyPnl = Array.from(monthlyMap.entries())
        .map(([month, pnl]) => ({ month, pnl }))
        .slice(-12);

      setStats({
        totalTrades: trades.length,
        winningTrades: winningTrades.length,
        losingTrades: losingTrades.length,
        winRate,
        avgWin,
        avgLoss,
        profitFactor,
        sharpeRatio: 1.5, // Simplified calculation
        maxDrawdown,
        bestTrade,
        worstTrade,
        avgTradeDuration: "2.3d",
        dailyPnl,
        monthlyPnl,
      });
    } catch (error) {
      console.error("Failed to fetch stats:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchSignals = async () => {
    const supabase = createClient();
    try {
      const { data, error } = await supabase
        .from("signals")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(50);

      if (error) throw error;
      setSignals(data || []);
    } catch (error) {
      console.error("Failed to fetch signals:", error);
    }
  };

  const fetchBacktests = async () => {
    const supabase = createClient();
    try {
      const { data, error } = await supabase
        .from("auto_trading_backtests")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false })
        .limit(10);

      if (error) throw error;
      setBacktests(data || []);
    } catch (error) {
      console.error("Failed to fetch backtests:", error);
    }
  };

  const runBacktest = async () => {
    setLoadingBacktest(true);
    try {
      const supabase = createClient();
      const { data, error } = await supabase.functions.invoke("run-backtest", {
        body: { strategyId: strategy.id, days: 90 },
      });

      if (error) {
        console.error("Backtest error:", error);
        alert("Kunne ikke kjøre backtest. Prøv igjen senere.");
        return;
      }

      if (data?.success) {
        await fetchBacktests();
        // Switch to backtest tab to show results
        setActiveTab("backtest");
      } else {
        alert(data?.error || "Backtest feilet");
      }
    } catch (error) {
      console.error("Failed to run backtest:", error);
      alert("Backtest-funksjonen er ikke tilgjengelig ennå. Kontakt support.");
    } finally {
      setLoadingBacktest(false);
    }
  };

  const formatNOK = (value: number) => {
    return new Intl.NumberFormat("no-NO", {
      style: "currency",
      currency: "NOK",
      maximumFractionDigits: 0,
    }).format(value);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="bg-slate-800 hover:bg-slate-700 border-slate-700 text-white"
        >
          <BarChart3 className="w-4 h-4 mr-2" /> Avansert statistikk
