                },
                {
                  label: "Ukentlig Resultat",
                  value: pnlWeek,
                  percent: `${pnlWeek >= 0 ? "+" : ""}${((pnlWeek / (portfolio?.total_value || 1)) * 100).toFixed(2)}%`,
