            }`}
          >
            <TrendingDown className="w-4 h-4 inline mr-2" />
            SELG (SHORT)
          </button>
        </div>

        {/* Quantity */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Antall (stk)
          </label>
          <Input
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(e.target.value)}
            placeholder="0.00"
            className="text-lg font-mono"
          />
          <div className="flex justify-between mt-1">
            <span className="text-xs text-gray-500">
              Verdi: ${((parseFloat(quantity) || 0) * currentPrice).toLocaleString()}
            </span>
            <button 
              onClick={() => setQuantity((portfolio.balance / currentPrice).toFixed(4))}
              className="text-xs text-blue-600 hover:underline"
            >
              Maks
            </button>
          </div>
        </div>

        {/* Leverage */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            Leverage: {leverage}x
          </label>
          <input
            type="range"
            min="1"
            max="125"
            value={leverage}
            onChange={(e) => setLeverage(e.target.value)}
            className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer dark:bg-gray-700"
          />
          <div className="flex justify-between text-xs text-gray-500 mt-1">
            <span>1x</span>
            <span>50x</span>
            <span>125x</span>
          </div>
        </div>

        {/* Stop Loss / Take Profit */}
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Stop Loss
            </label>
            <Input
              type="number"
              value={stopLoss}
              onChange={(e) => setStopLoss(e.target.value)}
              placeholder="$0.00"
              className="font-mono"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Take Profit
            </label>
            <Input
              type="number"
              value={takeProfit}
              onChange={(e) => setTakeProfit(e.target.value)}
              placeholder="$0.00"
              className="font-mono"
            />
          </div>
        </div>

        {/* Summary */}
        <div className="bg-gray-50 dark:bg-gray-800 rounded-xl p-4 space-y-2">
          <div className="flex justify-between text-sm">
            <span className="text-gray-600 dark:text-gray-400">Margin påkrevd</span>
            <span className="font-mono font-medium">${calculateMargin().toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-gray-600 dark:text-gray-400">Handelsgebyr (0.1%)</span>
            <span className="font-mono font-medium">${calculateFee().toFixed(2)}</span>
          </div>
          <div className="border-t border-gray-200 dark:border-gray-700 pt-2 mt-2">
            <div className="flex justify-between">
              <span className="font-medium text-gray-900 dark:text-white">Total</span>
              <span className="font-mono font-bold text-gray-900 dark:text-white">
                ${(calculateMargin() + calculateFee()).toFixed(2)}
              </span>
            </div>
          </div>
        </div>

        {/* Submit Button */}
        <AnimatePresence>
          {isValid && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              <Button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className={`w-full py-4 text-lg font-bold rounded-xl transition-all ${
                  side === 'long'
                    ? 'bg-green-600 hover:bg-green-700 text-white'
                    : 'bg-red-600 hover:bg-red-700 text-white'
                }`}
              >
                {isSubmitting ? 'Åpner posisjon...' : `${side === 'long' ? 'KJØP' : 'SELG'} ${selectedSymbol}`}
              </Button>
            </motion.div>
          )}
        </AnimatePresence>

        {!isValid && quantity && (
          <p className="text-sm text-red-600 text-center">
            {calculateMargin() > portfolio.balance 
              ? 'Ikke nok margin tilgjengelig' 
              : 'Vennligst fyll inn antall'}
          </p>
        )}
      </div>
    </div>
  );
}

'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { format } from 'date-fns'
import { nb, enUS } from 'date-fns/locale'
import { useLocale, useTranslations } from 'next-intl'

interface Order {
    id: string
    symbol: string
    side: 'buy' | 'sell'
    qty: number
    price: number
    created_at: string
    status: string
}

export function OrderHistory() {
    const t = useTranslations('orderHistory')
    const locale = useLocale()
    const [orders, setOrders] = useState<Order[]>([])
    const [loading, setLoading] = useState(true)

    const fetchOrders = async () => {
        const supabase = createClient()
        const { data: { user } } = await supabase.auth.getUser()

        if (!user) return

        const { data, error } = await supabase
            .from('trades')
            .select('*')
            .eq('user_id', user.id)
            .order('created_at', { ascending: false })
            .limit(10)

        if (data) setOrders(data as Order[])
        setLoading(false)
    }

    useEffect(() => {
        fetchOrders()

        // Optional: Realtime subscription could go here
    }, [])

    if (loading) return <div className="text-slate-500 text-sm">{t('loading')}</div>
    if (orders.length === 0) return <div className="text-slate-500 text-sm">{t('noOrders')}</div>

    return (
        <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-400 uppercase bg-slate-800/50">
                    <tr>
                        <th className="px-4 py-3">{t('date')}</th>
                        <th className="px-4 py-3">{t('pair')}</th>
                        <th className="px-4 py-3">{t('side')}</th>
                        <th className="px-4 py-3">{t('price')}</th>
                        <th className="px-4 py-3">{t('amount')}</th>
                        <th className="px-4 py-3">{t('total')}</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-800">
                    {orders.map((order) => (
                        <tr key={order.id} className="bg-slate-900/50 hover:bg-slate-800 transition-colors">
                            <td className="px-4 py-3 text-slate-300">
                                {format(new Date(order.created_at), 'dd.MM HH:mm', { locale: locale === 'no' ? nb : enUS })}
                            </td>
                            <td className="px-4 py-3 font-medium text-white">{order.symbol}</td>
                            <td className={`px-4 py-3 font-semibold ${order.side === 'buy' ? 'text-green-400' : 'text-red-400'}`}>
                                {order.side === 'buy' ? t('buy') : t('sell')}
                            </td>
                            <td className="px-4 py-3 text-slate-300">{order.price.toLocaleString(locale === 'no' ? 'no-NO' : 'en-US')}</td>
                            <td className="px-4 py-3 text-slate-300">{order.qty}</td>
                            <td className="px-4 py-3 text-slate-300">{(order.qty * order.price).toLocaleString(locale === 'no' ? 'no-NO' : 'en-US')}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    )
}

