export function useAnalytics() {
  const pathname = usePathname();
  const sessionId = useRef(getSessionId());
  const userId = useRef<string | null>(null);

  // Get user ID on mount
  useEffect(() => {
    getUserId().then((id) => {
      userId.current = id;
    });
  }, []);

  // Track page view
  useEffect(() => {
    if (!pathname) return;

    const trackView = async () => {
      try {
        await fetch('/api/analytics/track', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            session_id: sessionId.current,
            user_id: userId.current,
            page_path: pathname,
            referrer: document.referrer,
            user_agent: navigator.userAgent,
          }),
        });
      } catch (error) {
        // Silent fail for analytics
        console.debug('Analytics error:', error);
      }
    };

    trackView();
  }, [pathname]);

  // Track custom event
  const trackEvent = useCallback(async (
    eventType: string,
    metadata?: Record<string, unknown>,
    value?: number
  ) => {
    try {
      await fetch('/api/analytics/event', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          session_id: sessionId.current,
          user_id: userId.current,
          event_type: eventType,
          page_path: pathname,
          metadata,
          value,
        }),
      });
    } catch (error) {
      console.debug('Analytics error:', error);
    }
  }, [pathname]);

  // Track CTA click
  const trackCTA = useCallback((ctaName: string, location: string) => {
    trackEvent('click_cta', { cta_name: ctaName, location });
  }, [trackEvent]);

  // Track signup start
  const trackSignupStart = useCallback((plan?: string) => {
    trackEvent('start_signup', { plan });
  }, [trackEvent]);

  // Track pricing view
  const trackPricingView = useCallback(() => {
    trackEvent('view_pricing');
  }, [trackEvent]);

  return {
    trackEvent,
    trackCTA,
    trackSignupStart,
    trackPricingView,
  };
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import {
  isPushSupported,
  requestNotificationPermission,
  subscribeToPush,
  unsubscribeFromPush,
  getPushSubscription,
} from '@/lib/notifications/push';

interface Notification {
  id: string;
  title: string;
  body: string;
  is_read: boolean;
  created_at: string;
  category: string;
  action_url?: string;
}

interface NotificationPreferences {
  price_alerts: boolean;
  trade_executed: boolean;
  course_reminder: boolean;
  marketing_emails: boolean;
}

export function useNotifications() {
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isSupported, setIsSupported] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [preferences, setPreferences] = useState<NotificationPreferences | null>(null);
  const [loading, setLoading] = useState(true);

  const supabase = createClient();

  // Initialize
  useEffect(() => {
    setIsSupported(isPushSupported());

    if (typeof window !== 'undefined' && 'Notification' in window) {
      setPermission(Notification.permission);
    }

    checkSubscription();
    fetchNotifications();
    fetchPreferences();
  }, []);

  // Check push subscription status
  const checkSubscription = async () => {
    if (!isPushSupported()) return;

    const subscription = await getPushSubscription();
    setIsSubscribed(!!subscription);
  };

  // Fetch notifications from server
  const fetchNotifications = async () => {
    try {
      const { data, error } = await supabase
        .from('notifications')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(50);

      if (error) throw error;

      setNotifications(data || []);

      // Calculate unread count
      const unread = (data || []).filter(n => !n.is_read).length;
      setUnreadCount(unread);
    } catch (error) {
      console.error('Error fetching notifications:', error);
    }
  };

  // Fetch preferences
  const fetchPreferences = async () => {
    try {
      const { data, error } = await supabase
        .from('notification_preferences')
        .select('*')
        .single();

      if (error && error.code !== 'PGRST116') throw error;

      setPreferences(data || {
        price_alerts: true,
        trade_executed: true,
        course_reminder: true,
        marketing_emails: false,
      });
    } catch (error) {
      console.error('Error fetching preferences:', error);
    } finally {
      setLoading(false);
    }
  };

  // Request permission and subscribe
  const subscribe = async () => {
    try {
      const perm = await requestNotificationPermission();
      setPermission(perm);

      if (perm === 'granted') {
        const subscription = await subscribeToPush();
        setIsSubscribed(!!subscription);
        return true;
      }
      return false;
    } catch (error) {
      console.error('Error subscribing:', error);
      return false;
    }
  };

  // Unsubscribe
  const unsubscribe = async () => {
    try {
      const success = await unsubscribeFromPush();
      if (success) {
        setIsSubscribed(false);
      }
      return success;
    } catch (error) {
      console.error('Error unsubscribing:', error);
      return false;
    }
  };

  // Mark notifications as read
  const markAsRead = async (notificationIds?: string[]) => {
    try {
      const { error } = await supabase.rpc('mark_notifications_read', {
        p_notification_ids: notificationIds || null,
      });

      if (error) throw error;

      // Update local state
      if (notificationIds) {
        setNotifications(prev =>
          prev.map(n =>
            notificationIds.includes(n.id) ? { ...n, is_read: true } : n
          )
        );
        setUnreadCount(prev => Math.max(0, prev - notificationIds.length));
      } else {
        setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
        setUnreadCount(0);
      }
    } catch (error) {
      console.error('Error marking as read:', error);
    }
  };

  // Update preferences
  const updatePreferences = async (newPrefs: Partial<NotificationPreferences>) => {
    try {
      const { error } = await supabase
        .from('notification_preferences')
        .upsert({ ...preferences, ...newPrefs });

      if (error) throw error;

      setPreferences(prev => prev ? { ...prev, ...newPrefs } : null);
      return true;
    } catch (error) {
      console.error('Error updating preferences:', error);
      return false;
    }
  };

  // Real-time subscription for new notifications
  useEffect(() => {
    const subscription = supabase
      .channel('notifications')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications',
        },
        (payload) => {
          const newNotification = payload.new as Notification;
          setNotifications(prev => [newNotification, ...prev]);
          if (!newNotification.is_read) {
            setUnreadCount(prev => prev + 1);
          }
        }
      )
      .subscribe();

    return () => {
      subscription.unsubscribe();
    };
  }, [supabase]);

  return {
    permission,
    isSubscribed,
    isSupported,
    notifications,
    unreadCount,
    preferences,
    loading,
    subscribe,
    unsubscribe,
    markAsRead,
    updatePreferences,
    refresh: fetchNotifications,
  };
}

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { usePathname } from 'next/navigation';
import { useAuth } from '@/hooks/useAuth';

interface PageViewData {
  path: string;
  userId?: string;
  sessionId: string;
  referrer: string;
  userAgent: string;
  timeSpent: number;
}

interface TrackingEvent {
  type: string;
  data: Record<string, unknown>;
  timestamp: number;
}

// Generate or retrieve session ID
function getSessionId(): string {
  if (typeof window === 'undefined') return '';

  let sessionId = sessionStorage.getItem('analytics_session_id');
  if (!sessionId) {
    sessionId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    sessionStorage.setItem('analytics_session_id', sessionId);
  }
  return sessionId;
}

// Get or create visitor ID (persists across sessions)
function getVisitorId(): string {
  if (typeof window === 'undefined') return '';

  let visitorId = localStorage.getItem('analytics_visitor_id');
  if (!visitorId) {
    visitorId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    localStorage.setItem('analytics_visitor_id', visitorId);
  }
  return visitorId;
}

// Debounce function
function debounce<T extends (...args: Parameters<T>) => ReturnType<T>>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout;
  return (...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

// Track page view
async function trackPageView(data: PageViewData) {
  try {
    await fetch('/api/analytics/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: data.sessionId,
        user_id: data.userId || null,
        page_path: data.path,
        referrer: data.referrer,
        user_agent: data.userAgent,
        time_spent: data.timeSpent,
      }),
    });
  } catch (error) {
    // Silently fail - analytics should not break the app
    console.debug('Analytics track error:', error);
  }
}

// Track custom event
async function trackEvent(eventType: string, eventData: Record<string, unknown> = {}) {
  try {
    const sessionId = getSessionId();
    const visitorId = getVisitorId();

    await fetch('/api/analytics/event', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: sessionId,
        visitor_id: visitorId,
        event_type: eventType,
        event_data: eventData,
        page_path: window.location.pathname,
      }),
    });
  } catch (error) {
    console.debug('Analytics event error:', error);
  }
}

export function usePageTracking() {
  const pathname = usePathname();
  const { user } = useAuth();
  const startTimeRef = useRef<number>(Date.now());
  const sessionIdRef = useRef<string>('');
  const lastPathRef = useRef<string>('');

  // Initialize session ID
  useEffect(() => {
    if (typeof window !== 'undefined') {
      sessionIdRef.current = getSessionId();
      getVisitorId(); // Ensure visitor ID exists
    }
  }, []);

  // Track page view on path change
  useEffect(() => {
    if (!pathname || typeof window === 'undefined') return;

    // Calculate time spent on previous page
    const timeSpent = Math.floor((Date.now() - startTimeRef.current) / 1000);

    // Track the previous page's time spent if there was one
    if (lastPathRef.current && lastPathRef.current !== pathname) {
      trackPageView({
        path: lastPathRef.current,
        userId: user?.id,
        sessionId: sessionIdRef.current,
        referrer: document.referrer,
        userAgent: navigator.userAgent,
        timeSpent,
      });
    }

    // Reset timer for new page
    startTimeRef.current = Date.now();
    lastPathRef.current = pathname;

    // Track new page view after a short delay (to ensure page is actually viewed)
    const timer = setTimeout(() => {
      trackPageView({
        path: pathname,
        userId: user?.id,
        sessionId: sessionIdRef.current,
        referrer: document.referrer,
        userAgent: navigator.userAgent,
        timeSpent: 0,
      });
    }, 1000);

    return () => clearTimeout(timer);
  }, [pathname, user?.id]);

  // Track scroll depth
  useEffect(() => {
    if (typeof window === 'undefined') return;

    let maxScrollDepth = 0;
    const milestones = [25, 50, 75, 90];
    const trackedMilestones = new Set<number>();

    const handleScroll = debounce(() => {
      const scrollTop = window.scrollY;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      const scrollPercent = docHeight > 0 ? Math.round((scrollTop / docHeight) * 100) : 0;

      maxScrollDepth = Math.max(maxScrollDepth, scrollPercent);

      // Track milestones
      milestones.forEach((milestone) => {
        if (scrollPercent >= milestone && !trackedMilestones.has(milestone)) {
          trackedMilestones.add(milestone);
          trackEvent('scroll_depth', {
            depth: milestone,
            page_path: pathname,
          });
        }
      });
    }, 250);

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [pathname]);

  // Track time on page (heartbeat)
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const heartbeatInterval = setInterval(() => {
      const timeSpent = Math.floor((Date.now() - startTimeRef.current) / 1000);

      // Send heartbeat every 30 seconds
      if (timeSpent > 0 && timeSpent % 30 === 0) {
        trackEvent('heartbeat', {
          page_path: pathname,
          time_spent: timeSpent,
        });
      }
    }, 30000);

    return () => clearInterval(heartbeatInterval);
  }, [pathname]);

  // Track before unload
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleBeforeUnload = () => {
      const timeSpent = Math.floor((Date.now() - startTimeRef.current) / 1000);

      // Use sendBeacon for reliable tracking on page close
      if (navigator.sendBeacon) {
        const data = JSON.stringify({
          session_id: sessionIdRef.current,
          user_id: user?.id,
          page_path: pathname,
          time_spent: timeSpent,
        });
        navigator.sendBeacon('/api/analytics/track', new Blob([data], { type: 'application/json' }));
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [pathname, user?.id]);

  // Return tracking utilities
  const trackClick = useCallback((elementName: string, additionalData: Record<string, unknown> = {}) => {
    trackEvent('click', {
      element: elementName,
      page_path: pathname,
      ...additionalData,
    });
  }, [pathname]);

  const trackConversion = useCallback((conversionType: string, value?: number) => {
    trackEvent('conversion', {
      type: conversionType,
      value,
      page_path: pathname,
    });
  }, [pathname]);

  const trackError = useCallback((errorType: string, errorMessage: string) => {
    trackEvent('error', {
      type: errorType,
      message: errorMessage,
      page_path: pathname,
      user_agent: navigator.userAgent,
    });
  }, [pathname]);

  return {
    trackEvent,
    trackClick,
    trackConversion,
    trackError,
    sessionId: sessionIdRef.current,
    visitorId: getVisitorId(),
  };
}

// Hook for tracking specific elements
export function useElementTracking(elementName: string) {
  const { trackClick } = usePageTracking();

  const onClick = useCallback(() => {
    trackClick(elementName);
  }, [elementName, trackClick]);

  return { onClick };
}

export default usePageTracking;

