  maxTradesPerDay: number;
  enabled: boolean;
  useAI: boolean; // Use Cloudflare AI or rule-based
  confidenceThreshold: number; // Minimum confidence to execute (0-1)
}

export interface TradeDecision {
  symbol: string;
  action: 'BUY' | 'SELL' | 'HOLD';
  confidence: number;
  targetPrice: number;
  stopLoss: number;
  reason: string;
