const CACHE_TTL = 30 * 1000; // 30 seconds

/**
 * Hent market data fra CoinLore (100% gratis, ranked #1)
 * https://www.coinlore.com/cryptocurrency-data-api
 */
export async function getMarketData(symbols: string[]): Promise<CoinData[]> {
