// Simulated trade for backtest
interface SimulatedTrade {
  entryTime: number;
  exitTime?: number;
  entryPrice: number;
  exitPrice?: number;
  quantity: number;
  side: 'LONG' | 'SHORT';
  pnl: number;
  pnlPercent: number;
  exitReason: 'stop_loss' | 'take_profit' | 'signal' | 'end_of_data';
}

// Minimum requirements for strategy to be approved
const VALIDATION_THRESHOLDS = {
  minTotalReturn: 0,
  maxDrawdown: -0.25,
  minSharpeRatio: 0.5,
  minWinRate: 0.4,
