// ============================================================================

export interface CircuitBreakerCheck {
  passed: boolean;
  triggered?: string;
  level?: "trade" | "daily" | "weekly" | "strategy" | "account";
  action: "allow" | "warn" | "block";
  reason?: string;
  cooldownUntil?: Date;
  suggestions?: string[];
}

export interface RiskCheckInput {
  userId: string;
  sessionId: string;
  strategy: AutoTradingStrategy;
  config: UserAutoTradingConfig;
  circuitBreaker: CircuitBreakerConfig;
  currentPortfolioValue: number;
  todaysTrades: AutoTradingTrade[];
  weeksTrades: AutoTradingTrade[];
  allTrades: AutoTradingTrade[];
  consecutiveLosses: number;
  currentDrawdown: number; // From peak
}

/**
 * Comprehensive circuit breaker check
 */
export function checkCircuitBreakers(
  input: RiskCheckInput,
): CircuitBreakerCheck {
  const {
    circuitBreaker,
    currentPortfolioValue,
    todaysTrades,
    weeksTrades,
    allTrades,
    consecutiveLosses,
    currentDrawdown,
  } = input;

  // 1. Check account-level drawdown (highest priority)
  if (currentDrawdown >= circuitBreaker.accountDrawdownLimit) {
    return {
      passed: false,
      triggered: "account_drawdown",
      level: "account",
      action: "block",
      reason:
        `Kritisk drawdown på ${(currentDrawdown * 100).toFixed(1)}% (grense: ${(circuitBreaker.accountDrawdownLimit * 100).toFixed(0)}%). ` +
        "All trading stoppet for å beskytte kapital.",
      suggestions: [
        "Ta en pause på minst 1 uke",
        "Re-evaluer hele strategien",
        "Vurder å redusere risikonivå",
        "Kontakt support for hjelp",
      ],
    };
  }

  // 2. Check strategy-level drawdown
  if (currentDrawdown >= circuitBreaker.strategyDrawdownLimit) {
    const cooldownDays = circuitBreaker.strategyCooldownDays;
    const cooldownUntil = new Date();
    cooldownUntil.setDate(cooldownUntil.getDate() + cooldownDays);

    return {
      passed: false,
      triggered: "strategy_drawdown",
      level: "strategy",
      action: "block",
      reason:
        `Strategi drawdown på ${(currentDrawdown * 100).toFixed(1)}% (grense: ${(circuitBreaker.strategyDrawdownLimit * 100).toFixed(0)}%). ` +
        `Trading pauset i ${cooldownDays} dager.`,
      cooldownUntil,
      suggestions: [
        "Analyser hva som gikk galt",
        "Vurder å bytte strategi",
        "Reduser posisjonsstørrelse ved gjenstart",
        "Sjekk markedssentiment",
      ],
    };
  }

  // 3. Check consecutive losses
  if (consecutiveLosses >= circuitBreaker.maxConsecutiveLosses) {
    return {
      passed: false,
      triggered: "consecutive_losses",
      level: "strategy",
      action: "block",
      reason: `${consecutiveLosses} tap på rad. Strategi trenger en pause for å unngå "revenge trading".`,
      cooldownUntil: new Date(Date.now() + 24 * 60 * 60 * 1000), // 24h
      suggestions: [
        "Ikke jage tap - markedet vil alltid være der",
        "Bruk pausen til å analysere",
        "Sjekk om markedet har endret seg",
        "Vurder å redusere risiko ved gjenstart",
      ],
    };
  }

  // 4. Check weekly loss limit
  const weeklyLoss = calculatePeriodLoss(weeksTrades);
  if (weeklyLoss >= circuitBreaker.weeklyLossLimit) {
    return {
      passed: false,
      triggered: "weekly_loss_limit",
      level: "weekly",
      action: "block",
      reason:
        `Ukentlig tap på ${(weeklyLoss * 100).toFixed(1)}% (grense: ${(circuitBreaker.weeklyLossLimit * 100).toFixed(0)}%). ` +
        "Trading pauset til neste uke.",
      suggestions: [
        "God uke er over - beskytte kapital",
        "Analyser ukens trades",
        "Forbered strategi for neste uke",
      ],
    };
  }

  // 5. Check daily loss limit
  const dailyLoss = calculatePeriodLoss(todaysTrades);
  if (dailyLoss >= circuitBreaker.dailyLossLimit) {
    const cooldownHours = circuitBreaker.dailyCooldownHours;
    const cooldownUntil = new Date();
    cooldownUntil.setHours(cooldownUntil.getHours() + cooldownHours);

    return {
      passed: false,
      triggered: "daily_loss_limit",
      level: "daily",
      action: "block",
      reason:
        `Daglig tap på ${(dailyLoss * 100).toFixed(1)}% (grense: ${(circuitBreaker.dailyLossLimit * 100).toFixed(1)}%). ` +
        `Trading pauset i ${cooldownHours} timer.`,
      cooldownUntil,
      suggestions: [
        "Dagens trading er ferdig",
        "Ta en pause - kom tilbake i morgen",
        "Analyser hva som gikk galt",
        "Husk: kapitalbevaring er viktigst",
      ],
    };
  }

  // 6. Check max trades per day
  if (todaysTrades.length >= circuitBreaker.maxTradesPerDay) {
    return {
      passed: false,
      triggered: "max_trades_daily",
      level: "daily",
      action: "block",
      reason: `Maks ${circuitBreaker.maxTradesPerDay} trades per dag nådd. Overtrading prevention.`,
      suggestions: [
        "Kvalitet over kvantitet",
        "For mange trades øker transaksjonskostnader",
        "Vent til i morgen for nye muligheter",
      ],
    };
  }

  // 7. Check daily win limit (optional profit taking)
  if (circuitBreaker.dailyWinLimit) {
    const dailyProfit = calculatePeriodProfit(todaysTrades);
    if (dailyProfit >= circuitBreaker.dailyWinLimit) {
      return {
        passed: false,
        triggered: "daily_win_limit",
        level: "daily",
        action: "warn",
        reason:
          `Daglig gevinst på ${(dailyProfit * 100).toFixed(1)}% (mål: ${(circuitBreaker.dailyWinLimit * 100).toFixed(1)}%). ` +
          "Du kan fortsette, men vurder å sikre gevinsten.",
        suggestions: [
          "🎉 Bra jobbet! Vurder å ta gevinsten",
          "Ikke vær grådig - en god dag er en god dag",
          "Fortsett kun hvis setup er A+ kvalitet",
        ],
      };
    }
  }

  // All checks passed
  return {
    passed: true,
    action: "allow",
  };
}

function calculatePeriodLoss(trades: AutoTradingTrade[]): number {
  const closedTrades = trades.filter(
    (t) => t.status === "CLOSED" && t.realized_pnl !== null,
  );
  if (closedTrades.length === 0) return 0;

  const totalPnl = closedTrades.reduce(
    (sum, t) => sum + (t.realized_pnl || 0),
    0,
  );
  const totalInvested = closedTrades.reduce((sum, t) => sum + t.amount, 0);

  return totalInvested > 0
    ? Math.abs(Math.min(0, totalPnl / totalInvested))
    : 0;
}

function calculatePeriodProfit(trades: AutoTradingTrade[]): number {
  const closedTrades = trades.filter(
    (t) => t.status === "CLOSED" && t.realized_pnl !== null,
  );
  if (closedTrades.length === 0) return 0;

  const totalPnl = closedTrades.reduce(
    (sum, t) => sum + (t.realized_pnl || 0),
    0,
  );
  const totalInvested = closedTrades.reduce((sum, t) => sum + t.amount, 0);

  return totalInvested > 0 ? Math.max(0, totalPnl / totalInvested) : 0;
}

// ============================================================================
// STOP LOSS & TAKE PROFIT CALCULATIONS
// ============================================================================

export interface ExitLevels {
  stopLoss: number;
  takeProfit: number;
  trailingStop?: number;
  breakeven?: number;
  partialExit1?: number;
  partialExit2?: number;
}

/**
 * Calculate exit levels for a trade
 */
export function calculateExitLevels(
  entryPrice: number,
  direction: "LONG" | "SHORT",
  strategy: AutoTradingStrategy,
  volatility: number,
  atr: number,
): ExitLevels {
  const config = CIRCUIT_BREAKER_DEFAULTS[strategy.risk_level];

  // Base percentages
  let stopLossPercent = config.stopLossPercent;
  let takeProfitPercent = config.takeProfitPercent;

  // Adjust for volatility (ATR-based)
  const atrMultiplier = 2.0;
  const atrStopLoss = (atr * atrMultiplier) / entryPrice;

  // Use wider of fixed % or ATR-based
  stopLossPercent = Math.max(stopLossPercent, atrStopLoss);

  // Ensure minimum risk:reward of 1:1.5
  if (takeProfitPercent / stopLossPercent < 1.5) {
    takeProfitPercent = stopLossPercent * 1.5;
  }

  // Calculate actual prices
  const multiplier = direction === "LONG" ? 1 : -1;

  const stopLoss =
    direction === "LONG"
      ? entryPrice * (1 - stopLossPercent)
      : entryPrice * (1 + stopLossPercent);

  const takeProfit =
    direction === "LONG"
      ? entryPrice * (1 + takeProfitPercent)
      : entryPrice * (1 - takeProfitPercent);

  // Trailing stop (starts at 50% toward TP)
  const trailingDistance = stopLossPercent * 1.5;

  // Partial exits
  const partialExit1 =
    entryPrice + (takeProfit - entryPrice) * 0.5 * multiplier;
  const partialExit2 =
    entryPrice + (takeProfit - entryPrice) * 0.75 * multiplier;

  // Breakeven (when 50% to TP)
  const breakeven = entryPrice + (takeProfit - entryPrice) * 0.5 * multiplier;

  return {
    stopLoss,
    takeProfit,
    trailingStop: trailingDistance,
    breakeven,
    partialExit1,
    partialExit2,
  };
}

// ============================================================================
// REAL-TIME RISK MONITORING
// ============================================================================

export interface RiskStatus {
  portfolioValue: number;
  peakValue: number;
  currentDrawdown: number;
  dailyPnl: number;
  weeklyPnl: number;
  openRisk: number; // Sum of risk in open positions
  availableRisk: number; // Remaining risk budget for today
  consecutiveLosses: number;
  tradesToday: number;
  maxTradesToday: number;
  circuitBreakerStatus: "normal" | "warning" | "blocked";
  warnings: string[];
}

/**
 * Get current risk status for dashboard display
 */
export function calculateRiskStatus(
  portfolioValue: number,
  peakValue: number,
  todaysTrades: AutoTradingTrade[],
  weeksTrades: AutoTradingTrade[],
  openTrades: AutoTradingTrade[],
  config: CircuitBreakerConfig,
): RiskStatus {
  const currentDrawdown =
    peakValue > 0 ? (peakValue - portfolioValue) / peakValue : 0;

  // Calculate PnL
  const dailyPnl = todaysTrades.reduce((sum, t) => {
    if (t.status === "CLOSED") return sum + (t.realized_pnl || 0);
    return sum + (t.unrealized_pnl || 0);
  }, 0);

  const weeklyPnl = weeksTrades.reduce((sum, t) => {
    if (t.status === "CLOSED") return sum + (t.realized_pnl || 0);
    return sum + (t.unrealized_pnl || 0);
  }, 0);

  // Calculate open risk
  const openRisk = openTrades.reduce((sum, t) => {
    const stopDistance = Math.abs(t.entry_price - t.stop_loss) / t.entry_price;
    return sum + t.amount * stopDistance;
  }, 0);

  // Available risk budget
  const dailyLossUsed = calculatePeriodLoss(todaysTrades);
  const availableRisk =
    (config.dailyLossLimit - dailyLossUsed) * portfolioValue;

  // Consecutive losses
  const sortedTrades = [...todaysTrades, ...weeksTrades]
    .filter((t) => t.status === "CLOSED")
    .sort(
      (a, b) =>
        new Date(b.closed_at!).getTime() - new Date(a.closed_at!).getTime(),
    );

  let consecutiveLosses = 0;
  for (const trade of sortedTrades) {
    if ((trade.realized_pnl || 0) < 0) consecutiveLosses++;
    else break;
  }

  // Determine status
  let circuitBreakerStatus: "normal" | "warning" | "blocked" = "normal";
  const warnings: string[] = [];

  if (currentDrawdown >= config.accountDrawdownLimit * 0.8) {
    circuitBreakerStatus = "blocked";
    warnings.push("🚨 Nærmer seg kritisk drawdown - trading vil stoppes");
  } else if (currentDrawdown >= config.strategyDrawdownLimit * 0.8) {
    circuitBreakerStatus = "warning";
    warnings.push("⚠️ Høy drawdown - vurder å redusere risiko");
  }

  if (dailyLossUsed >= config.dailyLossLimit * 0.8) {
    circuitBreakerStatus =
      circuitBreakerStatus === "blocked" ? "blocked" : "warning";
    warnings.push("⚠️ Nærmer seg daglig tapsgrense");
  }

  if (consecutiveLosses >= config.maxConsecutiveLosses - 1) {
    circuitBreakerStatus =
      circuitBreakerStatus === "blocked" ? "blocked" : "warning";
    warnings.push(
      `⚠️ ${consecutiveLosses} tap på rad - neste tap pauser trading`,
    );
  }

  return {
    portfolioValue,
    peakValue,
    currentDrawdown,
    dailyPnl,
    weeklyPnl,
    openRisk,
    availableRisk: Math.max(0, availableRisk),
    consecutiveLosses,
    tradesToday: todaysTrades.length,
    maxTradesToday: config.maxTradesPerDay,
    circuitBreakerStatus,
    warnings,
  };
}

// ============================================================================
// CORRELATION RISK
// ============================================================================

/**
 * Check for excessive correlation in portfolio
 * Don't put all eggs in similar baskets
 */
export function checkCorrelationRisk(
  openTrades: AutoTradingTrade[],
  newTradeSymbol: string,
  correlationMatrix: Map<string, Map<string, number>>,
): { allowed: boolean; reason?: string } {
  if (openTrades.length === 0) return { allowed: true };

  const CORRELATION_THRESHOLD = 0.85;
  const MAX_CORRELATED_POSITIONS = 2;

  let correlatedPositions = 0;
  const correlatedSymbols: string[] = [];

  for (const trade of openTrades) {
    const correlation =
      correlationMatrix.get(trade.symbol)?.get(newTradeSymbol) || 0;
    if (correlation > CORRELATION_THRESHOLD) {
      correlatedPositions++;
      correlatedSymbols.push(trade.symbol);
    }
  }

  if (correlatedPositions >= MAX_CORRELATED_POSITIONS) {
    return {
      allowed: false,
      reason:
        `${newTradeSymbol} er høyt korrelert med ${correlatedSymbols.join(", ")}. ` +
        "Diversifisering kreves - velg en ukorrelert asset.",
    };
  }

  return { allowed: true };
}

// ============================================================================
// PORTFOLIO HEAT (TOTAL RISK EXPOSURE)
// ============================================================================

/**
 * Calculate total portfolio heat (sum of all open position risks)
 * Should not exceed certain threshold (e.g., 25% of portfolio)
 */
export function calculatePortfolioHeat(
  openTrades: AutoTradingTrade[],
  portfolioValue: number,
): {
  totalHeat: number;
  heatPercent: number;
  status: "safe" | "warm" | "hot" | "critical";
  maxNewPositionSize: number;
} {
  const totalHeat = openTrades.reduce((sum, t) => {
    const stopDistance = Math.abs(t.entry_price - t.stop_loss) / t.entry_price;
    return sum + t.amount * stopDistance;
  }, 0);

  const heatPercent = portfolioValue > 0 ? totalHeat / portfolioValue : 0;

  let status: "safe" | "warm" | "hot" | "critical";
  if (heatPercent > 0.25) status = "critical";
  else if (heatPercent > 0.2) status = "hot";
  else if (heatPercent > 0.15) status = "warm";
  else status = "safe";

  // Max new position based on remaining heat budget
  const maxHeat = portfolioValue * 0.25;
  const remainingHeat = maxHeat - totalHeat;
  const maxNewPositionSize = remainingHeat / 0.1; // Assume 10% stop loss

  return {
    totalHeat,
    heatPercent,
    status,
    maxNewPositionSize: Math.max(0, maxNewPositionSize),
  };
}

/**
 * Aggressive Strategy
 * Momentum + Volatility Breakout - High risk, leverage
 *
 * Strategy:
 * - Trades top 20 cryptocurrencies
 * - Focuses on high-momentum moves and volatility breakouts
 * - Uses higher leverage (2x)
 * - Wider stop-loss (12%)
 * - Both long and short positions
 * - Expected annual return: 60%
 */

import { BaseStrategy, MarketData, TechnicalIndicators } from './base-strategy'
import type { TradingSignal } from '../types'

export class AggressiveStrategy extends BaseStrategy {
  private readonly TOP_20_COINS = [
    'BTCUSDT',
    'ETHUSDT',
    'BNBUSDT',
    'SOLUSDT',
    'XRPUSDT',
    'ADAUSDT',
    'DOGEUSDT',
    'AVAXUSDT',
    'DOTUSDT',
    'MATICUSDT',
    'LINKUSDT',
    'LTCUSDT',
    'UNIUSDT',
    'ATOMUSDT',
    'NEARUSDT',
    'APTUSDT',
    'ARBUSDT',
    'OPUSDT',
    'SUIUSDT',
    'INJUSDT',
  ]

  async analyze(
    marketData: MarketData,
    indicators: TechnicalIndicators
  ): Promise<TradingSignal | null> {
    // Only trade top 20 coins
    if (!this.TOP_20_COINS.includes(marketData.symbol)) {
      return null
    }

    const rsi = indicators.rsi || 50
    const priceChange24h = marketData.price_change_24h
    const volatility = this.calculateVolatility(marketData)

    // Strategy 1: Momentum trading (chase strong moves)
    const momentumSignal = this.analyzeMomentum(
      marketData,
      indicators,
      rsi,
      priceChange24h,
      volatility
    )

    if (momentumSignal) {
      return momentumSignal
    }

    // Strategy 2: Volatility breakout (trade high volatility)
    const volatilitySignal = this.analyzeVolatilityBreakout(
      marketData,
      indicators,
      rsi,
      priceChange24h,
      volatility
    )

    return volatilitySignal
  }

  private analyzeMomentum(
    marketData: MarketData,
    indicators: TechnicalIndicators,
    rsi: number,
    priceChange24h: number,
    volatility: number
  ): TradingSignal | null {
    // LONG: Strong upward momentum
    const hasStrongUpMomentum = priceChange24h > 12 // Price up > 12%
    const rsiConfirmsUp = rsi > 60 && rsi < 80
    const hasHighVolume = marketData.volume_24h > 5000000

    if (hasStrongUpMomentum && rsiConfirmsUp && hasHighVolume) {
      const confidence = this.calculateMomentumConfidence(priceChange24h, rsi, marketData.volume_24h)

      return this.createSignal(
        marketData,
        indicators,
        'LONG',
        confidence,
        `Aggressive momentum: +${priceChange24h.toFixed(1)}%, RSI ${rsi.toFixed(0)}, High volume`
      )
    }

    // SHORT: Strong downward momentum (if allowed)
    if (this.strategy.allow_short) {
      const hasStrongDownMomentum = priceChange24h < -12
      const rsiConfirmsDown = rsi < 40 && rsi > 20

      if (hasStrongDownMomentum && rsiConfirmsDown && hasHighVolume) {
        const confidence = this.calculateMomentumConfidence(
          Math.abs(priceChange24h),
          100 - rsi,
          marketData.volume_24h
        )

        return this.createSignal(
          marketData,
          indicators,
          'SHORT',
          confidence,
          `Aggressive sell momentum: ${priceChange24h.toFixed(1)}%, RSI ${rsi.toFixed(0)}, High volume`
        )
      }
    }

    return null
  }

  private analyzeVolatilityBreakout(
    marketData: MarketData,
    indicators: TechnicalIndicators,
    rsi: number,
    priceChange24h: number,
    volatility: number
  ): TradingSignal | null {
    // Look for high volatility with directional bias
    const isHighVolatility = volatility > 15 // > 15% daily range
    const hasVolume = marketData.volume_24h > 2000000

    if (!isHighVolatility || !hasVolume) {
      return null
    }

    // Determine direction based on price position in range
    const rangePosition = (marketData.price - marketData.low_24h) / (marketData.high_24h - marketData.low_24h)

    // LONG: Price in upper 25% of range + positive change
    if (rangePosition > 0.75 && priceChange24h > 5) {
      const confidence = this.calculateVolatilityConfidence(volatility, rangePosition, priceChange24h)

      return this.createSignal(
        marketData,
        indicators,
        'LONG',
        confidence,
        `Volatility breakout UP: ${volatility.toFixed(1)}% range, price at ${(rangePosition * 100).toFixed(0)}% of range`
      )
    }

    // SHORT: Price in lower 25% of range + negative change (if allowed)
    if (this.strategy.allow_short && rangePosition < 0.25 && priceChange24h < -5) {
      const confidence = this.calculateVolatilityConfidence(volatility, 1 - rangePosition, Math.abs(priceChange24h))

      return this.createSignal(
        marketData,
        indicators,
        'SHORT',
        confidence,
        `Volatility breakout DOWN: ${volatility.toFixed(1)}% range, price at ${(rangePosition * 100).toFixed(0)}% of range`
      )
    }

    return null
  }

  private calculateMomentumConfidence(
    momentumStrength: number,
    rsi: number,
    volume: number
  ): number {
    let confidence = 65

    // Stronger momentum = higher confidence (up to +25)
    confidence += Math.min(momentumStrength * 1.5, 25)

    // RSI in momentum zone = higher confidence (up to +10)
    if (rsi >= 60 && rsi <= 75) {
      confidence += 10
    } else if (rsi >= 55 && rsi <= 80) {
      confidence += 5
    }

    // Higher volume = higher confidence (up to +5)
    if (volume > 10000000) {
      confidence += 5
    } else if (volume > 5000000) {
      confidence += 3
    }

    return Math.min(confidence, 90) // Cap at 90% for aggressive
  }

  private calculateVolatilityConfidence(
    volatility: number,
    rangePosition: number,
    priceChange: number
  ): number {
    let confidence = 60

    // Higher volatility = higher potential (up to +20)
    confidence += Math.min(volatility, 20)

    // Strong position in range = higher confidence (up to +10)
    if (rangePosition > 0.8) {
      confidence += 10
    } else if (rangePosition > 0.75) {
      confidence += 5
    }

    // Strong price change confirms direction (up to +10)
    confidence += Math.min(Math.abs(priceChange), 10)

    return Math.min(confidence, 85)
  }
}

/**
 * Base Trading Strategy
 * Abstract class that all trading strategies extend
 */

import type { AutoTradingStrategy, TradingSignal } from "../types";

export interface MarketData {
  symbol: string;
  price: number;
  volume_24h: number;
  price_change_24h: number;
  high_24h: number;
  low_24h: number;
  timestamp: Date;
}

export interface TechnicalIndicators {
  sma_20?: number; // Simple Moving Average 20 periods
  sma_50?: number; // Simple Moving Average 50 periods
  rsi?: number; // Relative Strength Index
  macd?: { value: number; signal: number; histogram: number };
  bollinger?: { upper: number; middle: number; lower: number };
  atr?: number; // Average True Range (volatility)
}

export abstract class BaseStrategy {
  protected strategy: AutoTradingStrategy;

  constructor(strategy: AutoTradingStrategy) {
    this.strategy = strategy;
  }

  /**
   * Analyze market data and generate trading signal
   * Each strategy implements its own logic
   */
  abstract analyze(
    marketData: MarketData,
    indicators: TechnicalIndicators,
  ): Promise<TradingSignal | null>;

  /**
   * Calculate technical indicators
   * Can be overridden by specific strategies
   */
  async calculateIndicators(
    symbol: string,
    historicalPrices: number[],
  ): Promise<TechnicalIndicators> {
    const indicators: TechnicalIndicators = {};

    if (historicalPrices.length >= 20) {
      indicators.sma_20 = this.calculateSMA(historicalPrices.slice(-20));
    }

    if (historicalPrices.length >= 50) {
      indicators.sma_50 = this.calculateSMA(historicalPrices.slice(-50));
    }

    if (historicalPrices.length >= 14) {
      indicators.rsi = this.calculateRSI(historicalPrices.slice(-14));
    }

    if (historicalPrices.length >= 20) {
      indicators.atr = this.calculateATR(historicalPrices.slice(-14));
      indicators.bollinger = this.calculateBollingerBands(
        historicalPrices.slice(-20),
      );
    }

    return indicators;
  }

  /**
   * Simple Moving Average
   */
  protected calculateSMA(prices: number[]): number {
    const sum = prices.reduce((acc, price) => acc + price, 0);
    return sum / prices.length;
  }

  /**
   * Relative Strength Index (RSI)
   */
  protected calculateRSI(prices: number[]): number {
    if (prices.length < 2) return 50; // Neutral

    const changes = [];
    for (let i = 1; i < prices.length; i++) {
      changes.push(prices[i] - prices[i - 1]);
    }

    const gains = changes.map((c) => (c > 0 ? c : 0));
    const losses = changes.map((c) => (c < 0 ? Math.abs(c) : 0));

    const avgGain = gains.reduce((a, b) => a + b, 0) / gains.length;
    const avgLoss = losses.reduce((a, b) => a + b, 0) / losses.length;

    if (avgLoss === 0) return 100;
    if (avgGain === 0) return 0;

    const rs = avgGain / avgLoss;
    const rsi = 100 - 100 / (1 + rs);

    return rsi;
  }

  /**
   * Average True Range (ATR) - Volatility measure
   */
  protected calculateATR(prices: number[]): number {
    if (prices.length < 2) return 0;

    const ranges = [];
    for (let i = 1; i < prices.length; i++) {
      ranges.push(Math.abs(prices[i] - prices[i - 1]));
    }

    return ranges.reduce((a, b) => a + b, 0) / ranges.length;
  }

  /**
   * Bollinger Bands
   */
  protected calculateBollingerBands(
    prices: number[],
    period: number = 20,
    multiplier: number = 2,
  ): { upper: number; middle: number; lower: number } {
    if (prices.length < period) return { upper: 0, middle: 0, lower: 0 };

    const slice = prices.slice(-period);
    const middle = this.calculateSMA(slice);

    const squareDiffs = slice.map((p) => Math.pow(p - middle, 2));
    const avgSquareDiff =
      squareDiffs.reduce((a, b) => a + b, 0) / squareDiffs.length;
    const stdDev = Math.sqrt(avgSquareDiff);

    return {
      upper: middle + stdDev * multiplier,
      middle: middle,
      lower: middle - stdDev * multiplier,
    };
  }

  /**
   * Calculate volatility percentage
   */
  protected calculateVolatility(marketData: MarketData): number {
    const high = marketData.high_24h;
    const low = marketData.low_24h;
    const current = marketData.price;

    return ((high - low) / current) * 100;
  }

  /**
   * Calculate risk score (0-100)
   * Higher score = higher risk
   */
  protected calculateRiskScore(
    marketData: MarketData,
    indicators: TechnicalIndicators,
  ): number {
    let riskScore = 0;

    // Factor 1: Price volatility (0-40 points)
    const volatility = this.calculateVolatility(marketData);
    riskScore += Math.min(volatility * 2, 40);

    // Factor 2: RSI extremes (0-20 points)
    if (indicators.rsi) {
      if (indicators.rsi > 70 || indicators.rsi < 30) {
        riskScore += 20; // Overbought or oversold
      }
    }

    // Factor 3: Price change (0-20 points)
    const priceChange = Math.abs(marketData.price_change_24h);
    riskScore += Math.min(priceChange * 2, 20);

    // Factor 4: Volume (0-20 points)
    // Low volume = higher risk (simplified)
    if (marketData.volume_24h < 1000000) {
      riskScore += 20;
    }

    return Math.min(riskScore, 100);
  }

  /**
   * Calculate dynamic stop loss based on ATR
   * ATR-multiplikator per risikonivå:
   * - Forsiktig: 1.5x ATR (stram, hyppigere stop-outs)
   * - Balansert: 2.0x ATR (standard)
   * - Offensiv: 2.5x ATR (gir mer rom)
   */
  protected calculateATRStopLoss(
    entryPrice: number,
    atr: number,
    side: "LONG" | "SHORT",
  ): { stopLossPrice: number; dynamicStopPct: number } {
    // ATR multiplikator basert på risikonivå
    const atrMultipliers: Record<string, number> = {
      conservative: 1.5,
      balanced: 2.0,
      aggressive: 2.5,
      custom: 2.0,
    };

    const multiplier = atrMultipliers[this.strategy.risk_level] || 2.0;
    const atrStopDistance = atr * multiplier;
    const dynamicStopPct = (atrStopDistance / entryPrice) * 100;

    // Bruk det STRENGESTE av fast og dynamisk stop-loss
    const finalStopPct = Math.min(this.strategy.stop_loss_pct, dynamicStopPct);

    let stopLossPrice: number;
    if (side === "LONG") {
      stopLossPrice = entryPrice * (1 - finalStopPct / 100);
    } else {
      stopLossPrice = entryPrice * (1 + finalStopPct / 100);
    }

    return { stopLossPrice, dynamicStopPct: finalStopPct };
  }

  /**
   * Get trailing stop configuration based on risk level
   */
  protected getTrailingStopConfig(): {
    enabled: boolean;
    activation_pct: number;
    distance_pct: number;
  } {
    const configs: Record<
      string,
      { enabled: boolean; activation_pct: number; distance_pct: number }
    > = {
      conservative: { enabled: true, activation_pct: 5, distance_pct: 3 },
      balanced: { enabled: true, activation_pct: 8, distance_pct: 5 },
      aggressive: { enabled: true, activation_pct: 12, distance_pct: 8 },
      custom: { enabled: true, activation_pct: 8, distance_pct: 5 },
    };

    return configs[this.strategy.risk_level] || configs["balanced"];
  }

  /**
   * Get partial profit taking levels based on risk level
   */
  protected getPartialTPLevels(): Array<{
    target_pct: number;
    sell_pct: number;
  }> {
    const levels: Record<
      string,
      Array<{ target_pct: number; sell_pct: number }>
    > = {
      conservative: [
        { target_pct: 5, sell_pct: 50 },
        { target_pct: 10, sell_pct: 50 },
      ],
      balanced: [
        { target_pct: 8, sell_pct: 30 },
        { target_pct: 15, sell_pct: 30 },
        { target_pct: 25, sell_pct: 40 }, // Resten med trailing
      ],
      aggressive: [
        { target_pct: 12, sell_pct: 25 },
        { target_pct: 25, sell_pct: 25 },
        { target_pct: 40, sell_pct: 50 }, // Resten med trailing
      ],
      custom: [
        { target_pct: 8, sell_pct: 30 },
        { target_pct: 15, sell_pct: 30 },
      ],
    };

    return levels[this.strategy.risk_level] || levels["balanced"];
  }

  /**
   * Fear & Greed Index — returns neutral (50) until external API is connected.
   */
  protected async getFearAndGreedIndex(): Promise<number> {
    return 50;
  }

  /**
   * Create a trading signal
   */
  protected createSignal(
    marketData: MarketData,
    indicators: TechnicalIndicators,
    side: "LONG" | "SHORT",
    confidence: number,
    reason: string,
  ): TradingSignal {
    const entryPrice = marketData.price;

    // Calculate ATR-based stop loss
    const atr = indicators.atr || this.calculateATR([marketData.price]);
    const { stopLossPrice, dynamicStopPct } = this.calculateATRStopLoss(
      entryPrice,
      atr,
      side,
    );

    // Calculate take profit if defined
    let takeProfitPrice: number | undefined;
    if (this.strategy.take_profit_pct) {
      if (side === "LONG") {
        takeProfitPrice =
          entryPrice * (1 + this.strategy.take_profit_pct / 100);
      } else {
        takeProfitPrice =
          entryPrice * (1 - this.strategy.take_profit_pct / 100);
      }
    }

    const riskScore = this.calculateRiskScore(marketData, indicators);
    const volatility = this.calculateVolatility(marketData);

    // Get trailing stop and partial TP config
    const trailingStop = this.getTrailingStopConfig();
    const partialTpLevels = this.getPartialTPLevels();

    return {
      symbol: marketData.symbol,
      side,
      confidence,
      entry_price: entryPrice,
      stop_loss_price: stopLossPrice,
      take_profit_price: takeProfitPrice,
      position_size_pct: this.strategy.max_position_size_pct,
      leverage: this.strategy.max_leverage,
      risk_score: riskScore,
      market_volatility_pct: volatility,
      reason,
      trailing_stop: trailingStop,
      partial_tp_levels: partialTpLevels,
    };
  }

  /**
   * Get strategy name
   */
  getName(): string {
    return this.strategy.name;
  }

  /**
   * Get risk level
   */
  getRiskLevel(): string {
    return this.strategy.risk_level;
  }
}

/**
 * Grid Trading Strategy
 * Den #1 mest brukte bot-strategien globalt
 * Fungerer i sidelengs markeder der trend-following taper penger
 */

import type { AutoTradingStrategy, TradingSignal } from "../types";
import {
  BaseStrategy,
  type MarketData,
  type TechnicalIndicators,
} from "./base-strategy";

export interface GridConfig {
  gridCount: number; // Antall grid-nivåer
  gridRangePct: number; // Total range i prosent (f.eks. 10% = ±5% fra midt)
  upperPrice?: number; // Manuell øvre grense (valgfri)
  lowerPrice?: number; // Manuell nedre grense (valgfri)
}

export class GridStrategy extends BaseStrategy {
  private gridConfig: GridConfig;
  private activeGrids: Map<
    string,
    {
      level: number;
      buyPrice: number;
      sellPrice: number;
      quantity: number;
      status: "empty" | "buy_placed" | "holding" | "sell_placed";
    }
  > = new Map();

  constructor(strategy: AutoTradingStrategy, gridConfig: GridConfig) {
    super(strategy);
    this.gridConfig = gridConfig;
  }

  /**
   * Analyze market for grid trading opportunities
   * Grid trading fungerer best i:
   * - Sidelengs markeder (litt volatilitet, ingen trend)
   * - Høy likviditet
   * - Lavt spread
   */
  async analyze(
    marketData: MarketData,
    indicators: TechnicalIndicators,
  ): Promise<TradingSignal | null> {
    const { symbol, price: currentPrice } = marketData;

    // Sjekk om markedet er egnet for grid trading
    const marketSuitability = this.assessMarketSuitability(
      marketData,
      indicators,
    );
    if (marketSuitability.score < 60) {
      return null; // Ikke egnet for grid trading
    }

    // Beregn grid-nivåer
    const volatility = this.calculateVolatility(marketData);
    const grids = this.calculateGridLevels(
      currentPrice,
      volatility,
      indicators,
    );

    // Finn hvilket nivå vi er på
    const currentGrid = grids.find(
      (g) => currentPrice >= g.buyPrice && currentPrice <= g.sellPrice,
    );

    if (!currentGrid) return null;

    // Sjekk om vi skal plassere en kjøpsordre på dette nivået
    const gridKey = `${symbol}_grid_${currentGrid.level}`;
    const existingGrid = this.activeGrids.get(gridKey);

    if (!existingGrid || existingGrid.status === "empty") {
      // Plasser kjøpsordre på dette nivået
      this.activeGrids.set(gridKey, {
        ...currentGrid,
        status: "buy_placed",
      });

      return this.createGridSignal(
        marketData,
        indicators,
        currentGrid,
        "Kjøper på grid-nivå " + currentGrid.level,
        marketSuitability.score,
      );
    }

    return null;
  }

  /**
   * Vurder om markedet er egnet for grid trading
   */
  private assessMarketSuitability(
    marketData: MarketData,
    indicators: TechnicalIndicators,
  ): { score: number; reasons: string[] } {
    let score = 0;
    const reasons: string[] = [];

    // 1. Volatilitet (30 poeng)
    // Grid trenger litt volatilitet, men ikke for mye
    const volatility = this.calculateVolatility(marketData);
    if (volatility >= 3 && volatility <= 15) {
      score += 30;
      reasons.push("God volatilitet for grid");
    } else if (volatility < 3) {
      score += 15;
      reasons.push("Lav volatilitet - redusert profittpotensial");
    } else {
      score += 10;
      reasons.push("Høy volatilitet - økt risiko");
    }

    // 2. RSI (25 poeng)
    // Grid fungerer best når RSI er nøytral (40-60)
    if (indicators.rsi && indicators.rsi >= 40 && indicators.rsi <= 60) {
      score += 25;
      reasons.push("Nøytral RSI - egnet for grid");
    } else if (indicators.rsi) {
      score += 10;
      reasons.push("RSI utenfor nøytralt område");
    }

    // 3. Trendstyrke (25 poeng)
    // Grid fungerer dårlig i sterke trender
    const sma20 = indicators.sma_20;
    const sma50 = indicators.sma_50;
    if (sma20 && sma50) {
      const trendStrength = Math.abs((sma20 - sma50) / sma50) * 100;
      if (trendStrength < 2) {
        score += 25;
        reasons.push("Sidelengs trend - perfekt for grid");
      } else if (trendStrength < 5) {
        score += 15;
        reasons.push("Svak trend - akseptabelt");
      } else {
        score += 5;
        reasons.push("Sterk trend - ikke ideelt");
      }
    }

    // 4. Volum (20 poeng)
    if (marketData.volume_24h > 10000000) {
      score += 20;
      reasons.push("God likviditet");
    } else if (marketData.volume_24h > 1000000) {
      score += 10;
      reasons.push("Tilstrekkelig likviditet");
    }

    return { score, reasons };
  }

  /*
   * Beregn grid-nivåer
   */
  private calculateGridLevels(
    currentPrice: number,
    volatility?: number,
    indicators?: TechnicalIndicators,
  ): Array<{
    level: number;
    buyPrice: number;
    sellPrice: number;
    quantity: number;
  }> {
    let { gridCount, gridRangePct, upperPrice, lowerPrice } = this.gridConfig;

    // PRO REFINEMENT: Auto-Range med Bollinger Bands
    if (
      (this.strategy.risk_level === "dynamic" ||
        this.strategy.risk_level === "balanced") &&
      indicators?.bollinger
    ) {
      upperPrice = indicators.bollinger.upper;
      lowerPrice = indicators.bollinger.lower;
    } else if (
      this.strategy.risk_level === "dynamic" ||
      this.strategy.risk_level === "aggressive"
    ) {
      // Fallback til 24t volatilitet
      const vol = volatility || 5;
      gridRangePct = Math.max(vol * 1.5, 5);
    }

    // Bruk manuelle priser hvis angitt, ellers beregn fra current price
    const upper = upperPrice || currentPrice * (1 + gridRangePct / 100 / 2);
    const lower = lowerPrice || currentPrice * (1 - gridRangePct / 100 / 2);

    const gridSize = (upper - lower) / gridCount;
    const grids = [];

    for (let i = 0; i < gridCount; i++) {
      const levelLower = lower + gridSize * i;
      const levelUpper = levelLower + gridSize;

      grids.push({
        level: i,
        buyPrice: levelLower,
        sellPrice: levelUpper,
        quantity: 0, // Beregnes senere basert på kapital
      });
    }

    return grids;
  }

  /**
   * Create grid trading signal
   */
  private createGridSignal(
    marketData: MarketData,
    indicators: TechnicalIndicators,
    grid: {
      level: number;
      buyPrice: number;
      sellPrice: number;
      quantity: number;
    },
    reason: string,
    confidence: number,
  ): TradingSignal {
    const baseSignal = this.createSignal(
      marketData,
      indicators,
      "LONG", // Grid trading er alltid LONG-basert (kjøp lavt, selg høyt)
      confidence,
      reason,
    );

    // Grid trading har ingen tradisjonell stop-loss
    // Isteden har vi "grid reset" hvis prisen går utenfor range
    return {
      ...baseSignal,
      stop_loss_price: grid.buyPrice * 0.95, // Nødstop hvis 5% under grid
      take_profit_price: grid.sellPrice,
      position_size_pct:
        this.strategy.max_position_size_pct / this.gridConfig.gridCount,
      // Grid-spesifikk konfig
      trailing_stop: {
        enabled: false,
        activation_pct: 0,
        distance_pct: 0,
      },
      partial_tp_levels: [], // Grid selger på fast nivå
    };
  }

  /**
   * Get grid configuration for risk level
   */
  static getGridConfig(riskLevel: string): GridConfig {
    const configs: Record<string, GridConfig> = {
      conservative: {
        gridCount: 5,
        gridRangePct: 10, // ±5%
      },
      balanced: {
        gridCount: 10,
        gridRangePct: 20, // ±10%
      },
      aggressive: {
        gridCount: 20,
        gridRangePct: 30, // ±15%
      },
      dynamic: {
        gridCount: 15,
        gridRangePct: 25, // AI justerer dynamisk
      },
    };

    return configs[riskLevel] || configs["balanced"];
  }
}

import crypto from 'crypto';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 16;
const AUTH_TAG_LENGTH = 16;

/**
 * Krypterer tekst med AES-256-GCM
 */
export function encrypt(text: string, secret: string): string {
  const key = crypto.scryptSync(secret, 'salt', 32);
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);

  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag();

  // Kombiner IV + authTag + encrypted data
  return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;
}

/**
 * Dekrypterer tekst med AES-256-GCM
 */
export function decrypt(encryptedText: string, secret: string): string {
  const parts = encryptedText.split(':');
  if (parts.length !== 3) {
    throw new Error('Invalid encrypted text format');
  }

  const iv = Buffer.from(parts[0], 'hex');
  const authTag = Buffer.from(parts[1], 'hex');
  const encrypted = parts[2];

  const key = crypto.scryptSync(secret, 'salt', 32);
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(authTag);

  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return decrypted;
}

/**
 * Kryptering av Binance API-nøkler før lagring i database.
 * Bruker Web Crypto API (edge-compatible).
 */

const ENCRYPTION_KEY_ENV = 'ENCRYPTION_KEY' // 32-byte hex string

/**
 * Generer ny encryption key (kjør én gang, lagre i env)
 */
export async function generateEncryptionKey(): Promise<string> {
  if (typeof crypto === 'undefined') {
    throw new Error('Web Crypto API ikke tilgjengelig')
  }

  const key = await crypto.subtle.generateKey(
    { name: 'AES-GCM', length: 256 },
    true,
    ['encrypt', 'decrypt']
  )

  const exported = await crypto.subtle.exportKey('raw', key)
  return Buffer.from(exported).toString('hex')
}

/**
 * Krypter API key
 */
export async function encryptApiKey(plaintext: string): Promise<string> {
  const encryptionKeyHex = process.env.ENCRYPTION_KEY

  if (!encryptionKeyHex) {
    throw new Error('ENCRYPTION_KEY ikke satt i environment variables')
  }

  const keyData = Buffer.from(encryptionKeyHex, 'hex')
  const key = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'AES-GCM' },
    false,
    ['encrypt']
  )

  const iv = crypto.getRandomValues(new Uint8Array(12))
  const encoded = new TextEncoder().encode(plaintext)

  const ciphertext = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    key,
    encoded
  )

  // Returner: iv + ciphertext som base64
  const combined = new Uint8Array(iv.length + ciphertext.byteLength)
  combined.set(iv, 0)
  combined.set(new Uint8Array(ciphertext), iv.length)

  return Buffer.from(combined).toString('base64')
}

/**
 * Dekrypter API key
 */
export async function decryptApiKey(encrypted: string): Promise<string> {
  const encryptionKeyHex = process.env.ENCRYPTION_KEY

  if (!encryptionKeyHex) {
    throw new Error('ENCRYPTION_KEY ikke satt')
  }

  const keyData = Buffer.from(encryptionKeyHex, 'hex')
  const key = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'AES-GCM' },
    false,
    ['decrypt']
  )

  const combined = Buffer.from(encrypted, 'base64')
  const iv = combined.slice(0, 12)
  const ciphertext = combined.slice(12)

  const decrypted = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv },
    key,
    ciphertext
  )

  return new TextDecoder().decode(decrypted)
}

/**
 * KLA-31: Automated Emails - Unified Email Service
 * 
 * This module provides a centralized email service for all transactional
 * and engagement emails in Klarpakke.
 * 
 * Features:
 * - Branded HTML templates for all email types
 * - Email preference checking before sending
 * - Queue integration for async processing
 * - Comprehensive logging
 */

import { Resend } from 'resend';
import { createClient } from '@/lib/supabase/server';

// Initialize Resend
const resend = new Resend(process.env.RESEND_API_KEY);

const FROM_EMAIL = 'Klarpakke <post@klarpakke.no>';
const REPLY_TO = 'support@klarpakke.no';

// Email types that require user consent
export type EmailType = 
  | 'welcome'
  | 'subscription_welcome'
  | 'payment_failed'
  | 'payment_succeeded'
  | 'subscription_cancelled'
  | 'subscription_expiring'
  | 'level_up'
  | 'achievement_unlocked'
  | 'leaderboard_climb'
  | 'trade_executed'
  | 'daily_digest'
  | 'weekly_digest'
  | 'password_reset'
  | 'email_verification'
  | 'marketing';

// Email preferences mapping
interface EmailPreferences {
  user_id: string;
  marketing_emails: boolean;
  transaction_emails: boolean;
  gamification_emails: boolean;
  trading_alerts: boolean;
  digest_emails: 'daily' | 'weekly' | 'never';
  updated_at: string;
}

/**
 * Check if user has opted in to receive a specific email type
 */
async function shouldSendEmail(userId: string, type: EmailType): Promise<boolean> {
  // Transactional emails are always sent
  const transactionalTypes: EmailType[] = [
    'welcome',
    'password_reset',
    'email_verification',
    'payment_failed',
    'subscription_expiring',
  ];

  if (transactionalTypes.includes(type)) {
    return true;
  }

  try {
    const supabase = await createClient();
    const { data: prefs } = await supabase
      .from('email_preferences')
      .select('*')
      .eq('user_id', userId)
      .single();

    if (!prefs) {
      // Default to sending if no preferences set
      return true;
    }

    switch (type) {
      case 'marketing':
        return prefs.marketing_emails;
      case 'level_up':
      case 'achievement_unlocked':
      case 'leaderboard_climb':
        return prefs.gamification_emails;
      case 'trade_executed':
        return prefs.trading_alerts;
      case 'daily_digest':
        return prefs.digest_emails === 'daily';
      case 'weekly_digest':
        return prefs.digest_emails === 'weekly' || prefs.digest_emails === 'daily';
      default:
        return true;
    }
  } catch (error) {
    console.error('[Email] Error checking preferences:', error);
    // Default to sending on error (fail open for transactional)
    return transactionalTypes.includes(type);
  }
}

/**
 * Get user email and name
 */
async function getUserInfo(userId: string): Promise<{ email: string; name: string } | null> {
  try {
    const supabase = await createClient();
    const { data: profile } = await supabase
      .from('profiles')
      .select('email, full_name')
      .eq('id', userId)
      .single();

    if (!profile?.email) {
      // Fallback: get email from auth
      const { data: { user } } = await supabase.auth.admin.getUserById(userId);
      if (!user?.email) return null;

      return {
        email: user.email,
        name: profile?.full_name || user.email.split('@')[0],
      };
    }

    return {
      email: profile.email,
      name: profile.full_name || profile.email.split('@')[0],
    };
  } catch (error) {
    console.error('[Email] Error getting user info:', error);
    return null;
  }
}

