interface SendEmailOptions {
  userId: string;
  type: EmailType;
  data: Record<string, string | number | boolean>;
  skipPreferences?: boolean;
}

/**
 * Send an email to a user
 */
export async function sendTemplatedEmail(options: SendEmailOptions): Promise<{ success: boolean; error?: string }> {
  const { userId, type, data, skipPreferences = false } = options;

  try {
    // Check preferences (unless skipped)
    if (!skipPreferences) {
      const shouldSend = await shouldSendEmail(userId, type);
      if (!shouldSend) {
        console.log(`[Email] Skipped ${type} for user ${userId} (preferences)`);
        return { success: true };
      }
    }

    // Get user info
    const user = await getUserInfo(userId);
    if (!user) {
      return { success: false, error: 'User not found' };
    }

    // Generate email content
    let email: { subject: string; html: string };

    switch (type) {
      case 'welcome':
        email = templates.welcome(data.name as string || user.name);
        break;
      case 'subscription_welcome':
        email = templates.subscriptionWelcome(data.name as string || user.name, data.tier as string);
        break;
      case 'payment_failed':
        email = templates.paymentFailed(data.name as string || user.name, data.updateUrl as string);
        break;
      case 'payment_succeeded':
        email = templates.paymentSucceeded(data.name as string || user.name, data.amount as string, data.nextBilling as string);
        break;
      case 'subscription_cancelled':
        email = templates.subscriptionCancelled(data.name as string || user.name, data.endDate as string);
        break;
      case 'level_up':
        email = templates.levelUp(
          data.name as string || user.name,
          data.oldLevel as number,
          data.newLevel as number,
          data.totalXp as number
        );
        break;
      case 'achievement_unlocked':
        email = templates.achievementUnlocked(data.name as string || user.name, data.badgeName as string, data.badgeIcon as string);
        break;
      case 'leaderboard_climb':
        email = templates.leaderboardClimb(
          data.name as string || user.name,
          data.climb as number,
          data.newRank as number,
          data.period as string
        );
        break;
      case 'trade_executed':
        email = templates.tradeExecuted(
          data.name as string || user.name,
          data.side as string,
          data.pair as string,
          data.amount as string,
          data.price as string,
          data.pnl as string
        );
        break;
      case 'daily_digest':
        email = templates.dailyDigest(
          data.name as string || user.name,
          data.trades as number,
          data.pnl as string,
          data.winRate as string
        );
        break;
      case 'password_reset':
        email = templates.passwordReset(data.name as string || user.name, data.resetUrl as string);
        break;
      case 'email_verification':
        email = templates.emailVerification(data.name as string || user.name, data.verifyUrl as string);
        break;
      default:
        return { success: false, error: 'Unknown email type' };
    }

    // Send email
    const { data: result, error } = await resend.emails.send({
      from: FROM_EMAIL,
      to: user.email,
      subject: email.subject,
      html: email.html,
      replyTo: REPLY_TO,
    });

    if (error) {
      console.error('[Email] Resend error:', error);
      return { success: false, error: error.message };
    }

    console.log(`[Email] Sent ${type} to ${user.email} (${result?.id})`);
    return { success: true };

  } catch (error) {
    console.error('[Email] Unexpected error:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Queue an email for async processing
 */
export async function queueEmail(options: SendEmailOptions): Promise<{ success: boolean; error?: string }> {
  try {
    const supabase = await createClient();

    const { error } = await supabase
      .from('notification_queue')
      .insert({
        user_id: options.userId,
        type: options.type,
        payload: options.data,
        status: 'pending',
      });

    if (error) {
      console.error('[Email] Queue error:', error);
      return { success: false, error: error.message };
    }

    console.log(`[Email] Queued ${options.type} for user ${options.userId}`);
    return { success: true };

  } catch (error) {
    console.error('[Email] Queue unexpected error:', error);
    return { success: false, error: String(error) };
  }
}

