export class BinanceService {
  private apiKey: string;
  private apiSecret: string;
  private baseUrl: string;

  constructor(credentials: BinanceCredentials) {
    this.apiKey = credentials.apiKey;
    this.apiSecret = credentials.apiSecret;
    this.baseUrl = credentials.isTestnet ? BINANCE_TESTNET_URL : BINANCE_API_URL;
  }

  /**
   * Generate HMAC SHA256 signature for authenticated requests
   */
  private generateSignature(queryString: string): string {
    return crypto
      .createHmac('sha256', this.apiSecret)
      .update(queryString)
      .digest('hex');
  }

  /**
   * Make authenticated request to Binance API
   */
  private async makeRequest<T>(
    endpoint: string,
    method: 'GET' | 'POST' | 'DELETE' = 'GET',
    params: Record<string, string | number | boolean | undefined> = {},
    requiresAuth: boolean = false
  ): Promise<T> {
    const timestamp = Date.now();
    const queryParams: Record<string, string> = {
      timestamp: timestamp.toString(),
    };

    // Add params to query string
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        queryParams[key] = String(value);
      }
    });

    const queryString = new URLSearchParams(queryParams).toString();
    const signature = this.generateSignature(queryString);

    const url = `${this.baseUrl}${endpoint}?${queryString}&signature=${signature}`;

    const headers: Record<string, string> = {
      'X-MBX-APIKEY': this.apiKey,
      'Content-Type': 'application/json',
    };

    const options: RequestInit = {
      method,
      headers,
    };

    const response = await fetch(url, options);

    if (!response.ok) {
      const error = await response.json() as { msg?: string; message?: string };
      throw new Error(`Binance API error: ${error.msg || error.message || 'Unknown error'}`);
    }

    return response.json() as Promise<T>;
  }

  /**
   * Test API key validity
   */
  async validateApiKey(): Promise<{ valid: boolean; error?: string }> {
    try {
      await this.makeRequest<BinanceAccount>('/api/v3/account', 'GET', {}, true);
      return { valid: true };
    } catch (error) {
      return { 
        valid: false, 
        error: error instanceof Error ? error.message : 'Invalid API key' 
      };
    }
  }

  /**
   * Get account information including balances
   */
  async getAccount(): Promise<BinanceAccount> {
    return this.makeRequest<BinanceAccount>('/api/v3/account', 'GET', {}, true);
  }

  /**
   * Get current price for a symbol
   */
  async getPrice(symbol: string): Promise<number> {
    const response = await fetch(`${this.baseUrl}/api/v3/ticker/price?symbol=${symbol}`);
    const data: BinanceTicker = await response.json();
    return parseFloat(data.price);
  }

  /**
   * Place a new order
   */
  async placeOrder(order: BinanceOrder): Promise<BinanceOrderResponse> {
    const params: Record<string, string | number | undefined> = {
      symbol: order.symbol,
      side: order.side,
      type: order.type,
    };

    if (order.quantity) {
      params.quantity = order.quantity.toString();
    }

    if (order.quoteOrderQty) {
      params.quoteOrderQty = order.quoteOrderQty.toString();
    }

    if (order.price) {
      params.price = order.price.toString();
    }

    if (order.stopPrice) {
      params.stopPrice = order.stopPrice.toString();
    }

    if (order.timeInForce) {
      params.timeInForce = order.timeInForce;
    }

    return this.makeRequest<BinanceOrderResponse>('/api/v3/order', 'POST', params, true);
  }

  /**
   * Place a market buy order (simplest for beginners)
   */
  async marketBuy(symbol: string, quoteOrderQty: number): Promise<BinanceOrderResponse> {
    return this.placeOrder({
      symbol,
      side: 'BUY',
      type: 'MARKET',
      quoteOrderQty,
    });
  }

  /**
   * Place a market sell order
   */
  async marketSell(symbol: string, quantity: number): Promise<BinanceOrderResponse> {
    return this.placeOrder({
      symbol,
      side: 'SELL',
      type: 'MARKET',
      quantity,
    });
  }

  /**
   * Get order status
   */
  async getOrderStatus(symbol: string, orderId: number): Promise<BinanceOrderStatus> {
    return this.makeRequest<BinanceOrderStatus>('/api/v3/order', 'GET', { symbol, orderId }, true);
  }

  /**
   * Cancel an order
   */
  async cancelOrder(symbol: string, orderId: number): Promise<BinanceCancelOrderResponse> {
    return this.makeRequest<BinanceCancelOrderResponse>('/api/v3/order', 'DELETE', { symbol, orderId }, true);
  }

  /**
   * Get all open orders
   */
  async getOpenOrders(symbol?: string): Promise<BinanceOrderStatus[]> {
    const params: Record<string, string> = {};
    if (symbol) {
      params.symbol = symbol;
    }
    return this.makeRequest<BinanceOrderStatus[]>('/api/v3/openOrders', 'GET', params, true);
  }

  /**
   * Get recent trades
   */
  async getMyTrades(symbol: string, limit: number = 500): Promise<BinanceTrade[]> {
    return this.makeRequest<BinanceTrade[]>('/api/v3/myTrades', 'GET', { symbol, limit }, true);
  }

  /**
   * Calculate USD value of an asset
   */
  async getAssetValueUSD(asset: string, amount: number): Promise<number> {
    if (asset === 'USDT' || asset === 'BUSD' || asset === 'USD') {
      return amount;
    }

    try {
      // Try USDT pair first
      const price = await this.getPrice(`${asset}USDT`);
      return amount * price;
    } catch {
      try {
        // Try BTC pair and convert
        const btcPrice = await this.getPrice(`${asset}BTC`);
        const btcUsdPrice = await this.getPrice('BTCUSDT');
        return amount * btcPrice * btcUsdPrice;
      } catch {
        return 0;
      }
    }
  }
}

/**
 * Helper to extract trade details from Binance order response
 */
export function extractTradeDetails(orderResponse: BinanceOrderResponse): {
  totalQty: number;
  avgPrice: number;
  totalCommission: number;
  commissionAsset: string;
} {
  if (!orderResponse.fills || orderResponse.fills.length === 0) {
    return {
      totalQty: parseFloat(orderResponse.executedQty),
      avgPrice: parseFloat(orderResponse.price) || 0,
      totalCommission: 0,
      commissionAsset: '',
    };
  }

  let totalQty = 0;
  let totalValue = 0;
  let totalCommission = 0;
  const commissionAsset = orderResponse.fills[0]?.commissionAsset || '';

  for (const fill of orderResponse.fills) {
    const qty = parseFloat(fill.qty);
    const price = parseFloat(fill.price);
    totalQty += qty;
    totalValue += qty * price;
    totalCommission += parseFloat(fill.commission);
  }

  return {
    totalQty,
    avgPrice: totalValue / totalQty,
    totalCommission,
    commissionAsset,
  };
}

"use client";

import { useAuth } from "@/hooks/useAuth";
import { createClient } from "@/lib/supabase/client";
import { Position, useTradingStore } from "@/store/tradingStore";
import { useCallback, useEffect, useMemo, useState } from "react";

interface LiveTradeResult {
  success: boolean;
  error?: string;
  orderId?: string;
}

export interface LiveTradingEngine {
  balance: number;
  positions: Position[];
  price: number;
  unrealizedPnL: number;
  maxDrawdown: number;
  pnlHistory: number[];
  placeOrder: (order: {
    side: "buy" | "sell";
    type: "market" | "limit";
    amount: number;
    price?: number;
  }) => Promise<LiveTradeResult>;
  closePosition: (
    positionId: string,
  ) => Promise<{ success: boolean; error?: string }>;
  isLoading: boolean;
  error: string | null;
  binanceStatus: "connected" | "disconnected" | "checking";
}

const INITIAL_PRICE = 850000; // BTC price in NOK

export function useLiveTradingEngine(symbol: string): LiveTradingEngine {
  const { user } = useAuth();
  const supabase = createClient();

  const {
    positions,
    marketData,
    updateMarketData,
    openPosition,
    closePosition: closeStorePosition,
  } = useTradingStore();

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pnlHistory] = useState<number[]>([]);
  const [maxDrawdown] = useState(0);
  const [binanceStatus, setBinanceStatus] = useState<
    "connected" | "disconnected" | "checking"
  >("checking");
  const [liveBalance, setLiveBalance] = useState(0);

  // Get current price
  const price = marketData[symbol]?.price || INITIAL_PRICE;

  // Check Binance connection
  useEffect(() => {
    const checkConnection = async () => {
      if (!user) {
        setBinanceStatus("disconnected");
        return;
      }

      try {
        const { data: profile, error: profileError } = await supabase
          .from("user_profiles")
          .select("tier")
          .eq("user_id", user.id)
          .maybeSingle();

        const liveTiers = ["master", "phd", "professor"];
        if (profileError || !liveTiers.includes(profile?.tier || "")) {
          setBinanceStatus("disconnected");
          return;
        }

        // Verify API key works by fetching account info
        const response = await fetch("/api/binance/account", {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
          },
        });

        if (response.ok) {
          const data = await response.json();
          setLiveBalance(data.balance || 0);
          setBinanceStatus("connected");
        } else {
          setBinanceStatus("disconnected");
        }
      } catch (err) {
        console.error("Error checking Binance connection:", err);
        setBinanceStatus("disconnected");
      }
    };

    checkConnection();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  // Update price from Binance WebSocket or API
  useEffect(() => {
    const fetchPrice = async () => {
      try {
        const response = await fetch(
          `https://api.binance.com/api/v3/ticker/price?symbol=${symbol.toUpperCase()}`,
        );
        if (response.ok) {
          const data = await response.json();
          const newPrice = parseFloat(data.price);

          // Convert to NOK (simplified - would use actual exchange rate)
          const nokPrice = newPrice * 8.5; // Approximate USD to NOK

          updateMarketData(symbol, {
            price: nokPrice,
            lastUpdate: new Date().toISOString(),
          });

          // Update position PnLs
          positions.forEach((pos) => {
            useTradingStore.getState().updatePosition(pos.id, nokPrice);
          });
        }
      } catch (err) {
        console.error("Error fetching price:", err);
      }
    };

    fetchPrice();
    const interval = setInterval(fetchPrice, 5000); // Poll every 5 seconds

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [symbol]);

  // Calculate unrealized PnL
  const unrealizedPnL = useMemo(() => {
    return positions.reduce((sum, pos) => sum + pos.pnl, 0);
  }, [positions]);

  // Place order via Binance API
  const placeOrder = useCallback(
    async (order: {
      side: "buy" | "sell";
      type: "market" | "limit";
      amount: number;
      price?: number;
    }): Promise<LiveTradeResult> => {
      setIsLoading(true);
      setError(null);

      try {
        if (!user) {
          throw new Error("Not authenticated");
        }

        if (binanceStatus !== "connected") {
          throw new Error("Binance not connected");
        }

        // Optimistic: show position in UI immediately
        const optimisticResult = order.side === "buy" ? openPosition({
          symbol,
          side: "long",
          entryPrice: price,
          quantity: order.amount,
          leverage: 1,
        }) : undefined;
        const tempPositionId = optimisticResult?.position?.id;

        // Execute on Binance
        const response = await fetch("/api/binance/order", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            symbol: symbol.toUpperCase(),
            side: order.side.toUpperCase(),
            type: order.type.toUpperCase(),
            quantity: order.amount,
            price: order.price,
          }),
        });

        if (!response.ok) {
          // Rollback optimistic position
          if (tempPositionId) closeStorePosition(tempPositionId);
          const errorData = await response.json();
          throw new Error(errorData.message || "Order failed");
        }

        const result = await response.json();

        // Record in database (non-blocking)
        supabase.from("trades").insert({
          user_id: user.id,
          mode: "live",
          trading_pair: symbol.replace("USDT", "/USDT"),
          binance_order_id: result.orderId,
          side: order.side,
          order_type: order.type,
          quantity: order.amount,
          price: result.price || price,
          total_value: order.amount * (result.price || price),
          fee: 0,
          status: "filled",
          idempotency_key: `live-${Date.now()}-${result.orderId}`,
          executed_at: new Date().toISOString(),
        }).then(({ error: dbErr }) => {
          if (dbErr) console.error("Trade DB insert failed:", dbErr);
        });

        return {
          success: true,
          orderId: result.orderId,
        };
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : "Trade failed";
        setError(errorMsg);
        return { success: false, error: errorMsg };
      } finally {
        setIsLoading(false);
      }
    },
    [user, symbol, price, binanceStatus, supabase, openPosition],
  );

  // Close position via Binance API
  const closePositionHandler = useCallback(
    async (
      positionId: string,
    ): Promise<{ success: boolean; error?: string }> => {
      setIsLoading(true);
      setError(null);

      try {
        const position = positions.find((p) => p.id === positionId);
        if (!position) {
          throw new Error("Position not found");
        }

        // Execute sell order on Binance
        const response = await fetch("/api/binance/order", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            symbol: symbol.toUpperCase(),
            side: "SELL",
            type: "MARKET",
            quantity: position.quantity,
          }),
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || "Close order failed");
        }

        const result = await response.json();

        // Update database
        if (user) {
          await supabase
            .from("trades")
            .update({
              status: "closed",
              exit_price: result.price || price,
              realized_pnl: position.pnl,
              closed_at: new Date().toISOString(),
            })
            .eq("id", positionId);
        }

        // Update local store
        closeStorePosition(positionId);

        return { success: true };
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : "Close failed";
        setError(errorMsg);
        return { success: false, error: errorMsg };
      } finally {
        setIsLoading(false);
      }
    },
    [positions, symbol, price, user, supabase, closeStorePosition],
  );

  return {
    balance: liveBalance,
    positions,
    price,
    unrealizedPnL,
    maxDrawdown,
    pnlHistory,
    placeOrder,
    closePosition: closePositionHandler,
    isLoading,
    error,
    binanceStatus,
  };
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { useTradingStore, Position } from '@/store/tradingStore';
import { calculateSlippage, SlippageResult } from '@/lib/paper-trading/slippage';
import { fetchMarketVolatility } from '@/lib/paper-trading/slippage';

interface PaperTradeResult {
  success: boolean;
  error?: string;
  slippage?: {
    bps: number;
    amount: number;
  };
}

export interface PaperTradingEngine {
  balance: number;
  positions: Position[];
  price: number;
  unrealizedPnL: number;
  maxDrawdown: number;
  pnlHistory: number[];
  placeOrder: (order: {
    side: 'buy' | 'sell';
    type: 'market' | 'limit';
    amount: number;
    price?: number;
  }) => Promise<PaperTradeResult>;
  closePosition: (positionId: string) => Promise<{ success: boolean; error?: string }>;
  isLoading: boolean;
  error: string | null;
}

const PAPER_BALANCE = 1_000_000; // 1M NOK paper balance
const INITIAL_PRICE = 850000; // BTC price in NOK

export function usePaperTradingEngine(symbol: string): PaperTradingEngine {
  const { user } = useAuth();
  const supabase = createClient();

  const { 
    portfolio, 
    positions, 
    marketData, 
    updateMarketData, 
    openPosition, 
    closePosition: closeStorePosition,
    trades 
  } = useTradingStore();

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pnlHistory, setPnlHistory] = useState<number[]>([]);
  const [maxDrawdown, setMaxDrawdown] = useState(0);

  // Get current price
  const price = marketData[symbol]?.price || INITIAL_PRICE;

  // Calculate unrealized PnL
  const unrealizedPnL = useMemo(() => {
    return positions.reduce((sum, pos) => sum + pos.pnl, 0);
  }, [positions]);

  // Update price simulation
  useEffect(() => {
    const interval = setInterval(() => {
      // Simulate small price movements
      const volatility = 0.002; // 0.2% volatility
      const change = (Math.random() - 0.5) * 2 * volatility;
      const newPrice = price * (1 + change);

      updateMarketData(symbol, {
        price: newPrice,
        lastUpdate: new Date().toISOString(),
      });

      // Update position PnLs
      positions.forEach((pos) => {
        useTradingStore.getState().updatePosition(pos.id, newPrice);
      });

      // Update PnL history for stress calculation
      setPnlHistory((prev) => {
        const newHistory = [...prev, unrealizedPnL].slice(-50);
        return newHistory;
      });

      // Update max drawdown
      const peak = Math.max(...pnlHistory, 0);
      const currentDD = peak > 0 ? ((peak - unrealizedPnL) / peak) * 100 : 0;
      setMaxDrawdown((prev) => Math.max(prev, currentDD));
    }, 2000);

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [symbol, price, positions.length, unrealizedPnL, pnlHistory.length]);

  // Fetch volatility on mount
  useEffect(() => {
    fetchMarketVolatility(symbol);
  }, [symbol]);

  // Place order with slippage simulation
  const placeOrder = useCallback(
    async (order: {
      side: 'buy' | 'sell';
      type: 'market' | 'limit';
      amount: number;
      price?: number;
    }): Promise<PaperTradeResult> => {
      setIsLoading(true);
      setError(null);

      try {
        if (!user) {
          throw new Error('Not authenticated');
        }

        // Calculate slippage for market orders
        let executionPrice = price;
        let slippageResult: SlippageResult | null = null;

        if (order.type === 'market') {
          slippageResult = calculateSlippage({
            symbol,
            side: order.side,
            orderType: order.type,
            amount: order.amount,
            currentPrice: price,
          });
          executionPrice = slippageResult.executionPrice;
        } else if (order.type === 'limit' && order.price) {
          executionPrice = order.price;
        }

        // Optimistic update: show position in UI immediately
        if (order.side === 'buy') {
          openPosition({
            symbol,
            side: 'long',
            entryPrice: executionPrice,
            quantity: order.amount,
            leverage: 1,
          });
        }

        // Persist to database in background
        const { error: tradeError } = await supabase.rpc(
          'place_paper_trade_with_slippage',
          {
            p_user_id: user.id,
            p_symbol: symbol,
            p_side: order.side,
            p_order_type: order.type,
            p_amount: order.amount,
            p_requested_price: price,
          }
        );

        if (tradeError) {
          console.warn('RPC failed, position kept in local store:', tradeError);
        }

        return {
          success: true,
          slippage: slippageResult
            ? {
                bps: slippageResult.slippageBps,
                amount: slippageResult.slippageAmount,
              }
            : undefined,
        };
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : 'Trade failed';
        setError(errorMsg);
        return { success: false, error: errorMsg };
      } finally {
        setIsLoading(false);
      }
    },
    [user, symbol, price, supabase, openPosition]
  );

  // Close position
  const closePositionHandler = useCallback(
    async (positionId: string): Promise<{ success: boolean; error?: string }> => {
      setIsLoading(true);
      setError(null);

      try {
        const position = positions.find((p) => p.id === positionId);
        if (!position) {
          throw new Error('Position not found');
        }

        // Close in store
        closeStorePosition(positionId);

        // Update database
        if (user) {
          await supabase.rpc('close_paper_trade', {
            p_trade_id: positionId,
            p_exit_price: price,
            p_pnl: position.pnl,
          });
        }

        return { success: true };
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : 'Close failed';
        setError(errorMsg);
        return { success: false, error: errorMsg };
      } finally {
        setIsLoading(false);
      }
    },
    [positions, price, user, supabase, closeStorePosition]
  );

  return {
    balance: portfolio.balance,
    positions,
    price,
    unrealizedPnL,
    maxDrawdown,
    pnlHistory,
    placeOrder,
    closePosition: closePositionHandler,
    isLoading,
    error,
  };
}

"use client";

import { createClient } from "@/lib/supabase/client";
import { useCallback, useEffect, useState } from "react";

export interface CoinPrice {
  symbol: string;
  name: string;
  price: number;
  change24h: number;
  lastUpdated: Date;
}

const COIN_NAMES: Record<string, string> = {
  BTCUSDT: "Bitcoin",
  ETHUSDT: "Ethereum",
  SOLUSDT: "Solana",
  BNBUSDT: "BNB",
  ADAUSDT: "Cardano",
  XRPUSDT: "XRP",
};

const supabase = createClient();

/**
 * Hook for å hente sanntidspriser fra Binance via Supabase Edge Function
 */
export function useRealtimePrices(
  symbols: string[] = ["BTCUSDT", "ETHUSDT", "SOLUSDT", "BNBUSDT"],
) {
  const [coins, setCoins] = useState<CoinPrice[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Stabilize symbols dependency
  const symbolsKey = symbols.join(",");

  const fetchPrices = useCallback(async () => {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        setError("Ikke autentisert");
        setLoading(false);
        return;
      }

      // Kall Edge Function direkte via Supabase-klienten (raskere og sikrere)
      const { data, error: invokeError } = await supabase.functions.invoke(
        `get-binance-prices?symbols=${symbolsKey}`,
        {
          method: "GET",
        },
      );

      if (invokeError) {
        throw invokeError;
      }

      const prices = data?.prices || [];

      const formattedCoins: CoinPrice[] = symbolsKey
        .split(",")
        .map((symbol) => {
          const priceData = prices.find(
            (p: any) => p.symbol === symbol.toUpperCase(),
          ) || { price: 0, change24h: 0 };
          return {
            symbol,
            name: COIN_NAMES[symbol] || symbol,
            price: priceData.price || 0,
            change24h: priceData.change24h || 0,
            lastUpdated: new Date(),
          };
        });

      setCoins(formattedCoins);
      setError(null);
    } catch (err) {
      console.error("Error fetching prices:", err);
      // Fallback til Binance API
      try {
        const binanceData = await fetchBinancePrices(symbolsKey.split(","));
        setCoins(binanceData);
        setError(null);
      } catch {
        setError("Kunne ikke hente priser");
      }
    } finally {
      setLoading(false);
    }
  }, [symbolsKey]);

  // Hent priser ved mount og hvert 10. sekund
  useEffect(() => {
    fetchPrices();
    const interval = setInterval(fetchPrices, 10000);
    return () => clearInterval(interval);
  }, [fetchPrices]);

  return { coins, loading, error, refresh: fetchPrices };
}

/**
 * Fallback: Hent priser direkte fra Binance public API
 */
async function fetchBinancePrices(symbols: string[]): Promise<CoinPrice[]> {
  const responses = await Promise.all(
    symbols.map(async (symbol) => {
      try {
        const res = await fetch(
          `https://api.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
        );
        if (!res.ok) return null;
        const data = await res.json();
        return {
          symbol,
          name: COIN_NAMES[symbol] || symbol,
          price: parseFloat(data.lastPrice) * 11.5, // Konverter til NOK (ca. kurs)
          change24h: parseFloat(data.priceChangePercent),
          lastUpdated: new Date(),
        };
      } catch {
        return null;
      }
    }),
  );

  return responses.filter((c): c is CoinPrice => c !== null);
}

"use client";

import { createClient } from "@/lib/supabase/client";
import {
  BinanceConnection,
  TradingMode,
  TradingModeState,
} from "@/types/trading";
import { useCallback, useEffect, useState } from "react";

export function useTradingMode() {
  const [state, setState] = useState<TradingModeState>({
    mode: "paper",
    canSwitchToLive: false,
    paperBalance: 1000000,
    liveBalance: null,
    isLoading: true,
    error: null,
  });

  const [binanceConnection, setBinanceConnection] = useState<BinanceConnection>(
    {
      isConnected: false,
      apiKeyLast4: null,
      connectedAt: null,
      balance: null,
    },
  );

  const supabase = createClient();

  // Fetch initial trading mode and Binance connection status
  useEffect(() => {
    const fetchTradingMode = async () => {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) {
          setState((prev) => ({ ...prev, isLoading: false }));
          return;
        }

        const { data: profile } = await supabase
          .from("user_profiles")
          .select("tier")
          .eq("user_id", user.id)
          .maybeSingle();

        const liveTiers = ["master", "phd", "professor"];
        const canSwitchToLive = liveTiers.includes(profile?.tier || "");

        setState((prev) => ({
          ...prev,
          mode: "paper",
          canSwitchToLive,
          isLoading: false,
        }));

        setBinanceConnection({
          isConnected: canSwitchToLive,
          apiKeyLast4: canSwitchToLive ? "****" : null,
          connectedAt: null,
          balance: null, // Would fetch from Binance API
        });
      } catch (err) {
        setState((prev) => ({
          ...prev,
          error:
            err instanceof Error ? err.message : "Failed to load trading mode",
          isLoading: false,
        }));
      }
    };

    fetchTradingMode();
  }, [supabase]);

  // Switch trading mode
  const switchMode = useCallback(
    async (newMode: TradingMode): Promise<boolean> => {
      try {
        if (newMode === "live" && !state.canSwitchToLive) {
          setState((prev) => ({
            ...prev,
            error: "Binance API not connected. Please connect your Binance account first.",
          }));
          return false;
        }

        // Optimistic update: switch mode in UI immediately
        const previousMode = state.mode;
        setState((prev) => ({ ...prev, mode: newMode, isLoading: false, error: null }));

        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Not authenticated");

        // Persist to database
        const { error } = await supabase.rpc("set_trading_mode", {
          user_uuid: user.id,
          new_mode: newMode,
        });

        if (error) throw error;

        return true;
      } catch (err) {
        // Rollback to previous mode
        setState((prev) => ({
          ...prev,
          mode: state.mode,
          error:
            err instanceof Error
              ? err.message
              : "Failed to switch trading mode",
          isLoading: false,
        }));
        return false;
      }
    },
    [supabase, state.canSwitchToLive],
  );

  // Connect Binance API
  const connectBinance = useCallback(
    async (apiKey: string, apiSecret: string): Promise<boolean> => {
      try {
        setState((prev) => ({ ...prev, isLoading: true, error: null }));

        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) throw new Error("Not authenticated");

        // Verify API key against Binance
        const isValid = await verifyBinanceApiKey(apiKey, apiSecret);
        if (!isValid) {
          throw new Error("Invalid Binance API key or secret");
        }

        // Encrypt and store API credentials via secure API route
        const encryptResponse = await fetch("/api/binance/encrypt", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ apiKey, apiSecret }),
        });

        if (!encryptResponse.ok) {
          throw new Error("Failed to encrypt API credentials");
        }

        const { encryptedKey, encryptedSecret } = await encryptResponse.json();

        const { error } = await supabase
          .from("profiles")
          .update({
            binance_connected: true,
            binance_api_key_id: encryptedKey,
            binance_api_secret_id: encryptedSecret,
          })
          .eq("id", user.id);

        if (error) throw error;

        setState((prev) => ({
          ...prev,
          canSwitchToLive: true,
          isLoading: false,
        }));

        setBinanceConnection({
          isConnected: true,
          apiKeyLast4: "****" + apiKey.slice(-4),
          connectedAt: new Date().toISOString(),
          balance: null,
        });

        return true;
      } catch (err) {
        setState((prev) => ({
          ...prev,
          error:
            err instanceof Error ? err.message : "Failed to connect Binance",
          isLoading: false,
        }));
        return false;
      }
    },
    [supabase],
  );

  // Disconnect Binance
  const disconnectBinance = useCallback(async (): Promise<boolean> => {
    try {
      setState((prev) => ({ ...prev, isLoading: true, error: null }));

      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("profiles")
        .update({
          binance_connected: false,
          binance_api_key_id: null,
          binance_api_secret_id: null,
          trading_mode: "paper",
        })
        .eq("id", user.id);

      if (error) throw error;

      setState((prev) => ({
        ...prev,
        mode: "paper",
        canSwitchToLive: false,
        isLoading: false,
      }));

      setBinanceConnection({
        isConnected: false,
        apiKeyLast4: null,
        connectedAt: null,
        balance: null,
      });

      return true;
    } catch (err) {
      setState((prev) => ({
        ...prev,
        error:
          err instanceof Error ? err.message : "Failed to disconnect Binance",
        isLoading: false,
      }));
      return false;
    }
  }, [supabase]);

  return {
    ...state,
    binanceConnection,
    switchMode,
    connectBinance,
    disconnectBinance,
  };
}

// Verify Binance API key
async function verifyBinanceApiKey(
  apiKey: string,
  apiSecret: string,
): Promise<boolean> {
  try {
    const timestamp = Date.now();
    const queryString = `timestamp=${timestamp}`;

    // Create signature (would use crypto library in production)
    const encoder = new TextEncoder();
    const cryptoKey = await crypto.subtle.importKey(
      "raw",
      encoder.encode(apiSecret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );
    const signature = await crypto.subtle.sign(
      "HMAC",
      cryptoKey,
      encoder.encode(queryString),
    );
    const signatureHex = Array.from(new Uint8Array(signature))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("");

    const response = await fetch(
      `https://api.binance.com/api/v3/account?${queryString}&signature=${signatureHex}`,
      {
        headers: { "X-MBX-APIKEY": apiKey },
      },
    );

    if (!response.ok) return false;

    const data = await response.json();

    // Check that API key does NOT have withdraw permissions
    if (data.permissions?.includes("WITHDRAW")) {
      throw new Error(
        "API key must NOT have withdraw permission for security reasons",
      );
    }

    return true;
  } catch (error) {
    console.error("Binance API verification failed:", error);
    return false;
  }
}

