// Technical indicator calculations
export function calculateSMA(data: number[], period: number): number[] {
  const sma: number[] = [];
  for (let i = 0; i < data.length; i++) {
    if (i < period - 1) {
      sma.push(NaN);
    } else {
      const sum = data.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0);
      sma.push(sum / period);
    }
  }
  return sma;
}

export function calculateEMA(data: number[], period: number): number[] {
  const ema: number[] = [];
  const multiplier = 2 / (period + 1);

  for (let i = 0; i < data.length; i++) {
    if (i === 0) {
      ema.push(data[i]);
    } else {
      ema.push((data[i] - ema[i - 1]) * multiplier + ema[i - 1]);
    }
  }
  return ema;
}

export function calculateRSI(data: number[], period: number = 14): number[] {
  const rsi: number[] = [];
  let gains = 0;
  let losses = 0;

  // Calculate initial average gain/loss
  for (let i = 1; i <= period; i++) {
    const change = data[i] - data[i - 1];
    if (change > 0) gains += change;
    else losses -= change;
  }

  let avgGain = gains / period;
  let avgLoss = losses / period;

  for (let i = 0; i < data.length; i++) {
    if (i < period) {
      rsi.push(NaN);
      continue;
    }

    if (i > period) {
      const change = data[i] - data[i - 1];
      avgGain = (avgGain * (period - 1) + (change > 0 ? change : 0)) / period;
      avgLoss = (avgLoss * (period - 1) + (change < 0 ? -change : 0)) / period;
    }

    const rs = avgGain / avgLoss;
    rsi.push(100 - (100 / (1 + rs)));
  }

  return rsi;
}

export function calculateMACD(
  data: number[],
  fastPeriod: number = 12,
  slowPeriod: number = 26,
  signalPeriod: number = 9
): { macd: number[]; signal: number[]; histogram: number[] } {
  const fastEMA = calculateEMA(data, fastPeriod);
  const slowEMA = calculateEMA(data, slowPeriod);

  const macd: number[] = fastEMA.map((fast, i) => fast - slowEMA[i]);
  const signal = calculateEMA(macd.filter(v => !isNaN(v)), signalPeriod);

  // Pad signal array to match MACD length
  const paddedSignal = Array(macd.length - signal.length).fill(NaN).concat(signal);

  const histogram = macd.map((m, i) => m - paddedSignal[i]);

  return { macd, signal: paddedSignal, histogram };
}

export function calculateBollingerBands(
  data: number[],
  period: number = 20,
  stdDev: number = 2
): { middle: number[]; upper: number[]; lower: number[] } {
  const middle = calculateSMA(data, period);
  const upper: number[] = [];
  const lower: number[] = [];

  for (let i = 0; i < data.length; i++) {
    if (i < period - 1) {
      upper.push(NaN);
      lower.push(NaN);
    } else {
      const slice = data.slice(i - period + 1, i + 1);
      const mean = slice.reduce((a, b) => a + b, 0) / period;
      const variance = slice.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / period;
      const standardDev = Math.sqrt(variance);

      upper.push(middle[i] + standardDev * stdDev);
      lower.push(middle[i] - standardDev * stdDev);
    }
  }

  return { middle, upper, lower };
}

/**
 * Generate trading signal based on strategy
 */
export function generateSignal(
  strategyId: StrategyType,
  data: MarketData[],
  currentIndex: number,
  params: Record<string, number | string>
): StrategySignal {
  const prices = data.map(d => d.close);
  const current = data[currentIndex];
  const previous = data[currentIndex - 1];

  switch (strategyId) {
    case 'ma_crossover': {
      const shortPeriod = Number(params.shortPeriod || 10);
      const longPeriod = Number(params.longPeriod || 30);

      if (currentIndex < longPeriod) {
        return { action: 'HOLD', confidence: 0, reason: 'Ikke nok data' };
      }

      const shortMA = calculateSMA(prices, shortPeriod);
      const longMA = calculateSMA(prices, longPeriod);

      const shortCurrent = shortMA[currentIndex];
      const shortPrev = shortMA[currentIndex - 1];
      const longCurrent = longMA[currentIndex];
      const longPrev = longMA[currentIndex - 1];

      if (shortPrev <= longPrev && shortCurrent > longCurrent) {
        return { 
          action: 'BUY', 
          confidence: 0.75, 
          reason: `Golden cross: ${shortPeriod}-dag MA krysset over ${longPeriod}-dag MA`,
          metadata: { shortMA: shortCurrent, longMA: longCurrent }
        };
      }

      if (shortPrev >= longPrev && shortCurrent < longCurrent) {
        return { 
          action: 'SELL', 
          confidence: 0.75, 
          reason: `Death cross: ${shortPeriod}-dag MA krysset under ${longPeriod}-dag MA`,
          metadata: { shortMA: shortCurrent, longMA: longCurrent }
        };
      }

      return { action: 'HOLD', confidence: 0.3, reason: 'Ingen MA crossover signal' };
    }

    case 'rsi': {
      const period = Number(params.period || 14);
      const oversold = Number(params.oversold || 30);
      const overbought = Number(params.overbought || 70);

      if (currentIndex < period) {
        return { action: 'HOLD', confidence: 0, reason: 'Ikke nok data' };
      }

      const rsi = calculateRSI(prices, period);
      const currentRSI = rsi[currentIndex];
      const prevRSI = rsi[currentIndex - 1];

      if (prevRSI <= oversold && currentRSI > oversold) {
        return { 
          action: 'BUY', 
          confidence: 0.8, 
          reason: `RSI forlot oversolgt nivå (${currentRSI.toFixed(1)})`,
          metadata: { rsi: currentRSI }
        };
      }

      if (prevRSI >= overbought && currentRSI < overbought) {
        return { 
          action: 'SELL', 
          confidence: 0.8, 
          reason: `RSI forlot overkjøpt nivå (${currentRSI.toFixed(1)})`,
          metadata: { rsi: currentRSI }
        };
      }

      return { action: 'HOLD', confidence: 0.3, reason: `RSI = ${currentRSI.toFixed(1)} (nøytral)` };
    }

    case 'macd': {
      const fast = Number(params.fastPeriod || 12);
      const slow = Number(params.slowPeriod || 26);
      const signal = Number(params.signalPeriod || 9);

      if (currentIndex < slow) {
        return { action: 'HOLD', confidence: 0, reason: 'Ikke nok data' };
      }

      const macd = calculateMACD(prices, fast, slow, signal);
      const histogram = macd.histogram[currentIndex];
      const prevHistogram = macd.histogram[currentIndex - 1];

      if (prevHistogram <= 0 && histogram > 0) {
        return { 
          action: 'BUY', 
          confidence: 0.75, 
          reason: 'MACD histogram vendte positivt',
          metadata: { macd: macd.macd[currentIndex], signal: macd.signal[currentIndex] }
        };
      }

      if (prevHistogram >= 0 && histogram < 0) {
        return { 
          action: 'SELL', 
          confidence: 0.75, 
          reason: 'MACD histogram vendte negativt',
          metadata: { macd: macd.macd[currentIndex], signal: macd.signal[currentIndex] }
        };
      }

      return { action: 'HOLD', confidence: 0.3, reason: 'Ingen MACD signal' };
    }

    case 'bollinger': {
      const bbPeriod = Number(params.period || 20);
      const bbStdDev = Number(params.stdDev || 2);

      if (currentIndex < bbPeriod) {
        return { action: 'HOLD', confidence: 0, reason: 'Ikke nok data' };
      }

      const bb = calculateBollingerBands(prices, bbPeriod, bbStdDev);
      const price = current.close;

      if (price <= bb.lower[currentIndex]) {
        return { 
          action: 'BUY', 
          confidence: 0.7, 
          reason: 'Pris treffer nedre Bollinger Band (oversolgt)',
          metadata: { lower: bb.lower[currentIndex], middle: bb.middle[currentIndex], upper: bb.upper[currentIndex] }
        };
      }

      if (price >= bb.upper[currentIndex]) {
        return { 
          action: 'SELL', 
          confidence: 0.7, 
          reason: 'Pris treffer øvre Bollinger Band (overkjøpt)',
          metadata: { lower: bb.lower[currentIndex], middle: bb.middle[currentIndex], upper: bb.upper[currentIndex] }
        };
      }

      return { action: 'HOLD', confidence: 0.3, reason: 'Pris innenfor Bollinger Bands' };
    }

    case 'breakout': {
      const lookback = Number(params.lookbackPeriod || 20);
      const threshold = Number(params.breakoutThreshold || 2) / 100;

      if (currentIndex < lookback) {
        return { action: 'HOLD', confidence: 0, reason: 'Ikke nok data' };
      }

      const lookbackData = data.slice(currentIndex - lookback, currentIndex);
      const high = Math.max(...lookbackData.map(d => d.high));
      const low = Math.min(...lookbackData.map(d => d.low));
      const price = current.close;

      if (price > high * (1 + threshold)) {
        return { 
          action: 'BUY', 
          confidence: 0.8, 
          reason: `Breakout over ${lookback}-dagers høyde`,
          metadata: { resistance: high, support: low }
        };
      }

      if (price < low * (1 - threshold)) {
        return { 
          action: 'SELL', 
          confidence: 0.8, 
          reason: `Breakdown under ${lookback}-dagers lav`,
          metadata: { resistance: high, support: low }
        };
      }

      return { action: 'HOLD', confidence: 0.3, reason: 'Ingen breakout signal' };
    }

    case 'ai_ml': {
      // Mock AI prediction - in production, this would call an ML model
      const confidence = Number(params.confidenceThreshold || 0.7);

      // Simulate AI prediction using price momentum + volume
      const priceChange = (current.close - data[currentIndex - 5].close) / data[currentIndex - 5].close;
      const volumeSpike = current.volume > (data[currentIndex - 5].volume * 1.5);

      const aiConfidence = 0.5 + Math.abs(priceChange) * 5 + (volumeSpike ? 0.2 : 0);

      if (aiConfidence > confidence && priceChange > 0) {
        return { 
          action: 'BUY', 
          confidence: aiConfidence, 
          reason: 'AI-modell predikerer oppgang basert på mønster-gjenkjenning',
          metadata: { aiConfidence, priceChange, volumeSpike: volumeSpike ? 1 : 0 }
        };
      }

      if (aiConfidence > confidence && priceChange < 0) {
        return { 
          action: 'SELL', 
          confidence: aiConfidence, 
          reason: 'AI-modell predikerer nedgang basert på mønster-gjenkjenning',
          metadata: { aiConfidence, priceChange, volumeSpike: volumeSpike ? 1 : 0 }
        };
      }

      return { action: 'HOLD', confidence: aiConfidence, reason: 'AI usikker - holder posisjon' };
    }

    default:
      return { action: 'HOLD', confidence: 0, reason: 'Ukjent strategi' };
  }
}

/**
 * Portfolio Library - Server-side portfolio queries
 * 
 * Denne modulen håndterer alle porteføljerelaterte database-spørringer.
 * Støtter både paper trading og Binance (real trading) data.
 */

import { createClient } from '@/lib/supabase/server';
import type { Database } from '@/lib/database.types';

// =============================================================================
// Types
// =============================================================================

export interface PortfolioOverview {
  totalValue: number;
  totalProfitAbs: number;
  totalProfitPct: number;
  dayChangeAbs: number;
  dayChangePct: number;
  totalInvested: number;
  positionCount: number;
  hasRealAccount: boolean;
  lastSynced: string | null;
}

export interface PortfolioPosition {
  id: string;
  symbol: string;
  quantity: number;
  avgBuyPrice: number;
  currentPrice: number;
  currentValue: number;
  unrealizedPnl: number;
  unrealizedPnlPercent: number;
  totalInvested: number;
  lastUpdated: string;
  isReal: boolean; // true = Binance, false = Paper trading
}

export interface PortfolioSummary {
  overview: PortfolioOverview;
  positions: PortfolioPosition[];
  hasData: boolean;
  dataSource: 'binance' | 'paper' | 'none';
}

export interface PortfolioError {
  message: string;
  code: string;
}

// =============================================================================
// Type Guards
// =============================================================================

function isValidNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value) && isFinite(value);
}

function safeNumber(value: unknown, defaultValue = 0): number {
  return isValidNumber(value) ? value : defaultValue;
}

// =============================================================================
// Helper Functions
// =============================================================================

function calculatePercentChange(current: number, previous: number): number {
  if (previous === 0) return 0;
  return ((current - previous) / previous) * 100;
}

// =============================================================================
// Database Queries
// =============================================================================

/**
 * Hent porteføljeoversikt for innlogget bruker
 * Prøver først Binance-data, deretter paper trading
 */
export async function getPortfolioOverview(userId: string): Promise<PortfolioSummary | null> {
  try {
    const supabase = await createClient();

    // Sjekk om bruker har Binance API keys
    const { data: apiKeys } = await supabase
      .from('exchange_api_keys')
      .select('*')
      .eq('user_id', userId)
      .eq('exchange', 'binance')
      .eq('is_active', true)
      .single();

    // Hvis Binance-konto, prøv å hente Binance-balanser
    if (apiKeys) {
      const { data: binanceBalances } = await supabase
        .from('binance_balances')
        .select('*')
        .eq('user_id', userId)
        .gt('total', 0)
        .order('usd_value', { ascending: false });

      if (binanceBalances && binanceBalances.length > 0) {
        // Bruker har Binance-data
        const totalValue = binanceBalances.reduce((sum, b) => sum + safeNumber(b.usd_value), 0);
        const lastSynced = binanceBalances[0]?.updated_at || null;

        const mappedPositions: PortfolioPosition[] = binanceBalances.map((bal) => ({
          id: bal.id,
          symbol: bal.asset,
          quantity: safeNumber(bal.total),
          avgBuyPrice: 0, // Vi har ikke denne fra Binance spot
          currentPrice: safeNumber(bal.last_price),
          currentValue: safeNumber(bal.usd_value),
          unrealizedPnl: 0,
          unrealizedPnlPercent: 0,
          totalInvested: 0,
          lastUpdated: bal.updated_at,
          isReal: true,
        }));

        return {
          overview: {
            totalValue: Math.round(totalValue * 100) / 100,
            totalProfitAbs: 0,
            totalProfitPct: 0,
            dayChangeAbs: 0,
            dayChangePct: 0,
            totalInvested: 0,
            positionCount: binanceBalances.length,
            hasRealAccount: true,
            lastSynced,
          },
          positions: mappedPositions,
          hasData: true,
          dataSource: 'binance',
        };
      }
    }

    // Fallback til paper trading data
    const { data: positions, error } = await supabase
      .from('portfolios')
      .select('*')
      .eq('user_id', userId);

    if (error) {
      console.error('Error fetching portfolio:', error);
      return null;
    }

    if (!positions || positions.length === 0) {
      return {
        overview: {
          totalValue: 0,
          totalProfitAbs: 0,
          totalProfitPct: 0,
          dayChangeAbs: 0,
          dayChangePct: 0,
          totalInvested: 0,
          positionCount: 0,
          hasRealAccount: !!apiKeys,
          lastSynced: null,
        },
        positions: [],
        hasData: false,
        dataSource: 'none',
      };
    }

    // Beregn totalsummer for paper trading
    let totalValue = 0;
    let totalInvested = 0;
    let totalUnrealizedPnl = 0;

    const mappedPositions: PortfolioPosition[] = positions.map((pos) => {
      const positionValue = safeNumber(pos.current_value);
      const positionInvested = safeNumber(pos.total_invested);
      const positionPnl = safeNumber(pos.unrealized_pnl);

      totalValue += positionValue;
      totalInvested += positionInvested;
      totalUnrealizedPnl += positionPnl;

      return {
        id: pos.id,
        symbol: pos.symbol,
        quantity: safeNumber(pos.quantity),
        avgBuyPrice: safeNumber(pos.avg_buy_price),
        currentPrice: safeNumber(pos.current_price),
        currentValue: positionValue,
        unrealizedPnl: positionPnl,
        unrealizedPnlPercent: safeNumber(pos.unrealized_pnl_percent),
        totalInvested: positionInvested,
        lastUpdated: pos.last_updated,
        isReal: false,
      };
    });

    const totalProfitAbs = totalUnrealizedPnl;
    const totalProfitPct = calculatePercentChange(totalValue, totalInvested);

    return {
      overview: {
        totalValue: Math.round(totalValue * 100) / 100,
        totalProfitAbs: Math.round(totalProfitAbs * 100) / 100,
        totalProfitPct: Math.round(totalProfitPct * 100) / 100,
        dayChangeAbs: 0,
        dayChangePct: 0,
        totalInvested: Math.round(totalInvested * 100) / 100,
        positionCount: positions.length,
        hasRealAccount: !!apiKeys,
        lastSynced: null,
      },
      positions: mappedPositions.sort((a, b) => b.currentValue - a.currentValue),
      hasData: true,
      dataSource: 'paper',
    };
  } catch (err) {
    const error = err instanceof Error ? err : new Error('Unknown error');
    console.error('Unexpected error in getPortfolioOverview:', error);
    return null;
  }
}

/**
 * Synkroniser Binance data for bruker
 * Kalles fra API eller Edge Function
 */
export async function syncBinancePortfolio(userId: string): Promise<{ success: boolean; message: string; synced?: number }> {
  try {
    const supabase = await createClient();

    // Sjekk om bruker har API keys
    const { data: apiKeys } = await supabase
      .from('exchange_api_keys')
      .select('api_key_encrypted, api_secret_encrypted, is_testnet')
      .eq('user_id', userId)
      .eq('exchange', 'binance')
      .eq('is_active', true)
      .single();

    if (!apiKeys) {
      return { success: false, message: 'No Binance API keys found' };
    }

    // Logg sync-forsøk
    await supabase
      .from('binance_sync_log')
      .insert({
        user_id: userId,
        status: 'in_progress',
        message: 'Starting sync',
      });

    // Her ville vi kalle Binance API - dette må gjøres fra en Edge Function
    // for å ikke eksponere API secrets på client-side

    return { 
      success: true, 
      message: 'Sync initiated. Data will be updated shortly.',
      synced: 0
    };
  } catch (err) {
    console.error('Error syncing Binance portfolio:', err);
    return { success: false, message: 'Sync failed' };
  }
}

/**
 * Hent sync-logg for bruker
 */
export async function getBinanceSyncLog(userId: string, limit = 10) {
  const supabase = await createClient();

  const { data, error } = await supabase
    .from('binance_sync_log')
    .select('*')
    .eq('user_id', userId)
    .order('created_at', { ascending: false })
    .limit(limit);

  if (error) {
    console.error('Error fetching sync log:', error);
    return [];
  }

  return data || [];
}

